def _normalize_youtube_avoid_text(value: Any) -> str:
    text = str(value or "").lower()
    return re.sub(r"[^a-z0-9]+", " ", text).strip()


def filter_universe_level_youtube_avoids(
    avoid_sectors: List[Any],
) -> Tuple[List[str], List[str], List[str]]:
    """Drop broad small/mid-cap avoid labels before sector-level demotion."""
    filtered: List[str] = []
    dropped: List[str] = []
    matched_tokens: Set[str] = set()
    normalized_tokens = {
        token: _normalize_youtube_avoid_text(token)
        for token in UNIVERSE_LEVEL_AVOID_TOKENS
    }
    for raw_sector in avoid_sectors or []:
        label = str(raw_sector or "").strip().lower()
        normalized_label = _normalize_youtube_avoid_text(label)
        matches = [
            token
            for token, normalized_token in normalized_tokens.items()
            if normalized_token and normalized_token in normalized_label
        ]
        if matches:
            dropped.append(label)
            matched_tokens.update(matches)
        elif label:
            filtered.append(label)
    return filtered, dropped, sorted(matched_tokens)


