def _long_bracket_source_geometry_ok(
    *,
    entry_price: float,
    stop_loss: float,
    take_profit: float,
    min_gap_pct: float = 0.01,
) -> Tuple[bool, str]:
    """Producer-side gate: reject long candidates whose source-supplied
    bracket levels are explicitly broken.

    day-manager 2026-05-19 (H3): the repair guard at
    _sanitize_long_bracket_levels catches bad geometry but the upstream
    plan producer keeps emitting it (e.g. RVYL fires every cycle). The
    repair should be defense-in-depth; the producer should reject any
    long whose source explicitly provided a take_profit that is not
    strictly above entry by at least min_gap_pct, or a stop_loss that is
    not strictly below entry by the same margin.

    Missing levels (0.0) are NOT rejected here — those legitimately fall
    through to the defaults at the call site. Only explicitly bad data
    is filtered.

    Returns (ok, reason). reason is "" when ok.
    """
    if not math.isfinite(entry_price) or entry_price <= 0:
        return True, ""
    gap = float(min_gap_pct) if min_gap_pct > 0 else 0.01
    floor_target = entry_price * (1.0 + gap)
    ceil_stop = entry_price * (1.0 - gap)
    if take_profit > 0 and take_profit < floor_target:
        return False, (
            f"source_take_profit_not_above_entry "
            f"(tp={take_profit:.4f} <= entry={entry_price:.4f} "
            f"* (1+{gap:.3f}))"
        )
    if stop_loss > 0 and stop_loss > ceil_stop:
        return False, (
            f"source_stop_loss_not_below_entry "
            f"(stop={stop_loss:.4f} >= entry={entry_price:.4f} "
            f"* (1-{gap:.3f}))"
        )
    return True, ""


def _sanitize_long_bracket_levels(
    *,
    entry_price: float,
    stop_loss: float,
    take_profit: float,
    reference_entry_price: float = 0.0,
    fallback_stop_pct: float = 0.05,
    fallback_target_pct: float = 0.10,
) -> Tuple[float, float, Dict[str, Any]]:
    """Ensure long-entry bracket levels are executable around the entry price."""
    metadata: Dict[str, Any] = {"repaired": False, "reasons": []}
    if not math.isfinite(entry_price) or entry_price <= 0:
        return stop_loss, take_profit, metadata

    reference = reference_entry_price if reference_entry_price > 0 else entry_price
    if not math.isfinite(reference):
        reference = entry_price

    if not math.isfinite(stop_loss) or stop_loss <= 0 or stop_loss >= entry_price:
        if reference > 0 and math.isfinite(stop_loss) and 0 < stop_loss < reference:
            stop_pct = (reference - stop_loss) / reference
        else:
            stop_pct = fallback_stop_pct
        stop_pct = min(max(stop_pct, 0.02), 0.20)
        stop_loss = entry_price * (1.0 - stop_pct)
        metadata["repaired"] = True
        metadata["reasons"].append("stop_loss_not_below_entry")

    if not math.isfinite(take_profit) or take_profit <= 0 or take_profit <= entry_price:
        if reference > 0 and math.isfinite(take_profit) and take_profit > reference:
            target_pct = (take_profit - reference) / reference
        else:
            target_pct = fallback_target_pct
        target_pct = min(max(target_pct, 0.02), 0.50)
        take_profit = entry_price * (1.0 + target_pct)
        metadata["repaired"] = True
        metadata["reasons"].append("take_profit_not_above_entry")

    return round(float(stop_loss), 4), round(float(take_profit), 4), metadata


def _reprice_long_bracket_preserving_geometry(
    *,
    original_entry: float,
    new_entry: float,
    stop_loss: float,
    take_profit: float,
) -> Tuple[float, float]:
    """Move a long bracket with a repriced entry while preserving original pct risk/reward."""
    if (
        not math.isfinite(original_entry)
        or original_entry <= 0
        or not math.isfinite(new_entry)
        or new_entry <= 0
    ):
        return stop_loss, take_profit

    stop_pct = 0.0
    target_pct = 0.0
    if math.isfinite(stop_loss) and 0 < stop_loss < original_entry:
        stop_pct = (original_entry - stop_loss) / original_entry
    if math.isfinite(take_profit) and take_profit > original_entry:
        target_pct = (take_profit - original_entry) / original_entry

    if stop_pct <= 0 and target_pct <= 0:
        return stop_loss, take_profit

    if stop_pct <= 0:
        stop_pct = min(max(target_pct / 2.0, 0.02), 0.20)
    if target_pct <= 0:
        target_pct = min(max(stop_pct * 2.0, 0.02), 0.50)

    return (
        round(float(new_entry) * (1.0 - min(max(stop_pct, 0.02), 0.20)), 4),
        round(float(new_entry) * (1.0 + min(max(target_pct, 0.02), 0.50)), 4),
    )


