class MarketScheduler:
    """
    Time-aware market scheduler that knows what phase we're in.

    This is the BRAIN that decides what workflow to run based on time.
    The orchestrator doesn't need a server - it knows what to do.
    """

    def __init__(self, timezone: str = "US/Eastern"):
        self.logger = logging.getLogger("AutonomousAgent.MarketScheduler")
        self.timezone = timezone
        try:
            import pytz

            self.tz = pytz.timezone(timezone)
        except ImportError:
            self.tz = None
            self.logger.warning("pytz not installed, using local time")
        # User-tunable evening boundaries (ET decimal hours).
        # Unified evening pipeline defaults:
        # - PM workflow starts at 6:30 PM ET
        # - Overnight starts at 8:30 PM ET
        self.pm_workflow_start_et = float(
            os.environ.get("PM_WORKFLOW_START_ET", "18.5")
        )
        self.overnight_start_et = float(os.environ.get("OVERNIGHT_START_ET", "20.5"))
        if not (0.0 <= self.pm_workflow_start_et < 24.0):
            self.pm_workflow_start_et = 18.5
        if not (0.0 <= self.overnight_start_et <= 24.0):
            self.overnight_start_et = 20.5
        if self.overnight_start_et <= self.pm_workflow_start_et:
            self.overnight_start_et = min(24.0, self.pm_workflow_start_et + 0.5)

    def get_current_time(self) -> datetime:
        """Get current time in market timezone."""
        if self.tz:
            return datetime.now(self.tz)
        return datetime.now()

    def get_market_phase(self) -> MarketPhase:
        """Determine current market phase based on time."""
        now = self.get_current_time()
        hour = now.hour
        minute = now.minute
        time_decimal = hour + minute / 60

        # Check if weekend.
        if now.weekday() >= 5:  # Saturday = 5, Sunday = 6
            # Sunday evening refresh window: treat as overnight session kickoff.
            if now.weekday() == 6 and time_decimal >= 18.0:
                return MarketPhase.OVERNIGHT
            # Weekend daytime: treat as after-hours/PM workflow for Monday prep
            if is_weekend_daytime(now):
                return MarketPhase.PM_WORKFLOW
            return MarketPhase.OVERNIGHT

        # Check if market holiday (e.g., Presidents' Day, MLK Day, etc.)
        try:
            from autotrade.utils.data_quality import DataQualityGate

            if not DataQualityGate().is_trading_day(
                now.date() if hasattr(now, "date") else now
            ):
                logger.info(
                    f"[PHASE] Market holiday detected ({now.strftime('%Y-%m-%d')}). Staying in OVERNIGHT/PM_WORKFLOW mode."
                )
                # Evening on a holiday: allow PM_WORKFLOW for next-day prep
                if time_decimal >= self.pm_workflow_start_et:
                    return MarketPhase.PM_WORKFLOW
                if time_decimal >= self.overnight_start_et or time_decimal < 4:
                    return MarketPhase.OVERNIGHT
                # Daytime on holiday: stay in OVERNIGHT (no trading)
                return MarketPhase.OVERNIGHT
        except Exception as e:
            logger.warning(
                f"[PHASE] Holiday check failed: {e}. Proceeding with time-based logic."
            )

        # Time-based phase detection (all times ET)
        if (
            time_decimal >= self.overnight_start_et or time_decimal < 4
        ):  # overnight window
            return MarketPhase.OVERNIGHT
        elif 4 <= hour < 7:  # 4 AM - 7 AM
            return MarketPhase.EARLY_PREMARKET
        elif 7 <= time_decimal < 9.5:  # 7 AM - 9:30 AM
            return MarketPhase.PREMARKET
        elif 9.5 <= time_decimal < 9.75:  # 9:30 AM - 9:45 AM (observation period)
            return MarketPhase.MARKET_OPEN
        elif 9.75 <= time_decimal < 15.5:  # 9:45 AM - 3:30 PM
            return MarketPhase.MARKET_HOURS
        elif 15.5 <= time_decimal < 16:  # 3:30 PM - 4:00 PM
            return MarketPhase.POWER_HOUR
        elif (
            16 <= time_decimal < self.pm_workflow_start_et
        ):  # post market until PM workflow
            return MarketPhase.POST_MARKET
        elif self.pm_workflow_start_et <= time_decimal < self.overnight_start_et:
            return MarketPhase.PM_WORKFLOW
        else:
            return MarketPhase.OVERNIGHT

    def get_phase_actions(self, phase: MarketPhase) -> Dict:
        """Get recommended actions for each market phase."""
        if not isinstance(phase, MarketPhase):
            try:
                phase = MarketPhase(getattr(phase, "value", phase))
            except Exception:
                phase = MarketPhase.OVERNIGHT
        actions = {
            MarketPhase.OVERNIGHT: {
                "primary": "research",
                "description": "Research mode - optimize watchlist, analyze backtests",
                "interval_seconds": 300,  # 5 minutes
                "run_pm_workflow": False,
                "run_day_manager": False,
                "run_premarket": False,
            },
            MarketPhase.EARLY_PREMARKET: {
                "primary": "prepare",
                "description": "Early prep - download data, validate signals",
                "interval_seconds": 120,  # 2 minutes
                "run_pm_workflow": False,
                "run_day_manager": False,
                "run_premarket": False,
            },
            MarketPhase.PREMARKET: {
                "primary": "premarket_scan",
                "description": "PREMARKET - Run scans, validate picks, prepare orders",
                "interval_seconds": 60,  # 1 minute
                "run_pm_workflow": False,
                "run_day_manager": False,
                "run_premarket": True,
            },
            MarketPhase.MARKET_OPEN: {
                "primary": "market_open",
                "description": "MARKET OPEN - Execute plan, monitor closely",
                "interval_seconds": 30,  # 30 seconds - high frequency
                "run_pm_workflow": False,
                "run_day_manager": True,
                "run_premarket": False,
            },
            MarketPhase.MARKET_HOURS: {
                "primary": "day_manager",
                "description": "MARKET HOURS - Day manager active",
                "interval_seconds": 60,  # 1 minute
                "run_pm_workflow": False,
                "run_day_manager": True,
                "run_premarket": False,
            },
            MarketPhase.POWER_HOUR: {
                "primary": "power_hour",
                "description": "POWER HOUR - Final adjustments, close weak positions",
                "interval_seconds": 30,  # 30 seconds
                "run_pm_workflow": False,
                "run_day_manager": True,
                "run_premarket": False,
            },
            MarketPhase.MIDDAY_RESCAN: {
                "primary": "midday_rescan",
                "description": "MID-DAY RESCAN - Refreshing watchlist and strategy picks",
                "interval_seconds": 60,
                "run_pm_workflow": False,
                "run_day_manager": True,
                "run_premarket": True,
            },
            MarketPhase.POST_MARKET: {
                "primary": "post_market",
                "description": "POST MARKET - Wait for close data to settle",
                "interval_seconds": 180,  # 3 minutes
                "run_pm_workflow": False,
                "run_day_manager": False,
                "run_premarket": False,
            },
            MarketPhase.PM_WORKFLOW: {
                "primary": "pm_workflow",
                "description": "PM WORKFLOW - Run post-market analysis, generate signals",
                "interval_seconds": 300,  # 5 minutes (only runs once)
                "run_pm_workflow": True,
                "run_day_manager": False,
                "run_premarket": False,
            },
        }
        return actions.get(phase, actions[MarketPhase.OVERNIGHT])

    def should_run_workflow(self, workflow: str) -> bool:
        """Check if a specific workflow should run now."""
        phase = self.get_market_phase()
        actions = self.get_phase_actions(phase)

        if workflow == "pm_workflow":
            return actions.get("run_pm_workflow", False)
        elif workflow == "day_manager":
            return actions.get("run_day_manager", False)
        elif workflow == "premarket":
            return actions.get("run_premarket", False)
        return False

    def get_status(self) -> Dict:
        """Get current schedule status."""
        now = self.get_current_time()
        phase = self.get_market_phase()
        actions = self.get_phase_actions(phase)

        return {
            "current_time": now.strftime("%Y-%m-%d %H:%M:%S %Z"),
            "market_phase": phase.value,
            "primary_action": actions["primary"],
            "description": actions["description"],
            "interval_seconds": actions["interval_seconds"],
            "run_pm_workflow": actions["run_pm_workflow"],
            "run_day_manager": actions["run_day_manager"],
            "run_premarket": actions["run_premarket"],
            "is_weekend": now.weekday() >= 5,
        }


class ErrorDiagnoser:
    """
    Diagnoses errors in the trading system using LOCAL Ollama models.

    This is how the orchestrator fixes itself without human intervention.
    """

    def __init__(self):
        self.logger = logging.getLogger("AutonomousAgent.ErrorDiagnoser")
        self.ollama_url = "http://localhost:11434"
        self.error_history: List[Dict] = []
        self.max_history = 100

    def diagnose_error(self, error: Exception, context: str = "") -> Dict:
        """Diagnose an error and suggest fixes."""
        error_info = {
            "type": type(error).__name__,
            "message": str(error),
            "traceback": traceback.format_exc(),
            "context": context,
            "timestamp": datetime.now().isoformat(),
        }

        # Store in history
        self.error_history.append(error_info)
        if len(self.error_history) > self.max_history:
            self.error_history = self.error_history[-self.max_history :]

        # Common error patterns - quick diagnosis
        quick_fix = self._quick_diagnosis(error_info)
        if quick_fix:
            error_info["diagnosis"] = quick_fix
            error_info["source"] = "pattern_match"
            return error_info

        # Use Ollama for complex diagnosis
        try:
            diagnosis = self._ollama_diagnosis(error_info)
            error_info["diagnosis"] = diagnosis
            error_info["source"] = "ollama"
        except Exception as e:
            error_info["diagnosis"] = {
                "issue": f"Diagnosis failed: {e}",
                "fix": "Check error manually",
                "severity": "unknown",
            }
            error_info["source"] = "fallback"

        return error_info

    def _quick_diagnosis(self, error_info: Dict) -> Optional[Dict]:
        """Quick pattern-based diagnosis for common errors."""
        error_type = error_info["type"]
        message = error_info["message"].lower()

        patterns = {
            # API errors
            ("APIError", "429"): {
                "issue": "Rate limit exceeded",
                "fix": "Wait 60 seconds before retrying",
                "severity": "low",
                "auto_fix": "sleep_60",
            },
            ("APIError", "401"): {
                "issue": "Invalid API credentials",
                "fix": "Check ALPACA_API_KEY and ALPACA_SECRET_KEY in .env",
                "severity": "critical",
                "auto_fix": None,
            },
            ("ConnectionError", "connection refused"): {
                "issue": "Service not running",
                "fix": "Start required service (Ollama/SearXNG)",
                "severity": "high",
                "auto_fix": "check_services",
            },
            # Data errors
            ("KeyError", ""): {
                "issue": "Missing data field",
                "fix": "Check data structure matches expected schema",
                "severity": "medium",
                "auto_fix": None,
            },
            ("ValueError", "could not convert"): {
                "issue": "Invalid data type",
                "fix": "Validate input data before processing",
                "severity": "medium",
                "auto_fix": None,
            },
            # Import errors
            ("ImportError", ""): {
                "issue": "Missing package",
                "fix": "Install missing package with pip/conda",
                "severity": "high",
                "auto_fix": "install_package",
            },
            ("ModuleNotFoundError", ""): {
                "issue": "Missing module",
                "fix": "Check PYTHONPATH or install package",
                "severity": "high",
                "auto_fix": "install_package",
            },
        }

        for (err_type, keyword), diagnosis in patterns.items():
            if error_type == err_type or err_type.lower() in error_type.lower():
                if not keyword or keyword in message:
                    return diagnosis

        return None

    def _ollama_diagnosis(self, error_info: Dict) -> Dict:
        """Use Ollama for complex error diagnosis."""
        import requests

        prompt = f"""/no_think
You are a Python debugging expert. Diagnose this error:

Error Type: {error_info["type"]}
Message: {error_info["message"]}
Context: {error_info["context"]}

Traceback:
{error_info["traceback"][:1500]}

Return ONLY JSON:
{{"issue": "one-line description", "fix": "specific fix action", "severity": "low/medium/high/critical", "code_fix": "code snippet if applicable or null"}}"""

        try:
            response = requests.post(
                f"{self.ollama_url}/api/chat",
                json={
                    "model": "qwen3:8b",
                    "messages": [{"role": "user", "content": prompt}],
                    "stream": False,
                    "think": False,
                    "options": {"num_predict": 300},
                },
                timeout=30,
            )

            if response.status_code == 200:
                content = response.json().get("message", {}).get("content", "")
                # Extract JSON
                start = content.find("{")
                if start >= 0:
                    depth = 0
                    for i, c in enumerate(content[start:]):
                        if c == "{":
                            depth += 1
                        elif c == "}":
                            depth -= 1
                            if depth == 0:
                                return json.loads(content[start : start + i + 1])

            return {"issue": "Unknown", "fix": "Check manually", "severity": "unknown"}

        except Exception as e:
            return {"issue": str(e), "fix": "Ollama unavailable", "severity": "unknown"}

    def get_error_summary(self) -> Dict:
        """Get summary of recent errors."""
        if not self.error_history:
            return {"total_errors": 0, "by_type": {}, "recent": []}

        by_type = {}
        for err in self.error_history:
            err_type = err["type"]
            by_type[err_type] = by_type.get(err_type, 0) + 1

        return {
            "total_errors": len(self.error_history),
            "by_type": by_type,
            "recent": self.error_history[-5:],
        }

    def check_services(self) -> Dict:
        """Check if required services are running."""
        import requests

        services = {
            "ollama": {"url": "http://localhost:11434/api/tags", "required": True},
            "searxng": {"url": "http://localhost:8080/healthz", "required": False},
        }

        status = {}
        for name, config in services.items():
            try:
                response = requests.get(config["url"], timeout=5)
                status[name] = {
                    "running": response.status_code == 200,
                    "required": config["required"],
                }
            except Exception:
                status[name] = {
                    "running": False,
                    "required": config["required"],
                }

        return status


class DataFetcher:
    """
    Fetches stock data with priority:
    1. LocalDataProvider (DownDay parquet) - fastest, 4453 tickers
    2. yfinance API - fallback for missing/real-time data
    """

    def __init__(self):
        self.logger = logging.getLogger("AutonomousAgent.DataFetcher")
        self._local_provider = None
        self._yf_available = False

        # Try to load LocalDataProvider
        try:
            from autotrade.utils.local_data_provider import get_provider

            self._local_provider = get_provider()
            self.logger.info(
                f"DataFetcher: LocalDataProvider active "
                f"({self._local_provider.get_stats().get('ticker_count', 0)} tickers)"
            )
        except ImportError as e:
            self.logger.warning(f"LocalDataProvider not available: {e}")

        # Check yfinance availability
        try:
            import yfinance as yf

            self.yf = yf
            self._yf_available = True
        except ImportError:
            self.logger.warning("yfinance not available")

    @property
    def available(self) -> bool:
        """Check if any data source is available."""
        return self._local_provider is not None or self._yf_available

    def has_local_data(self, ticker: str) -> bool:
        """Check if ticker has local data."""
        if self._local_provider:
            return self._local_provider.has_ticker(ticker.upper())
        return False

    def get_missing_tickers(self, tickers: List[str]) -> List[str]:
        """Find tickers missing from local market data."""
        cleaned: List[str] = []
        seen: set[str] = set()
        for ticker in tickers or []:
            symbol = str(ticker or "").upper().strip()
            if not symbol or symbol in seen:
                continue
            seen.add(symbol)
            cleaned.append(symbol)

        if not cleaned:
            return []

        # Predictions DB freshness checks are deprecated.
        if not self._local_provider:
            return cleaned
        return [
            symbol for symbol in cleaned if not self._local_provider.has_ticker(symbol)
        ]

    def fetch_ticker_data(self, ticker: str, period: str = "1mo") -> Optional[Dict]:
        """
        Fetch OHLCV data for a ticker.

        Priority:
        1. LocalDataProvider (if ticker available)
        2. yfinance API (fallback)
        """
        ticker = ticker.upper()

        # Map period to days
        period_days = {
            "1d": 1,
            "5d": 5,
            "1mo": 30,
            "3mo": 90,
            "6mo": 180,
            "1y": 365,
            "2y": 730,
        }
        days = period_days.get(period, 30)

        # Try LocalDataProvider first
        if self._local_provider and self._local_provider.has_ticker(ticker):
            try:
                df = self._local_provider.get_ticker_data(ticker, days=days)
                if df is not None and not df.empty:
                    return self._df_to_data_dict(df, ticker)
            except Exception as e:
                self.logger.debug(f"Local data failed for {ticker}: {e}")

        # Fallback to yfinance
        return self._fetch_from_yfinance(ticker, period)

    def _df_to_data_dict(self, df, ticker: str) -> Optional[Dict]:
        """Convert DataFrame to data dictionary."""
        if df is None or df.empty:
            return None

        try:

            def _safe_float(value):
                """Convert numeric-like values to float; return None for null/NaN."""
                if value is None:
                    return None
                try:
                    # NaN is the only value that is not equal to itself.
                    if value != value:
                        return None
                except Exception:
                    pass
                try:
                    return float(value)
                except Exception:
                    return None

            latest = df.iloc[-1]
            prev = df.iloc[-2] if len(df) > 1 else latest

            close_col = "Adj Close" if "Adj Close" in df.columns else "Close"

            data = {
                "ticker": ticker,
                "close": float(latest[close_col]),
                "open": float(latest.get("Open", latest[close_col])),
                "high": float(latest.get("High", latest[close_col])),
                "low": float(latest.get("Low", latest[close_col])),
                "volume": int(latest.get("Volume", 0)),
                "prev_close": float(prev[close_col]),
                "change_pct": (latest[close_col] - prev[close_col])
                / prev[close_col]
                * 100,
                "fetched_at": datetime.now().isoformat(),
                "source": "local",
            }

            # Include pre-computed features if available
            for feat in ["SMA_10", "SMA_20", "EMA_10", "EMA_20", "RSI_14", "MACD"]:
                if feat in latest.index:
                    data[feat.lower()] = _safe_float(latest[feat])

            self.logger.debug(f"Fetched {ticker} from local: ${data['close']:.2f}")
            return data

        except Exception as e:
            self.logger.warning(f"Failed to convert local data for {ticker}: {e}")
            return None

    def _fetch_from_yfinance(self, ticker: str, period: str = "1mo") -> Optional[Dict]:
        """Fetch data from yfinance (fallback)."""
        if not self._yf_available:
            return None

        try:
            stock = self.yf.Ticker(ticker)
            hist = stock.history(period=period)

            if hist.empty:
                self.logger.warning(f"No yfinance data for {ticker}")
                return None

            latest = hist.iloc[-1]
            prev = hist.iloc[-2] if len(hist) > 1 else latest

            data = {
                "ticker": ticker,
                "close": float(latest["Close"]),
                "open": float(latest["Open"]),
                "high": float(latest["High"]),
                "low": float(latest["Low"]),
                "volume": int(latest["Volume"]),
                "prev_close": float(prev["Close"]),
                "change_pct": (latest["Close"] - prev["Close"]) / prev["Close"] * 100,
                "fetched_at": datetime.now().isoformat(),
                "source": "yfinance",
            }

            # Calculate ATR if enough data
            if len(hist) >= 14:
                tr = []
                for i in range(1, len(hist)):
                    high_val = hist.iloc[i]["High"]
                    low_val = hist.iloc[i]["Low"]
                    prev_close = hist.iloc[i - 1]["Close"]
                    tr.append(
                        max(
                            high_val - low_val,
                            abs(high_val - prev_close),
                            abs(low_val - prev_close),
                        )
                    )
                data["atr_14"] = sum(tr[-14:]) / 14

            # Get additional info
            try:
                info = stock.info
                data["sector"] = info.get("sector", "Unknown")
                data["industry"] = info.get("industry", "Unknown")
                data["market_cap"] = info.get("marketCap", 0)
                data["avg_volume"] = info.get("averageVolume", 0)
            except Exception:
                pass

            self.logger.info(f"Fetched {ticker} from yfinance: ${data['close']:.2f}")
            return data

        except Exception as e:
            self.logger.error(f"Failed to fetch {ticker} from yfinance: {e}")
            return None

    def bulk_fetch(self, tickers: List[str], max_concurrent: int = 5) -> List[Dict]:
        """Fetch data for multiple tickers."""
        results = []

        # Separate local vs API tickers
        local_tickers = []
        api_tickers = []

        for ticker in tickers:
            if self.has_local_data(ticker):
                local_tickers.append(ticker)
            else:
                api_tickers.append(ticker)

        self.logger.info(
            f"Bulk fetch: {len(local_tickers)} local, {len(api_tickers)} API"
        )

        # Fetch local tickers (fast)
        for ticker in local_tickers:
            data = self.fetch_ticker_data(ticker)
            if data:
                results.append(data)

        # Fetch API tickers with rate limiting
        for i, ticker in enumerate(api_tickers):
            data = self._fetch_from_yfinance(ticker)
            if data:
                results.append(data)

            # Rate limiting for API calls
            if (i + 1) % max_concurrent == 0:
                time.sleep(1)

        return results


class WebResearcher:
    """
    Performs web research using SearXNG with CACHING.

    Cache prevents redundant searches:
    - News articles cached for 4 hours
    - Stock research cached for 2 hours
    - Sentiment analysis cached until next search
    """

    # In-memory cache with TTL
    _cache: Dict[str, Dict] = {}
    _cache_ttl: Dict[str, datetime] = {}

    def __init__(self, cache_dir: Path = None):
        self.logger = logging.getLogger("AutonomousAgent.WebResearcher")
        self.searxng_url = os.environ.get("SEARXNG_URL", "http://localhost:8080")

        # Cache directory for persistent storage
        self.cache_dir = cache_dir or LOG_DIR / "research_cache"
        self.cache_dir.mkdir(exist_ok=True)

        # Load existing cache from disk
        self._load_cache()

        # Check for OpenAI
        self.openai_key = os.environ.get("OPENAI_API_KEY")
        self.openai_client = None
        self.logger.info(
            "WebResearcher initialized (OpenAI disabled - using local models)"
        )

        # Date keywords for freshness validation
        self.current_month = datetime.now().strftime("%B")
        self.current_year = str(datetime.now().year)

    def _load_cache(self):
        """Load cache from disk on startup."""
        cache_file = self.cache_dir / "research_cache.json"
        if cache_file.exists():
            try:
                with open(cache_file) as f:
                    data = json.load(f)
                # Only load entries less than 4 hours old
                cutoff = datetime.now() - timedelta(hours=4)
                for key, value in data.items():
                    cached_at = datetime.fromisoformat(
                        value.get("_cached_at", "2000-01-01")
                    )
                    if cached_at > cutoff:
                        WebResearcher._cache[key] = value
                        WebResearcher._cache_ttl[key] = cached_at
                self.logger.info(
                    f"Loaded {len(WebResearcher._cache)} cached research entries"
                )
            except Exception as e:
                self.logger.warning(f"Failed to load cache: {e}")

    def _save_cache(self):
        """Save cache to disk."""
        cache_file = self.cache_dir / "research_cache.json"
        try:
            with open(cache_file, "w") as f:
                json.dump(WebResearcher._cache, f, indent=2, default=str)
        except Exception as e:
            self.logger.warning(f"Failed to save cache: {e}")

    def _get_cached(self, key: str, max_age_hours: float = 2.0) -> Optional[Dict]:
        """Get cached result if not expired."""
        if key in WebResearcher._cache:
            cached_at = WebResearcher._cache_ttl.get(key, datetime.min)
            if datetime.now() - cached_at < timedelta(hours=max_age_hours):
                self.logger.debug(f"Cache HIT: {key}")
                return WebResearcher._cache[key]
            else:
                self.logger.debug(f"Cache EXPIRED: {key}")
        return None

    def _set_cached(self, key: str, value: Dict):
        """Cache a result."""
        value["_cached_at"] = datetime.now().isoformat()
        WebResearcher._cache[key] = value
        WebResearcher._cache_ttl[key] = datetime.now()
        self._save_cache()
        self.logger.debug(f"Cached: {key}")

    def _get_openai_client(self):
        """Lazy-load OpenAI client ONLY when absolutely needed (last resort)."""
        if self.openai_client is None and self.openai_key:
            try:
                from openai import OpenAI

                self.openai_client = OpenAI(api_key=self.openai_key)
                self.logger.warning("OpenAI client loaded (last resort)")
            except ImportError:
                pass
        return self.openai_client

    def _validate_article_freshness(
        self, articles: List[Dict]
    ) -> Tuple[List[Dict], bool]:
        """
        Validate article freshness - check if articles are current.

        Returns:
            (filtered_articles, is_fresh) - Fresh articles and whether results are current
        """
        fresh_articles = []
        stale_count = 0

        # Current date context
        today = datetime.now()
        current_year = today.year
        current_month = today.month

        # Month names for matching
        months = [
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "August",
            "September",
            "October",
            "November",
            "December",
        ]
        current_month_name = months[current_month - 1]
        prev_month_name = months[current_month - 2] if current_month > 1 else "December"

        for article in articles:
            title = article.get("title", "")
            content = article.get("content", "")
            text = f"{title} {content}".lower()

            # Check for current date indicators
            is_fresh = False

            # Check for current year
            if str(current_year) in text:
                is_fresh = True

            # Check for "today", "yesterday", time indicators
            if any(
                word in text
                for word in [
                    "today",
                    "yesterday",
                    "hours ago",
                    "minutes ago",
                    "just now",
                ]
            ):
                is_fresh = True

            # Check for current or previous month
            if current_month_name.lower() in text or prev_month_name.lower() in text:
                is_fresh = True

            # Check for quarter references (Q1 2026 = Jan-Mar 2026)
            quarter_mapping = {
                "q1": [1, 2, 3],
                "q2": [4, 5, 6],
                "q3": [7, 8, 9],
                "q4": [10, 11, 12],
            }
            for quarter, months_range in quarter_mapping.items():
                if quarter in text and str(current_year) in text:
                    if (
                        current_month in months_range
                        or current_month == months_range[-1] + 1
                    ):
                        is_fresh = True
                        break

            if is_fresh:
                fresh_articles.append(article)
            else:
                stale_count += 1

        # Consider results "fresh" if at least 40% are current
        is_fresh_overall = (
            len(fresh_articles) >= len(articles) * 0.4 if articles else False
        )

        if stale_count > 0:
            self.logger.debug(
                f"Filtered {stale_count} stale articles, {len(fresh_articles)} fresh"
            )

        return fresh_articles, is_fresh_overall

    def _filter_relevance(self, results: List[Dict], symbol: str = None) -> List[Dict]:
        """
        Filter search results for relevance to stock/trading.

        Removes:
        - Social media clutter (reddit threads, twitter spam)
        - Unrelated pages (shopping, forums, random blogs)
        - Results that don't mention the target symbol
        """
        relevant = []

        # Domains to deprioritize (not block, just score lower)
        low_quality_domains = [
            "reddit.com",
            "twitter.com",
            "facebook.com",
            "tiktok.com",
            "pinterest.com",
            "instagram.com",
            "amazon.com",
            "ebay.com",
        ]

        # Keywords that indicate financial relevance
        financial_keywords = [
            "stock",
            "share",
            "price",
            "earnings",
            "revenue",
            "market",
            "investor",
            "trading",
            "analyst",
            "forecast",
            "guidance",
            "quarterly",
            "dividend",
            "sec",
            "filing",
            "eps",
            "nasdaq",
            "nyse",
        ]

        for result in results:
            url = result.get("url", "").lower()
            title = result.get("title", "").lower()
            content = result.get("content", "").lower()
            combined = f"{title} {content}"

            # Score each result
            score = 0

            # Check if symbol is mentioned (if provided)
            if symbol:
                symbol_lower = symbol.lower()
                if symbol_lower in title:
                    score += 3  # Strong signal
                elif symbol_lower in content:
                    score += 1
                else:
                    score -= 2  # Doesn't mention the stock at all

            # Check for financial relevance
            keyword_hits = sum(1 for kw in financial_keywords if kw in combined)
            score += min(keyword_hits, 3)  # Cap at 3 points

            # Penalize low-quality domains
            if any(domain in url for domain in low_quality_domains):
                score -= 2

            # Quality domains get bonus
            quality_domains = [
                "reuters.com",
                "bloomberg.com",
                "wsj.com",
                "cnbc.com",
                "marketwatch.com",
                "seekingalpha.com",
                "finance.yahoo.com",
                "investors.com",
                "barrons.com",
                "fool.com",
            ]
            if any(domain in url for domain in quality_domains):
                score += 2

            result["_relevance_score"] = score
            if score >= 0:  # Only include if score is non-negative
                relevant.append(result)

        # Sort by relevance score
        relevant.sort(key=lambda x: x.get("_relevance_score", 0), reverse=True)

        return relevant

    def search_web(
        self,
        query: str,
        max_results: int = 5,
        require_fresh: bool = True,
        symbol: str = None,
    ) -> List[Dict]:
        """Search the web using SearXNG with caching, freshness and relevance validation."""
        import requests

        # Extract symbol from query if not provided
        if not symbol:
            # Try to find a ticker pattern (1-5 uppercase letters)
            import re

            ticker_match = re.search(r"\b([A-Z]{1,5})\b", query)
            if ticker_match:
                symbol = ticker_match.group(1)

        # Check cache first (1 hour TTL for web searches)
        cache_key = f"web:{query}:{symbol or 'none'}"
        cached = self._get_cached(cache_key, max_age_hours=1.0)
        if cached:
            self.logger.info(f"Using cached search results for: {query[:50]}...")
            return cached.get("results", [])[:max_results]

        try:
            # First search attempt
            response = requests.get(
                f"{self.searxng_url}/search",
                params={
                    "q": query,
                    "format": "json",
                    "categories": "general,news",
                    "time_range": "week",  # Prefer recent results
                },
                timeout=15,
            )

            if response.status_code == 200:
                data = response.json()
                results = []
                for r in data.get("results", [])[
                    : max_results * 3
                ]:  # Get extra for filtering
                    results.append(
                        {
                            "title": r.get("title", ""),
                            "url": r.get("url", ""),
                            "content": r.get("content", "")[:500],
                            "engine": r.get("engine", ""),
                            "publishedDate": r.get("publishedDate", ""),
                        }
                    )

                # Filter for relevance first
                relevant_results = self._filter_relevance(results, symbol)
                self.logger.debug(
                    f"Relevance filtered: {len(results)} -> {len(relevant_results)}"
                )

                # Then validate freshness
                if require_fresh:
                    fresh_results, is_fresh = self._validate_article_freshness(
                        relevant_results
                    )

                    # If not enough fresh results, try with date in query
                    if not is_fresh and len(fresh_results) < 2:
                        self.logger.info("Results stale, retrying with date context...")
                        date_query = f"{query} {self.current_month} {self.current_year}"
                        return self._search_with_date(date_query, max_results, symbol)

                    # Cache the fresh results
                    self._set_cached(
                        cache_key, {"results": fresh_results, "query": query}
                    )
                    return fresh_results[:max_results]

                # Cache relevant results
                self._set_cached(
                    cache_key, {"results": relevant_results, "query": query}
                )
                return relevant_results[:max_results]
            else:
                self.logger.warning(f"SearXNG returned {response.status_code}")
                return []

        except Exception as e:
            self.logger.error(f"Web search failed: {e}")
            return []

    def _search_with_date(
        self, query: str, max_results: int, symbol: str = None
    ) -> List[Dict]:
        """Fallback search with explicit date context."""
        import requests

        try:
            response = requests.get(
                f"{self.searxng_url}/search",
                params={
                    "q": query,
                    "format": "json",
                    "categories": "news",  # News only for date-specific
                    "time_range": "month",
                },
                timeout=15,
            )

            if response.status_code == 200:
                data = response.json()
                results = []
                for r in data.get("results", [])[: max_results * 2]:
                    results.append(
                        {
                            "title": r.get("title", ""),
                            "url": r.get("url", ""),
                            "content": r.get("content", "")[:500],
                            "engine": r.get("engine", ""),
                            "publishedDate": r.get("publishedDate", ""),
                            "date_filtered": True,  # Mark as date-filtered result
                        }
                    )
                # Apply relevance filtering
                filtered = self._filter_relevance(results, symbol)
                return filtered[:max_results]
            return []
        except Exception:
            return []

    def _analyze_with_ollama(self, symbol: str, news: List[Dict]) -> Dict:
        """Use LOCAL Ollama model for sentiment analysis (preferred over OpenAI)."""
        if not news:
            return {
                "sentiment": "neutral",
                "confidence": 0,
                "analysis": "No news found",
            }

        news_text = "\n".join(
            [f"- {n['title']}: {n.get('content', '')[:200]}" for n in news[:5]]
        )

        prompt = f"""Analyze the sentiment for {symbol} based on this news:

{news_text}

Respond with ONLY a JSON object:
{{"sentiment": "bullish" or "neutral" or "bearish", "confidence": 0-100, "analysis": "brief 1-sentence summary"}}"""

        try:
            import requests

            response = requests.post(
                "http://localhost:11434/api/chat",
                json={
                    "model": "qwen3:8b",  # Fast local model
                    "messages": [{"role": "user", "content": prompt}],
                    "stream": False,
                    "think": False,  # Disable qwen3 extended thinking mode
                    "options": {"num_predict": 150},
                },
                timeout=30,
            )

            if response.status_code == 200:
                content = response.json().get("message", {}).get("content", "")
                # Extract JSON from response
                import re

                json_match = re.search(r"\{[^}]+\}", content)
                if json_match:
                    return json.loads(json_match.group())

            return {
                "sentiment": "neutral",
                "confidence": 50,
                "analysis": "Analysis incomplete",
            }

        except Exception as e:
            self.logger.debug(f"Ollama analysis failed: {e}")
            return {"sentiment": "neutral", "confidence": 0, "analysis": str(e)}

    def research_stock(self, symbol: str) -> Dict:
        """Research a specific stock using LOCAL models (OpenAI as last resort only)."""
        # Check cache first (2 hour TTL for full stock research)
        cache_key = f"stock:{symbol}"
        cached = self._get_cached(cache_key, max_age_hours=2.0)
        if cached:
            self.logger.info(f"Using cached research for {symbol}")
            return cached

        results = {
            "symbol": symbol,
            "news": [],
            "fresh_news": True,
            "sentiment": "neutral",
            "confidence": 0,
            "catalysts": [],
            "risks": [],
            "researched_at": datetime.now().isoformat(),
            "model_used": "ollama",  # Track which model was used
        }

        # Search for recent news with freshness validation
        news_results = self.search_web(f"{symbol} stock news today", require_fresh=True)
        results["news"] = news_results
        results["fresh_news"] = len(news_results) > 0

        # Search for catalysts
        catalyst_results = self.search_web(
            f"{symbol} earnings FDA catalyst announcement", require_fresh=True
        )
        for r in catalyst_results:
            if any(
                kw in r["content"].lower()
                for kw in ["earnings", "fda", "approval", "announcement"]
            ):
                results["catalysts"].append(r["title"])

        # Use LOCAL Ollama model for analysis (NOT OpenAI)
        if news_results:
            analysis = self._analyze_with_ollama(symbol, news_results)
            results["sentiment"] = analysis.get("sentiment", "neutral")
            results["confidence"] = analysis.get("confidence", 0)
            results["analysis"] = analysis.get("analysis", "")
            results["model_used"] = "ollama"

        # Cache the research results
        self._set_cached(cache_key, results)
        return results


class WatchlistOptimizer:
    """Optimizes watchlist selection using LOCAL Ollama models (OpenAI as last resort)."""

    def __init__(self):
        self.logger = logging.getLogger("AutonomousAgent.WatchlistOptimizer")
        # OpenAI is last resort - don't initialize eagerly
        self.openai_key = os.environ.get("OPENAI_API_KEY")
        self.openai_client = None  # Will only load if Ollama fails

    def _get_openai_client(self):
        """Lazy-load OpenAI ONLY as last resort."""
        if self.openai_client is None and self.openai_key:
            try:
                from openai import OpenAI

                self.openai_client = OpenAI(api_key=self.openai_key)
                self.logger.warning("OpenAI loaded as LAST RESORT fallback")
            except ImportError:
                pass
        return self.openai_client

    def analyze_current_picks(self, plan_path: Path) -> Dict:
        """Analyze the current PM plan picks for quality."""
        if not plan_path.exists():
            return {"error": "Plan not found"}

        # Load plan with automatic migration to canonical schema
        try:
            from autotrade.utils.plan_schema_validator import load_and_migrate_plan

            plan = load_and_migrate_plan(str(plan_path))
            # CANONICAL: Always use 'signals' key after migration
            signals = plan.get("signals", [])
            self.logger.info(
                f"Loaded plan with {len(signals)} signals (migrated schema)"
            )
        except Exception as e:
            self.logger.warning(f"Migration failed, using fallback: {e}")
            with open(plan_path) as f:
                plan = json.load(f)
            # Fallback: Try canonical 'signals' first, then legacy keys
            signals = plan.get(
                "signals", plan.get("buy_signals", plan.get("entry_candidates", []))
            )

        analysis = {
            "plan_date": plan.get("generated_at", ""),
            "position_count": len(plan.get("positions", [])),
            "signals": signals,
            "issues": [],
            "suggestions": [],
            "score": 0,
        }

        def _num(value: Any, default: float = 0.0) -> float:
            try:
                return float(value)
            except Exception:
                return default

        def _calc_rr(sig: Dict[str, Any]) -> float:
            rr = _num(sig.get("risk_reward"), 0.0)
            if rr > 0:
                return rr
            entry = _num(
                sig.get("entry_price", sig.get("entry", sig.get("price"))), 0.0
            )
            stop = _num(
                sig.get("stop_loss", sig.get("stop", sig.get("stop_price"))), 0.0
            )
            target = _num(
                sig.get("target", sig.get("target_price", sig.get("take_profit"))), 0.0
            )
            risk = max(entry - stop, 0.0)
            reward = max(target - entry, 0.0)
            if entry > 0 and risk > 0 and reward > 0:
                return reward / risk
            return 0.0

        # Analyze signal quality
        score_values: List[float] = []
        rr_values: List[float] = []
        for sig in signals:
            score = _num(
                sig.get("final_score", sig.get("confidence", sig.get("score"))), 0.0
            )
            rr = _calc_rr(sig)
            score_values.append(score)
            if rr > 0:
                rr_values.append(rr)

            # Check for issues
            symbol = sig.get("symbol", sig.get("ticker", "?"))
            if rr > 0 and rr < 1.5:
                analysis["issues"].append(f"{symbol}: Poor R:R ratio ({rr:.1f})")
            if score < 40:
                analysis["issues"].append(f"{symbol}: Low score ({score:.0f})")

        # Calculate overall quality score
        if score_values:
            avg_score = sum(score_values) / len(score_values)
            avg_rr = (sum(rr_values) / len(rr_values)) if rr_values else 1.5
            analysis["score"] = avg_score * 0.6 + min(avg_rr * 20, 40)  # Max 100

        return analysis

    def optimize_with_ollama(
        self, signals: List[Dict], market_context: str = ""
    ) -> Dict:
        """Use LOCAL Ollama model to optimize watchlist (preferred over OpenAI)."""
        # Prepare signals for analysis
        signal_summary = []
        for s in signals[:15]:  # Top 15
            signal_summary.append(
                {
                    "symbol": s.get("symbol", s.get("ticker")),
                    "score": round(s.get("final_score", s.get("score", 0)), 1),
                    "rr": round(s.get("risk_reward", 0), 1),
                    "action": s.get("action", "watch"),
                }
            )

        prompt = f"""You are an expert day trader. Analyze these stock picks and optimize the watchlist.

Current picks:
{json.dumps(signal_summary, indent=2)}

Return ONLY a JSON object with:
{{"optimized_picks": ["SYM1", "SYM2", ...top 10 symbols], "reasoning": "brief explanation", "confidence": 0-100}}

Consider: risk/reward ratios, diversification, and momentum quality."""

        try:
            import requests

            response = requests.post(
                "http://localhost:11434/api/chat",
                json={
                    "model": "qwen3:8b",  # Use faster model (30b takes too long)
                    "messages": [{"role": "user", "content": prompt}],
                    "stream": False,
                    "think": False,  # Disable qwen3 extended thinking mode
                    "options": {"num_predict": 500},
                },
                timeout=45,
            )

            if response.status_code == 200:
                content = response.json().get("message", {}).get("content", "")
                self.logger.debug(f"Ollama response: {content[:200]}")

                # Extract JSON from response - handle nested braces

                # Find first { and match to closing }
                start = content.find("{")
                if start >= 0:
                    # Count braces to find matching close
                    depth = 0
                    for i, c in enumerate(content[start:]):
                        if c == "{":
                            depth += 1
                        elif c == "}":
                            depth -= 1
                            if depth == 0:
                                json_str = content[start : start + i + 1]
                                try:
                                    result = json.loads(json_str)
                                    if "optimized_picks" in result:
                                        result["model_used"] = "ollama"
                                        self.logger.info(
                                            f"Ollama optimization: {result.get('confidence', 0)}% confidence"
                                        )
                                        return result
                                except json.JSONDecodeError:
                                    pass
                                break

            # Fallback - return original order
            return {
                "optimized_picks": [s["symbol"] for s in signal_summary[:10]],
                "reasoning": "Using original ranking",
                "confidence": 50,
                "model_used": "fallback",
            }

        except Exception as e:
            self.logger.warning(f"Ollama optimization failed: {e}")
            return {
                "optimized_picks": [s["symbol"] for s in signal_summary[:10]],
                "reasoning": f"Ollama failed: {e}",
                "confidence": 30,
                "model_used": "fallback",
            }

    def optimize_with_openai(
        self, signals: List[Dict], market_context: str = ""
    ) -> Dict:
        """LAST RESORT: Use OpenAI only if Ollama fails completely."""
        # First try Ollama
        ollama_result = self.optimize_with_ollama(signals, market_context)
        if ollama_result.get("confidence", 0) >= 50:
            return ollama_result

        # Only use OpenAI if Ollama confidence is very low
        openai = self._get_openai_client()
        if not openai:
            return ollama_result  # Return Ollama result even if low confidence

        self.logger.warning("Ollama confidence low, trying OpenAI as LAST RESORT")

        # Prepare signals for analysis
        signal_summary = []
        for s in signals[:20]:  # Top 20
            signal_summary.append(
                {
                    "symbol": s.get("symbol", s.get("ticker")),
                    "price": s.get("price", s.get("current_price", 0)),
                    "score": s.get("final_score", s.get("score", 0)),
                    "rr": s.get("risk_reward", 0),
                    "action": s.get("action", "watch"),
                }
            )

        try:
            response = openai.chat.completions.create(
                model="gpt-4.1-mini",  # Use mini to save costs
                messages=[
                    {
                        "role": "system",
                        "content": """You are an expert day trader. Analyze these stock picks and return JSON with:
1. 'optimized_picks': Array of top 10 symbols, re-ranked by your analysis
2. 'reasoning': Brief explanation of your ranking logic
3. 'removed': Symbols you would remove and why
4. 'confidence': 0-100 confidence in this watchlist

Consider: risk/reward, sector diversity, momentum quality, and position sizing.""",
                    },
                    {
                        "role": "user",
                        "content": f"Market context: {market_context}\n\nCurrent picks:\n{json.dumps(signal_summary, indent=2)}",
                    },
                ],
                response_format={"type": "json_object"},
                max_tokens=500,
            )

            result = json.loads(response.choices[0].message.content)
            result["model_used"] = "openai_last_resort"
            self.logger.info(
                f"OpenAI (last resort) optimization complete: {result.get('confidence', 0)}% confidence"
            )
            return result

        except Exception as e:
            self.logger.error(f"OpenAI optimization failed: {e}")
            return ollama_result  # Fall back to Ollama result

    def update_watchlist(self, plan_path: Path, optimized: Dict) -> bool:
        """Update the PM plan with optimized picks."""
        if not plan_path.exists():
            return False

        with open(plan_path) as f:
            plan = json.load(f)

        # Add optimization metadata
        plan["optimization"] = {
            "optimized_at": datetime.now().isoformat(),
            "optimized_picks": optimized.get("optimized_picks", []),
            "reasoning": optimized.get("reasoning", ""),
            "confidence": optimized.get("confidence", 0),
            "removed": optimized.get("removed", []),
        }

        # Save updated plan
        with open(plan_path, "w") as f:
            json.dump(plan, f, indent=2)

        self.logger.info(f"Updated {plan_path.name} with optimization")
        return True


class BacktestAnalyzer:
    """Analyzes backtest results to find improvement opportunities."""

    def __init__(self):
        self.logger = logging.getLogger("AutonomousAgent.BacktestAnalyzer")
        try:
            self.run_registry = RunRegistry()
        except Exception:
            self.run_registry = None

    def get_recent_backtests(self, days: int = 7) -> List[Dict]:
        """Get recent backtest results from agentic logs + RunRegistry."""
        results = []
        cutoff = datetime.now() - timedelta(days=days)

        for f in LOG_DIR.glob("agentic_backtest_*.json"):
            try:
                # Parse date from filename
                date_str = f.stem.split("_")[2]  # agentic_backtest_YYYYMMDD_HHMMSS
                file_date = datetime.strptime(date_str, "%Y%m%d")

                if file_date >= cutoff:
                    with open(f) as fp:
                        data = json.load(fp)
                        data["file"] = f.name
                        results.append(data)
            except Exception:
                continue

        # Also pull recent runs from Stage 6 RunRegistry
        if self.run_registry:
            try:
                for run_id, run_data in self.run_registry.runs.items():
                    ts = run_data.get("timestamp", "")
                    if ts:
                        try:
                            run_dt = datetime.fromisoformat(
                                str(ts).replace("Z", "+00:00")
                            )
                            if run_dt.replace(tzinfo=None) >= cutoff:
                                run_data["file"] = f"registry:{run_id}"
                                results.append(run_data)
                        except Exception:
                            pass
            except Exception:
                pass

        return sorted(results, key=lambda x: x.get("file", ""), reverse=True)

    def analyze_patterns(self, backtests: List[Dict]) -> Dict:
        """Analyze backtest patterns to find improvements."""
        analysis = {
            "total_backtests": len(backtests),
            "avg_pnl": 0,
            "best_trades": [],
            "worst_trades": [],
            "patterns": [],
            "suggestions": [],
        }

        if not backtests:
            return analysis

        all_trades = []
        total_pnl = 0

        for bt in backtests:
            trades = bt.get("trades", [])
            all_trades.extend(trades)
            total_pnl += bt.get("total_pnl", 0)

        if all_trades:
            analysis["avg_pnl"] = total_pnl / len(backtests)

            # Sort by P&L
            sorted_trades = sorted(
                all_trades, key=lambda x: x.get("pnl_pct", 0), reverse=True
            )
            analysis["best_trades"] = sorted_trades[:5]
            analysis["worst_trades"] = sorted_trades[-5:]

            # Find patterns in winning trades
            winners = [t for t in all_trades if t.get("pnl_pct", 0) > 0]
            losers = [t for t in all_trades if t.get("pnl_pct", 0) < 0]

            if winners:
                avg_winner_rr = sum(t.get("risk_reward", 0) for t in winners) / len(
                    winners
                )
                analysis["patterns"].append(f"Avg winner R:R: {avg_winner_rr:.2f}")

            if losers:
                avg_loser_rr = sum(t.get("risk_reward", 0) for t in losers) / len(
                    losers
                )
                analysis["patterns"].append(f"Avg loser R:R: {avg_loser_rr:.2f}")

            # Generate suggestions
            if avg_winner_rr > 2.0:
                analysis["suggestions"].append(
                    "High R:R trades are winning - focus on setups with R:R > 2.0"
                )

            win_rate = len(winners) / len(all_trades) * 100 if all_trades else 0
            if win_rate < 50:
                analysis["suggestions"].append(
                    f"Win rate is {win_rate:.0f}% - consider tighter entry criteria"
                )

        return analysis


class CodeDebugger:
    """
    Debugs Python code using LOCAL Ollama models.

    Uses qwen3-coder for code analysis - NO OpenAI for debugging.
    """

    def __init__(self):
        self.logger = logging.getLogger("AutonomousAgent.CodeDebugger")
        self.ollama_url = "http://localhost:11434"

    def analyze_error(
        self, error_message: str, code_context: str = "", file_path: str = ""
    ) -> Dict:
        """
        Analyze a Python error and suggest fixes.

        Args:
            error_message: The error traceback
            code_context: Relevant code snippet
            file_path: Path to the file with error

        Returns:
            Dict with analysis, suggestion, and fixed_code
        """
        prompt = f"""/no_think
You are a Python debugging expert. Analyze this error and provide a fix.

Error:
{error_message}

{"Code context:" if code_context else ""}
{code_context}

{"File:" if file_path else ""}
{file_path}

Respond with JSON only:
{{"issue": "what's wrong", "suggestion": "how to fix", "fixed_code": "corrected code if applicable", "confidence": 0-100}}"""

        try:
            import requests

            response = requests.post(
                f"{self.ollama_url}/api/chat",
                json={
                    "model": "qwen3:8b",  # Use qwen3:8b for faster response
                    "messages": [{"role": "user", "content": prompt}],
                    "stream": False,
                    "think": False,
                    "options": {"num_predict": 800},
                },
                timeout=45,
            )

            if response.status_code == 200:
                content = response.json().get("message", {}).get("content", "")
                # Extract JSON
                start = content.find("{")
                if start >= 0:
                    depth = 0
                    for i, c in enumerate(content[start:]):
                        if c == "{":
                            depth += 1
                        elif c == "}":
                            depth -= 1
                            if depth == 0:
                                result = json.loads(content[start : start + i + 1])
                                result["model_used"] = "ollama"
                                return result

            return {
                "issue": "Analysis failed",
                "suggestion": "Check error manually",
                "confidence": 0,
            }

        except Exception as e:
            self.logger.error(f"Code debug failed: {e}")
            return {
                "issue": str(e),
                "suggestion": "Check error manually",
                "confidence": 0,
            }

    def validate_python_file(self, file_path: str) -> Dict:
        """Check a Python file for syntax errors."""
        import ast

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                code = f.read()

            ast.parse(code)
            return {"valid": True, "errors": []}

        except SyntaxError as e:
            return {
                "valid": False,
                "errors": [
                    {
                        "line": e.lineno,
                        "offset": e.offset,
                        "message": e.msg,
                        "text": e.text.strip() if e.text else "",
                    }
                ],
            }
        except Exception as e:
            return {"valid": False, "errors": [{"message": str(e)}]}

    def suggest_improvements(self, code: str, context: str = "trading bot") -> Dict:
        """Suggest code improvements using local model."""
        prompt = f"""/no_think
Review this Python code for a {context}. Suggest improvements for:
1. Error handling
2. Performance
3. Best practices

Code:
```python
{code[:2000]}
```

Respond with JSON only:
{{"improvements": ["improvement 1", "improvement 2"], "critical_issues": ["issue if any"], "score": 0-100}}"""

        try:
            import requests

            response = requests.post(
                f"{self.ollama_url}/api/chat",
                json={
                    "model": "qwen3:8b",
                    "messages": [{"role": "user", "content": prompt}],
                    "stream": False,
                    "think": False,
                    "options": {"num_predict": 500},
                },
                timeout=45,
            )

            if response.status_code == 200:
                content = response.json().get("message", {}).get("content", "")
                start = content.find("{")
                if start >= 0:
                    depth = 0
                    for i, c in enumerate(content[start:]):
                        if c == "{":
                            depth += 1
                        elif c == "}":
                            depth -= 1
                            if depth == 0:
                                return json.loads(content[start : start + i + 1])

            return {"improvements": [], "critical_issues": [], "score": 50}

        except Exception as e:
            return {"improvements": [], "critical_issues": [str(e)], "score": 0}


class TomorrowsPlanGenerator:
    """
    Generates actionable trade plans for tomorrow focused on MAKING MONEY.

    Core responsibilities:
    1. Detect odd lot positions (1-2 shares that need cleanup)
    2. Identify positions to close at open
    3. Identify new entries from PM plan
    4. Set specific prices, stops, and targets
    5. Generate ready-to-execute Alpaca orders

    This is about MONEY, not research for research's sake.
    """

    def __init__(self):
        self.logger = logging.getLogger("AutonomousAgent.TomorrowsPlan")
        self.alpaca_client = None
        self.market_data_client = None
        self._init_alpaca()
        self._load_config()
        # day-manager 2026-05-22 (H10): session-local skip set so a symbol whose
        # source plan ships malformed bracket geometry (e.g. RVYL tp<=entry)
        # only logs one WARNING per session instead of per-cycle noise.
        self._plan_producer_reject_silenced: set[str] = set()

    def _load_config(self):
        """Load trading config for position limits and sizing."""
        try:
            config_path = PROJECT_DIR / "config" / "trading_config.yaml"
            if config_path.exists():
                import yaml

                with open(config_path) as f:
                    config = yaml.safe_load(f)
                portfolio_config = config.get("portfolio", {})
                caps = resolve_position_caps(config=config)
                self.max_positions = caps.total_cap
                self.core_max_positions = caps.core_cap
                self.reserve_max_positions = caps.reserve_cap
                self.weak_day = caps.weak_day
                self.position_caps = caps.to_dict()
                self.position_size_target = portfolio_config.get(
                    "position_size_target", 3000
                )
                self.position_size_max = portfolio_config.get("position_size_max", 6000)
                self.logger.info(
                    f"Config: max_positions={self.max_positions}, core={self.core_max_positions}, "
                    f"reserve={self.reserve_max_positions}, position_size=${self.position_size_target}"
                )
            else:
                caps = resolve_position_caps(config={})
                self.max_positions = caps.total_cap
                self.core_max_positions = caps.core_cap
                self.reserve_max_positions = caps.reserve_cap
                self.weak_day = caps.weak_day
                self.position_caps = caps.to_dict()
                self.position_size_target = 3000
                self.position_size_max = 6000
        except Exception as e:
            self.logger.warning(f"Could not load config: {e}, using defaults")
            caps = resolve_position_caps(config={})
            self.max_positions = caps.total_cap
            self.core_max_positions = caps.core_cap
            self.reserve_max_positions = caps.reserve_cap
            self.weak_day = caps.weak_day
            self.position_caps = caps.to_dict()
            self.position_size_target = 3000
            self.position_size_max = 6000

    def _plan_entry_constraints(self, plan: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        """Return the active entry-constraint contract for a plan."""
        plan_payload = plan if isinstance(plan, dict) else {}
        return resolve_entry_constraints(
            plan_payload,
            failsafe={"max_positions": getattr(self, "max_positions", 40)},
            config=get_config(),
            alpha_router=dict(plan_payload.get("regime_router") or {}),
        )

    def _apply_plan_entry_constraints(
        self,
        plan: Optional[Dict[str, Any]],
        *,
        source: str,
    ) -> Dict[str, Any]:
        """Sync runtime caps with the current plan and emit drift warnings."""
        entry_constraints = self._plan_entry_constraints(plan)
        self.max_positions = int(
            entry_constraints.get("max_positions", self.max_positions)
            or self.max_positions
        )
        self.core_max_positions = int(
            entry_constraints.get(
                "core_max_positions",
                getattr(self, "core_max_positions", self.max_positions),
            )
            or getattr(self, "core_max_positions", self.max_positions)
        )
        self.reserve_max_positions = int(
            entry_constraints.get(
                "reserve_max_positions",
                getattr(self, "reserve_max_positions", 10),
            )
            or getattr(self, "reserve_max_positions", 10)
        )
        self.weak_day = bool(
            entry_constraints.get("weak_day", getattr(self, "weak_day", False))
        )
        self.position_caps = dict(entry_constraints)
        return entry_constraints

    def _slot_class_for_order(self, order: Dict[str, Any]) -> str:
        """Infer the slot class for a planned order."""
        return classify_slot_class(
            symbol=order.get("symbol") or order.get("ticker"),
            candidate=order,
        )

    def _slot_class_for_symbol(self, symbol: str) -> str:
        """Infer the slot class for an already-held symbol."""
        symbol_key = str(symbol or "").upper().strip()
        if not symbol_key:
            return "core"
        cached = getattr(self, "_position_slot_class_by_symbol", {}).get(symbol_key)
        if cached:
            return str(cached)
        slot_class = classify_slot_class(symbol=symbol_key)
        if not hasattr(self, "_position_slot_class_by_symbol"):
            self._position_slot_class_by_symbol = {}
        self._position_slot_class_by_symbol[symbol_key] = slot_class
        return slot_class

    def _init_alpaca(self):
        """Initialize Alpaca client for position checking."""
        try:
            from autotrade.utils.alpaca_client_factory import (
                create_data_client,
                create_trading_client,
                resolve_alpaca_credentials,
            )

            creds = resolve_alpaca_credentials(require=False)
            if not creds:
                self.logger.warning(
                    "Alpaca credentials missing; position tracking disabled"
                )
                return

            self.alpaca_client = create_trading_client(
                api_key=creds.api_key,
                secret_key=creds.secret_key,
                paper=creds.paper,
                validate_connection=True,
                retries=3,
                retry_delay_seconds=2.0,
                logger=self.logger,
                require_credentials=True,
            )
            try:
                self.market_data_client = create_data_client(
                    api_key=creds.api_key,
                    secret_key=creds.secret_key,
                    paper=creds.paper,
                    require_credentials=True,
                )
            except Exception as md_err:
                self.logger.debug(f"Could not init Alpaca market data client: {md_err}")
            self.logger.info("Alpaca client initialized for position tracking")
        except Exception as e:
            self.logger.warning(f"Could not init Alpaca client: {e}")

    def _coerce_float(self, value, default: float = 0.0) -> float:
        """Best-effort conversion to finite float with a safe fallback."""
        import math

        if value is None:
            return default
        try:
            if isinstance(value, str):
                cleaned = value.strip().replace("$", "").replace(",", "")
                if cleaned == "":
                    return default
                value = cleaned
            result = float(value)
            if math.isfinite(result):
                return result
        except Exception:
            pass
        return default

    def _coerce_int(self, value, default: int = 0) -> int:
        """Best-effort conversion to int with a safe fallback."""
        try:
            return int(round(self._coerce_float(value, float(default))))
        except Exception:
            return default

    @staticmethod
    def _normalize_position_timestamp(value: Any) -> Optional[datetime]:
        """Parse broker/cache timestamps into timezone-aware datetimes."""
        if value is None:
            return None
        if isinstance(value, datetime):
            dt_value = value
        elif isinstance(value, (int, float)):
            try:
                dt_value = datetime.fromtimestamp(float(value), tz=pytz.UTC)
            except Exception:
                return None
        else:
            text = str(value).strip()
            if not text:
                return None
            if text.endswith("Z"):
                text = f"{text[:-1]}+00:00"
            try:
                dt_value = datetime.fromisoformat(text)
            except Exception:
                return None
        if dt_value.tzinfo is None:
            dt_value = dt_value.replace(tzinfo=pytz.UTC)
        return dt_value

    def _position_hold_snapshot(self, position: Any) -> Tuple[Optional[str], float]:
        """Return the best entry timestamp plus computed hold minutes."""
        raw_timestamp = None
        for key in (
            "entry_time",
            "entry_at",
            "created_at",
            "filled_at",
            "submitted_at",
        ):
            try:
                candidate = getattr(position, key, None)
            except Exception:
                candidate = None
            if candidate not in (None, ""):
                raw_timestamp = candidate
                break
        normalized = self._normalize_position_timestamp(raw_timestamp)
        if normalized is None:
            return None, 0.0
        now_value = datetime.now(normalized.tzinfo)
        hold_minutes = max((now_value - normalized).total_seconds() / 60.0, 0.0)
        return normalized.isoformat(), hold_minutes

    def get_current_positions(self) -> List[Dict]:
        """Get all current positions from Alpaca."""
        if not self.alpaca_client:
            return []

        try:
            from autotrade.utils.position_cache import fetch_positions_with_fallback

            result = fetch_positions_with_fallback(
                self.alpaca_client,
                logger=self.logger,
                retries=2,
                retry_delay_seconds=1.0,
                backoff_multiplier=2.0,
                use_cache=True,
            )
            positions = result.get("positions") or []
            result = []
            for pos in positions:
                entry_timestamp, hold_minutes = self._position_hold_snapshot(pos)
                result.append(
                    {
                        "symbol": pos.symbol,
                        "qty": int(pos.qty),
                        "side": "long" if float(pos.qty) > 0 else "short",
                        "avg_entry": float(pos.avg_entry_price),
                        "current_price": float(pos.current_price),
                        "market_value": float(pos.market_value),
                        "unrealized_pnl": float(pos.unrealized_pl),
                        "pnl_pct": float(pos.unrealized_plpc) * 100,
                        "cost_basis": float(pos.cost_basis),
                        "entry_time": entry_timestamp,
                        "hold_minutes": hold_minutes,
                    }
                )
            return result
        except Exception as e:
            self.logger.error(f"Failed to get positions: {e}")
            return []

    def detect_odd_lots(self, min_position_size: int = 5) -> List[Dict]:
        """
        Detect odd lot positions (1-4 shares) that should be cleaned up.

        These positions are:
        - Too small to matter
        - Leftover from partial fills
        - Wasting buying power
        """
        positions = self.get_current_positions()
        odd_lots = []

        for pos in positions:
            if pos["qty"] < min_position_size:
                odd_lots.append(
                    {
                        "symbol": pos["symbol"],
                        "qty": pos["qty"],
                        "reason": f"Position too small ({pos['qty']} shares)",
                        "action": "CLOSE_AT_OPEN",
                        "current_value": pos["market_value"],
                        "pnl": pos["unrealized_pnl"],
                        "pnl_pct": pos["pnl_pct"],
                    }
                )
                self.logger.info(
                    f"Odd lot detected: {pos['symbol']} ({pos['qty']} shares, ${pos['market_value']:.2f})"
                )

        return odd_lots

    @staticmethod
    def _odd_lot_requires_review(pos: Dict[str, Any]) -> bool:
        """Near-flat odd lots should be reviewed rather than auto-liquidated."""
        pnl_pct = float(pos.get("pnl_pct", 0.0) or 0.0)
        return pnl_pct > -1.0

    def detect_losers_to_cut(self, max_loss_pct: float = -5.0) -> List[Dict]:
        """Detect losing positions that should be cut."""
        positions = self.get_current_positions()
        losers = []

        for pos in positions:
            if pos["pnl_pct"] < max_loss_pct:
                losers.append(
                    {
                        "symbol": pos["symbol"],
                        "qty": pos["qty"],
                        "reason": f"Loss too big ({pos['pnl_pct']:.1f}%)",
                        "action": "CLOSE_AT_OPEN",
                        "loss": pos["unrealized_pnl"],
                        "loss_pct": pos["pnl_pct"],
                    }
                )
                self.logger.info(
                    f"Loser to cut: {pos['symbol']} ({pos['pnl_pct']:.1f}% loss)"
                )

        return losers

    def get_account_info(self) -> Dict:
        """Get account buying power and balance."""
        if not self.alpaca_client:
            return self._load_cached_account_info()

        try:
            account = self.alpaca_client.get_account()
            return {
                "cash": float(account.cash),
                "buying_power": float(account.buying_power),
                "equity": float(account.equity),
                "day_trade_count": account.daytrade_count,
                "pattern_day_trader": account.pattern_day_trader,
            }
        except Exception as e:
            self.logger.error(f"Failed to get account: {e}")
            return self._load_cached_account_info()

    def _load_cached_account_info(self) -> Dict:
        """Best-effort local fallback when live broker account lookup is unavailable."""
        default = {"cash": 0.0, "buying_power": 0.0, "equity": 0.0}
        try:
            snapshot_path = (
                Path(__file__).resolve().parents[2]
                / "data"
                / "alpaca_snapshot_today.json"
            )
            if not snapshot_path.exists():
                return default
            payload = json.loads(snapshot_path.read_text(encoding="utf-8"))
            account = dict(payload.get("account") or {})
            cash = float(account.get("cash") or 0.0)
            buying_power = float(account.get("buying_power") or cash or 0.0)
            equity = float(
                account.get("equity") or account.get("portfolio_value") or 0.0
            )
            if cash <= 0.0 and buying_power <= 0.0 and equity <= 0.0:
                return default
            return {
                "cash": cash,
                "buying_power": buying_power,
                "equity": equity,
                "account_source": "alpaca_snapshot_today",
            }
        except Exception as exc:
            self.logger.debug(f"Failed to load cached account snapshot: {exc}")
            return default

    def generate_plan(self, pm_plan_path: Path = None) -> Dict:
        """
        Generate tomorrow's actionable trade plan.

        Returns a plan with:
        - Positions to close (odd lots + losers)
        - New entries to make
        - Specific order parameters
        """
        plan = {
            "generated_at": datetime.now().isoformat(),
            "for_date": (datetime.now() + timedelta(days=1)).strftime("%Y-%m-%d"),
            "account": self.get_account_info(),
            "cleanup_orders": [],  # Odd lots and losers to close
            "review_positions": [],  # Positions that need conviction review at the open
            "entry_orders": [],  # New positions to open
            "total_actions": 0,
            "summary": "",
        }

        # 1. Detect odd lots
        odd_lots = self.detect_odd_lots(min_position_size=5)
        for odd in odd_lots:
            if self._odd_lot_requires_review(odd):
                plan["review_positions"].append(
                    {
                        "symbol": odd["symbol"],
                        "qty": odd["qty"],
                        "action": "REVIEW_AT_OPEN",
                        "reason": "Odd lot recovered near flat; re-check conviction before liquidating",
                        "current_value": odd["current_value"],
                        "pnl_pct": odd.get("pnl_pct", 0.0),
                    }
                )
            else:
                plan["cleanup_orders"].append(
                    {
                        "type": "MARKET_SELL",
                        "symbol": odd["symbol"],
                        "qty": odd["qty"],
                        "reason": odd["reason"],
                        "expected_proceeds": odd["current_value"],
                    }
                )

        # 2. Detect losers to cut
        losers = self.detect_losers_to_cut(max_loss_pct=-5.0)
        for loser in losers:
            # Don't duplicate if already in cleanup
            if not any(o["symbol"] == loser["symbol"] for o in plan["cleanup_orders"]):
                plan["cleanup_orders"].append(
                    {
                        "type": "MARKET_SELL",
                        "symbol": loser["symbol"],
                        "qty": loser["qty"],
                        "reason": loser["reason"],
                        "expected_loss": loser["loss"],
                    }
                )

        # 3. Load PM plan or morning game plan for new entries
        plan_loaded = False
        pm_plan = None

        # Try multiple plan sources, preferring PM plan (post-market curated) over morning.
        plan_paths = []
        morning_plan_path = (
            PLANS_DIR / f"morning_game_plan_{datetime.now().strftime('%Y%m%d')}.json"
        )
        if pm_plan_path and pm_plan_path.exists():
            plan_paths.append(pm_plan_path)
        if morning_plan_path.exists() and morning_plan_path not in plan_paths:
            plan_paths.append(morning_plan_path)

        for path in plan_paths:
            try:
                # Use migration helper for consistent schema
                from autotrade.utils.plan_schema_validator import load_and_migrate_plan

                pm_plan = load_and_migrate_plan(str(path))
                self.logger.info(f"Loaded plan from: {path.name} (migrated schema)")
                plan_loaded = True
                break
            except Exception:
                # Fallback to raw loading
                try:
                    with open(path) as f:
                        pm_plan = json.load(f)
                    self.logger.info(f"Loaded plan from: {path.name}")
                    plan_loaded = True
                    break
                except Exception as e2:
                    self.logger.warning(f"Failed to load {path}: {e2}")

        if plan_loaded and pm_plan:
            entry_constraints = self._apply_plan_entry_constraints(
                pm_plan, source=str(pm_plan.get("generated_at") or "plan")
            )
            # CANONICAL: Use 'signals' after migration (with fallback for safety)
            signals = pm_plan.get(
                "signals",
                pm_plan.get("buy_signals", pm_plan.get("entry_candidates", [])),
            )

            self.logger.info(f"Found {len(signals)} signals in plan")
            buying_power = plan["account"].get("buying_power", 0)

            # Get current positions to avoid duplicates
            current_symbols = {p["symbol"] for p in self.get_current_positions()}

            # Filter for actionable signals - handle different field names
            # morning_game_plan uses: recommendation='BUY', confidence
            # pm_plan uses: action='buy', final_score
            actionable = []
            for s in signals:
                # Check various score/action fields
                score = self._coerce_float(
                    s.get("confidence") or s.get("final_score") or s.get("score"), 0.0
                )
                action = (s.get("recommendation") or s.get("action") or "").lower()

                if score > 50 or action in ["buy", "strong_buy"]:
                    actionable.append(s)

            # Calculate available slots (max_positions - current positions + positions being closed)
            current_position_count = len(current_symbols)
            cleanup_count = len(plan["cleanup_orders"])
            plan_max_positions = int(
                entry_constraints.get("max_positions", self.max_positions)
                or self.max_positions
            )
            available_slots = (
                plan_max_positions - current_position_count + cleanup_count
            )
            available_slots = max(0, available_slots)  # Can't be negative

            self.logger.info(
                f"Position slots: {current_position_count} current, {cleanup_count} closing, {available_slots} available"
            )

            # Take signals to fill available slots
            entries_added = 0
            for sig in actionable:
                if entries_added >= available_slots:
                    break

                symbol = sig.get("symbol", sig.get("ticker"))
                if symbol in current_symbols:
                    self.logger.debug(f"Skipping {symbol} - already in portfolio")
                    continue  # Already have this position

                # Handle different field names from various plan formats:
                # morning_game_plan: entry_price, stop_loss, target, confidence
                # pm_plan: entry, stop, target, final_score
                entry_price = sig.get("entry_price")
                if entry_price is None:
                    entry_price = sig.get("entry")
                if entry_price is None:
                    entry_price = sig.get("price")
                entry_price = self._coerce_float(entry_price, 0.0)

                stop_loss = sig.get("stop_loss")
                if stop_loss is None:
                    stop_loss = sig.get("stop")
                if stop_loss is None:
                    stop_loss = sig.get("stop_price")
                stop_loss = self._coerce_float(stop_loss, 0.0)

                take_profit = sig.get("target")
                if take_profit is None:
                    take_profit = sig.get("take_profit")
                if take_profit is None:
                    take_profit = sig.get("target_price")
                take_profit = self._coerce_float(take_profit, 0.0)

                score = self._coerce_float(
                    sig.get("confidence") or sig.get("final_score") or sig.get("score"),
                    0.0,
                )

                # day-manager 2026-05-19 (H3): reject explicit bad geometry
                # at the producer (e.g. RVYL kept emitting tp<=entry every
                # cycle). Missing levels (==0) still fall through to defaults.
                geometry_ok, geometry_reason = _long_bracket_source_geometry_ok(
                    entry_price=entry_price,
                    stop_loss=stop_loss,
                    take_profit=take_profit,
                )
                if not geometry_ok:
                    if symbol in self._plan_producer_reject_silenced:
                        self.logger.debug(
                            "[PLAN PRODUCER REJECT] %s skipped (dedup): %s",
                            symbol,
                            geometry_reason,
                        )
                    else:
                        self.logger.warning(
                            "[PLAN PRODUCER REJECT] %s skipped: %s",
                            symbol,
                            geometry_reason,
                        )
                        self._plan_producer_reject_silenced.add(symbol)
                    continue

                if stop_loss <= 0 and entry_price > 0:
                    stop_loss = entry_price * 0.95
                if take_profit <= 0 and entry_price > 0:
                    take_profit = entry_price * 1.10
                stop_loss, take_profit, risk_repair = _sanitize_long_bracket_levels(
                    entry_price=entry_price,
                    stop_loss=stop_loss,
                    take_profit=take_profit,
                )
                if risk_repair["repaired"]:
                    self.logger.warning(
                        "[PLAN RISK REPAIR] %s repaired invalid bracket levels: %s",
                        symbol,
                        ",".join(risk_repair["reasons"]),
                    )

                if entry_price > 0 and buying_power > entry_price * 10:
                    # Position size from config (target $3000 per position)
                    position_value = min(self.position_size_target, buying_power * 0.10)
                    qty = int(position_value / entry_price)
                    if qty < 1:
                        continue

                    plan["entry_orders"].append(
                        {
                            "type": "BRACKET",
                            "symbol": symbol,
                            "qty": qty,
                            "entry_price": entry_price,
                            "stop_loss": stop_loss,
                            "take_profit": take_profit,
                            "risk_level_repaired": bool(risk_repair["repaired"]),
                            "risk_level_repair_reasons": risk_repair["reasons"],
                            "score": score,
                            "estimated_cost": entry_price * qty,
                            # Strategy lab metadata (from validated strategies)
                            "strategy_name": sig.get("strategy_name", ""),
                            "setup_type": sig.get("setup_type", ""),
                            "symbol_strategy_rank": sig.get("symbol_strategy_rank"),
                            "symbol_strategy_source": sig.get("symbol_strategy_source"),
                            "max_hold_days": sig.get("max_hold_days"),
                            "stop_atr_mult": sig.get("stop_atr_mult"),
                            "target_atr_mult": sig.get("target_atr_mult"),
                        }
                    )
                    buying_power -= entry_price * qty  # Track remaining buying power
                    entries_added += 1

            # If no high-score signals, take by score anyway to fill available slots
            if not plan["entry_orders"] and signals and available_slots > 0:
                # Sort by confidence or final_score
                sorted_signals = sorted(
                    signals,
                    key=lambda x: self._coerce_float(
                        x.get("confidence") or x.get("final_score") or x.get("score"),
                        0.0,
                    ),
                    reverse=True,
                )
                self.logger.info(
                    f"Fallback: taking top {available_slots} from {len(sorted_signals)} signals"
                )
                entries_added = 0
                for sig in sorted_signals:
                    if entries_added >= available_slots:
                        break

                    symbol = sig.get("symbol", sig.get("ticker"))
                    if symbol in current_symbols:
                        continue

                    entry_price = sig.get("entry_price")
                    if entry_price is None:
                        entry_price = sig.get("entry")
                    if entry_price is None:
                        entry_price = sig.get("price")
                    entry_price = self._coerce_float(entry_price, 0.0)

                    stop_loss = sig.get("stop_loss")
                    if stop_loss is None:
                        stop_loss = sig.get("stop")
                    if stop_loss is None:
                        stop_loss = sig.get("stop_price")
                    stop_loss = self._coerce_float(stop_loss, 0.0)

                    take_profit = sig.get("target")
                    if take_profit is None:
                        take_profit = sig.get("take_profit")
                    if take_profit is None:
                        take_profit = sig.get("target_price")
                    take_profit = self._coerce_float(take_profit, 0.0)

                    score = self._coerce_float(
                        sig.get("confidence")
                        or sig.get("final_score")
                        or sig.get("score"),
                        0.0,
                    )

                    # day-manager 2026-05-19 (H3): same producer-side reject
                    # as the primary path above.
                    geometry_ok, geometry_reason = _long_bracket_source_geometry_ok(
                        entry_price=entry_price,
                        stop_loss=stop_loss,
                        take_profit=take_profit,
                    )
                    if not geometry_ok:
                        if symbol in self._plan_producer_reject_silenced:
                            self.logger.debug(
                                "[PLAN PRODUCER REJECT] %s skipped (dedup): %s",
                                symbol,
                                geometry_reason,
                            )
                        else:
                            self.logger.warning(
                                "[PLAN PRODUCER REJECT] %s skipped: %s",
                                symbol,
                                geometry_reason,
                            )
                            self._plan_producer_reject_silenced.add(symbol)
                        continue

                    if stop_loss <= 0 and entry_price > 0:
                        stop_loss = entry_price * 0.95
                    if take_profit <= 0 and entry_price > 0:
                        take_profit = entry_price * 1.10
                    stop_loss, take_profit, risk_repair = _sanitize_long_bracket_levels(
                        entry_price=entry_price,
                        stop_loss=stop_loss,
                        take_profit=take_profit,
                    )
                    if risk_repair["repaired"]:
                        self.logger.warning(
                            "[PLAN RISK REPAIR] %s repaired invalid bracket levels: %s",
                            symbol,
                            ",".join(risk_repair["reasons"]),
                        )

                    if entry_price > 0 and buying_power > entry_price * 10:
                        position_value = min(
                            self.position_size_target, buying_power * 0.10
                        )
                        qty = int(position_value / entry_price)
                        if qty < 1:
                            continue

                        plan["entry_orders"].append(
                            {
                                "type": "BRACKET",
                                "symbol": symbol,
                                "qty": qty,
                                "entry_price": entry_price,
                                "stop_loss": stop_loss,
                                "take_profit": take_profit,
                                "risk_level_repaired": bool(risk_repair["repaired"]),
                                "risk_level_repair_reasons": risk_repair["reasons"],
                                "score": score,
                                "estimated_cost": entry_price * qty,
                                "note": "Lower conviction - watch closely",
                                # Strategy lab metadata (from validated strategies)
                                "strategy_name": sig.get("strategy_name", ""),
                                "setup_type": sig.get("setup_type", ""),
                                "symbol_strategy_rank": sig.get("symbol_strategy_rank"),
                                "symbol_strategy_source": sig.get(
                                    "symbol_strategy_source"
                                ),
                                "max_hold_days": sig.get("max_hold_days"),
                                "stop_atr_mult": sig.get("stop_atr_mult"),
                                "target_atr_mult": sig.get("target_atr_mult"),
                            }
                        )
                        buying_power -= entry_price * qty
                        entries_added += 1

        plan["total_actions"] = (
            len(plan["cleanup_orders"])
            + len(plan["review_positions"])
            + len(plan["entry_orders"])
        )

        # Generate summary
        cleanup_count = len(plan["cleanup_orders"])
        review_count = len(plan["review_positions"])
        entry_count = len(plan["entry_orders"])
        plan["summary"] = (
            f"Tomorrow's Plan: Close {cleanup_count} positions, "
            f"Review {review_count} positions, Enter {entry_count} new trades"
        )

        self.logger.info(f"Generated plan: {plan['summary']}")
        return plan

    # ==================== SMART EXECUTION (LLM-Guided) ====================

    def _evaluate_trade_with_llm(
        self, order: Dict, current_price: float, market_context: Dict
    ) -> Dict:
        """
        Use LLM to evaluate if a trade is worth making RIGHT NOW.

        Returns decision dict with:
        - execute: bool - should we place this order?
        - confidence: 0-100 - how confident in this trade?
        - reasoning: str - why or why not?
        - adjusted_qty: int - suggested quantity (may be less than planned)
        """
        from langgraph_workflow.llm_helper import LLMHelper

        symbol = order.get("symbol")
        planned_price = self._coerce_float(
            order.get("entry_price") or order.get("entry") or order.get("price"), 0.0
        )
        planned_qty = self._coerce_int(order.get("qty"), 0)
        score = self._coerce_float(
            order.get("score") or order.get("final_score") or order.get("confidence"),
            50.0,
        )

        stop_loss = self._coerce_float(order.get("stop_loss") or order.get("stop"), 0.0)
        if stop_loss <= 0 and planned_price > 0:
            stop_loss = planned_price * 0.95

        target = self._coerce_float(
            order.get("take_profit") or order.get("target"), 0.0
        )
        if target <= 0 and planned_price > 0:
            target = planned_price * 1.10

        # Ensure current_price is valid
        current_price = self._coerce_float(current_price, 0.0)
        if current_price <= 0:
            current_price = planned_price if planned_price > 0 else 1.0

        # Calculate price gap from overnight plan
        if planned_price > 0 and current_price > 0:
            gap_pct = ((current_price - planned_price) / planned_price) * 100
        else:
            gap_pct = 0

        # Calculate risk/reward safely
        risk_pct = (
            ((current_price - stop_loss) / current_price * 100)
            if current_price > 0
            else 0
        )
        reward_pct = (
            ((target - current_price) / current_price * 100) if current_price > 0 else 0
        )
        risk_amount = max(0.0, current_price - stop_loss)
        reward_amount = max(0.0, target - current_price)
        rr_ratio = (reward_amount / risk_amount) if risk_amount > 0 else 0.0
        position_value = (
            planned_qty * current_price if planned_qty and current_price else 0
        )

        # Build context for LLM
        prompt = f"""You are a day trading execution advisor. Evaluate if this trade should be executed RIGHT NOW at market open.

TRADE SETUP (from overnight research):
- Symbol: {symbol}
- Overnight Score: {score}/100
- Planned Entry: ${planned_price:.2f}
- Current Price: ${current_price:.2f}
- Gap from Plan: {gap_pct:+.1f}%
- Stop Loss: ${stop_loss:.2f} ({risk_pct:.1f}% risk)
- Target: ${target:.2f} ({reward_pct:.1f}% upside)
- R:R Ratio: {rr_ratio:.2f}:1
- Planned Quantity: {planned_qty} shares (${position_value:,.0f})

MARKET CONTEXT:
- SPY Pre-market: {market_context.get("spy_change", "flat")}
- Market Sentiment: {market_context.get("sentiment", "mixed")}
- Sector Momentum: {market_context.get("sector", "mixed")}

DECISION CRITERIA:
1. If gap > +5% - stock already moved, may be chasing
2. If gap < -3% - might indicate weakness, but could be opportunity
3. Risk/Reward ratio should be at least 1.5:1
4. Overnight score < 60 is weak conviction
5. If market context is unavailable, evaluate setup quality alone. Do NOT skip solely for missing context.
6. Bias toward EXECUTE when Overnight score >= 80 and R:R >= 1.5, unless there is a clear red flag.

Respond in JSON only:
{{
    "execute": true/false,
    "confidence": 0-100,
    "reasoning": "one sentence explanation",
    "adjusted_qty_pct": 100 (or less if reducing position)
}}"""

        try:
            llm = LLMHelper()
            result = llm.call(
                prompt=prompt,
                task="decision",  # Use best model for trading decisions
                temperature=0.1,
                max_tokens=256,
                use_cache=False,  # Don't cache - prices change!
            )

            if result.success and result.parsed_json:
                decision = result.parsed_json
                execute = bool(decision.get("execute", False))
                confidence = self._coerce_int(decision.get("confidence"), 50)
                reasoning = str(decision.get("reasoning", "LLM decision"))
                adjusted_qty_pct = decision.get("adjusted_qty_pct", 100)
                adjusted_qty = max(1, int(planned_qty * adjusted_qty_pct / 100))

                # Guardrail: do not reject high-quality setups only due missing context.
                if (not execute) and score >= 80 and rr_ratio >= 1.5:
                    reason_l = reasoning.lower()
                    if any(
                        k in reason_l
                        for k in ["context", "unknown", "unavailable", "missing"]
                    ):
                        execute = True
                        confidence = max(confidence, 65)
                        reasoning = "Market context missing, but setup quality is high (score>=80 and R:R>=1.5)"

                return {
                    "execute": execute,
                    "confidence": confidence,
                    "reasoning": reasoning,
                    "adjusted_qty": adjusted_qty,
                    "gap_pct": gap_pct,
                    "current_price": current_price,
                }
            else:
                # LLM failed - use rule-based fallback
                self.logger.warning(f"[LLM FALLBACK] {symbol} - using rules")
                return self._rule_based_trade_eval(order, current_price, gap_pct)

        except Exception as e:
            self.logger.warning(f"[LLM ERROR] {symbol}: {e}")
            return self._rule_based_trade_eval(order, current_price, gap_pct)

    def _rule_based_trade_eval(
        self, order: Dict, current_price: float, gap_pct: float
    ) -> Dict:
        """Fallback rule-based trade evaluation when LLM unavailable."""
        score = order.get("score", 50)
        planned_qty = order.get("qty", 0)

        # Simple rules:
        # 1. Skip if gapped up more than 5%
        if gap_pct > 5:
            return {
                "execute": False,
                "confidence": 80,
                "reasoning": f"Gapped up {gap_pct:.1f}% - would be chasing",
                "adjusted_qty": 0,
                "gap_pct": gap_pct,
                "current_price": current_price,
            }

        # 2. Skip if score too low
        if score < 50:
            return {
                "execute": False,
                "confidence": 70,
                "reasoning": f"Score {score} too low for execution",
                "adjusted_qty": 0,
                "gap_pct": gap_pct,
                "current_price": current_price,
            }

        # 3. Reduce size if gapped up 2-5%
        if gap_pct > 2:
            return {
                "execute": True,
                "confidence": 60,
                "reasoning": f"Gapped up {gap_pct:.1f}% - reducing position",
                "adjusted_qty": max(1, int(planned_qty * 0.5)),
                "gap_pct": gap_pct,
                "current_price": current_price,
            }

        # 4. Gapped down - could be opportunity or trouble
        if gap_pct < -3:
            return {
                "execute": True,
                "confidence": 50,  # Lower confidence
                "reasoning": f"Gapped down {gap_pct:.1f}% - smaller position",
                "adjusted_qty": max(1, int(planned_qty * 0.5)),
                "gap_pct": gap_pct,
                "current_price": current_price,
            }

        # 5. Normal gap - execute as planned
        return {
            "execute": True,
            "confidence": 75,
            "reasoning": f"Gap {gap_pct:+.1f}% acceptable, score {score}",
            "adjusted_qty": planned_qty,
            "gap_pct": gap_pct,
            "current_price": current_price,
        }

    def _get_market_context(self) -> Dict:
        """Get quick market context for trade decisions."""
        context = {
            "spy_change": "flat (context unavailable)",
            "spy_price": None,
            "sentiment": "mixed",
            "sector": "mixed",
            "hot_sectors": [],
            "cold_sectors": [],
        }

        try:
            spy_price = None
            prev_close = None

            # 1) Try Alpaca quote first.
            if getattr(self, "market_data_client", None):
                try:
                    from alpaca.data.requests import StockLatestQuoteRequest

                    quote = self.market_data_client.get_stock_latest_quote(
                        StockLatestQuoteRequest(symbol_or_symbols=["SPY"])
                    )
                    if isinstance(quote, dict) and "SPY" in quote:
                        q = quote["SPY"]
                        ask = self._coerce_float(getattr(q, "ask_price", 0.0), 0.0)
                        bid = self._coerce_float(getattr(q, "bid_price", 0.0), 0.0)
                        if ask > 0 and bid > 0:
                            spy_price = (ask + bid) / 2.0
                        elif ask > 0:
                            spy_price = ask
                        elif bid > 0:
                            spy_price = bid
                except Exception:
                    pass

            # 2) yfinance fallback for SPY price and previous close.
            try:
                import yfinance as yf

                spy = yf.Ticker("SPY")
                fast = getattr(spy, "fast_info", {}) or {}

                def _get_fast(keys: List[str]) -> Optional[float]:
                    for key in keys:
                        val = None
                        if isinstance(fast, dict):
                            val = fast.get(key)
                        else:
                            val = getattr(fast, key, None)
                        num = self._coerce_float(val, 0.0)
                        if num > 0:
                            return num
                    return None

                if spy_price is None:
                    spy_price = _get_fast(
                        ["lastPrice", "last_price", "regularMarketPrice"]
                    )
                prev_close = _get_fast(
                    ["previousClose", "previous_close", "regularMarketPreviousClose"]
                )
            except Exception:
                pass

            if spy_price and spy_price > 0:
                context["spy_price"] = round(spy_price, 2)
                if prev_close and prev_close > 0:
                    change_pct = ((spy_price - prev_close) / prev_close) * 100
                    context["spy_change"] = f"{change_pct:+.2f}% (SPY {spy_price:.2f})"
                else:
                    context["spy_change"] = f"SPY {spy_price:.2f}"

            # Load market sentiment + sector momentum from latest overnight report / morning plan.
            sentiment = None
            hot_sectors: List[str] = []
            cold_sectors: List[str] = []

            def _load_json(path: Path) -> Optional[Dict]:
                try:
                    with open(path) as f:
                        payload = json.load(f)
                    return payload if isinstance(payload, dict) else None
                except Exception:
                    return None

            # Prefer latest overnight report.
            overnight_reports = sorted(
                (PROJECT_DIR / "research").glob("overnight_report_*.json"),
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
            if overnight_reports:
                report = _load_json(overnight_reports[0]) or {}
                outlook = report.get("market_outlook", {})
                sectors = report.get("sector_analysis", {})
                if isinstance(outlook, dict):
                    sentiment = (
                        outlook.get("overall_bias")
                        or outlook.get("sp500_sentiment")
                        or sentiment
                    )
                    hot_sectors = hot_sectors or list(outlook.get("hot_sectors") or [])
                    cold_sectors = cold_sectors or list(
                        outlook.get("cold_sectors") or []
                    )
                elif isinstance(outlook, str) and outlook.strip():
                    sentiment = outlook.strip()
                if isinstance(sectors, dict):
                    hot_sectors = hot_sectors or list(sectors.get("hot_sectors") or [])
                    cold_sectors = cold_sectors or list(
                        sectors.get("cold_sectors") or []
                    )

            # Morning game plan fallback for sentiment field if available.
            morning_plans = sorted(
                PLANS_DIR.glob("morning_game_plan_*.json"),
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
            if morning_plans:
                plan = _load_json(morning_plans[0]) or {}
                plan_outlook = plan.get("market_outlook")
                if isinstance(plan_outlook, dict):
                    sentiment = (
                        sentiment
                        or plan_outlook.get("overall_bias")
                        or plan_outlook.get("sp500_sentiment")
                    )
                    hot_sectors = hot_sectors or list(
                        plan_outlook.get("hot_sectors") or []
                    )
                    cold_sectors = cold_sectors or list(
                        plan_outlook.get("cold_sectors") or []
                    )
                elif isinstance(plan_outlook, str) and plan_outlook.strip():
                    sentiment = sentiment or plan_outlook.strip()

            if sentiment:
                context["sentiment"] = str(sentiment).lower()
            if hot_sectors:
                context["hot_sectors"] = [str(s).lower() for s in hot_sectors if s]
            if cold_sectors:
                context["cold_sectors"] = [str(s).lower() for s in cold_sectors if s]
            if context["hot_sectors"] or context["cold_sectors"]:
                hot = (
                    ", ".join(context["hot_sectors"][:3])
                    if context["hot_sectors"]
                    else "none"
                )
                cold = (
                    ", ".join(context["cold_sectors"][:3])
                    if context["cold_sectors"]
                    else "none"
                )
                context["sector"] = f"hot: {hot}; cold: {cold}"

        except Exception as e:
            self.logger.debug(f"Market context error: {e}")

        return context

    def _log_trade_decision(self, decision: Dict, order: Dict, executed: bool):
        """Log trade decision for later review and learning."""
        logs_dir = globals().get("LOGS_DIR", Path("./logs"))
        today = datetime.now().strftime("%Y%m%d")
        log_file = logs_dir / f"trade_decisions_{today}.json"
        log_file.parent.mkdir(parents=True, exist_ok=True)

        entry = {
            "timestamp": datetime.now().isoformat(),
            "symbol": order.get("symbol"),
            "planned_price": order.get("entry_price"),
            "current_price": decision.get("current_price"),
            "gap_pct": decision.get("gap_pct"),
            "planned_qty": order.get("qty"),
            "adjusted_qty": decision.get("adjusted_qty"),
            "score": order.get("score"),
            "llm_execute": decision.get("execute"),
            "llm_confidence": decision.get("confidence"),
            "llm_reasoning": decision.get("reasoning"),
            "actually_executed": executed,
            "entry_source": str(
                order.get("entry_source") or decision.get("entry_source") or ""
            ),
            "plan_score_source": str(
                order.get("plan_score_source")
                or decision.get("plan_score_source")
                or ""
            ),
            "source_bucket": str(
                order.get("source_bucket") or decision.get("source_bucket") or ""
            ),
            "strategy_name": str(order.get("strategy_name") or ""),
            "setup_type": str(order.get("setup_type") or ""),
            "strategy_id": str(order.get("strategy_id") or ""),
        }

        try:
            if log_file.exists():
                with open(log_file, "r", encoding="utf-8") as f:
                    decisions = json.load(f)
            else:
                decisions = []

            decisions.append(entry)

            with open(log_file, "w", encoding="utf-8") as f:
                json.dump(decisions, f, indent=2)

        except Exception as e:
            self.logger.debug(f"Failed to log trade decision: {e}")

    def _record_buy_order_entry(
        self,
        *,
        symbol: str,
        order: Any,
        submitted_price: float,
        reason: str,
        entry_score: Optional[float] = None,
        signal_context: Optional[Dict[str, Any]] = None,
    ) -> Optional[str]:
        """Record a journal entry for a submitted BUY order (pending or filled)."""
        order_id = str(getattr(order, "id", "") or "").strip()
        if not order_id:
            # Critical for tracking; if missing, we can't record.
            self.logger.warning(
                f"[JOURNAL] Cannot record BUY for {symbol}: order_id is missing."
            )
            return None

        try:
            filled_qty = int(float(getattr(order, "filled_qty", 0) or 0))
        except Exception:
            filled_qty = 0
        try:
            filled_price = float(getattr(order, "filled_avg_price", 0) or 0.0)
        except Exception:
            filled_price = 0.0

        # P1 Fix: Use submitted values if not yet filled
        effective_price = filled_price if filled_price > 0 else float(submitted_price)
        requested_qty = int(float(getattr(order, "qty", 0) or 0))
        qty = filled_qty if filled_qty > 0 else requested_qty

        status = "filled" if filled_qty > 0 else "submitted"

        from autotrade.signals.trade_learner import record_entry as journal_record_entry

        try:
            return journal_record_entry(
                symbol=symbol,
                price=effective_price,
                quantity=qty,
                reason=reason,
                entry_status=status,
                order_id=order_id,
                filled_qty=filled_qty,
                submitted_price=float(submitted_price),
                entry_score=entry_score,
                signal_context=signal_context or {},
            )
        except Exception as e:
            self.logger.error(f"[JOURNAL] Failed to record BUY entry for {symbol}: {e}")
            return None

    @staticmethod
    def _market_fade_lockout_reason(now: Optional[datetime] = None) -> str:
        """Block fresh entries in the final noisy 30 minutes of the regular session."""
        current = now or get_market_now()
        current_time = current.time()
        if (current_time.hour, current_time.minute) >= (15, 30) and (
            current_time.hour,
            current_time.minute,
        ) < (16, 0):
            return "market_fade_lockout:after_1530_et"
        return ""

    def execute_plan(self, plan: Dict = None, dry_run: bool = False) -> Dict:
        """
        Execute the morning plan with LLM-guided decision making.

        Instead of blindly placing all 20 orders, we:
        1. Evaluate each trade with LLM for current market conditions
        2. Space out trades to observe market behavior
        3. Log all decisions for review and learning
        4. Start with highest-conviction trades first

        Args:
            plan: Plan dict with entry_orders and cleanup_orders
            dry_run: If True, just log what would happen

        Returns:
            Dict with entries, exits, errors, skipped counts
        """
        from alpaca.trading.requests import MarketOrderRequest, LimitOrderRequest
        from alpaca.trading.enums import OrderSide, TimeInForce

        result = {
            "entries": 0,
            "exits": 0,
            "errors": 0,
            "orders": [],
            "skipped": 0,
            "candidate_count": 0,
            "open_slots": 0,
            "block_reason": "",
        }
        execution_accounting = ExecutionAccounting()

        if not self.alpaca_client:
            self.logger.error("[EXECUTE] No Alpaca client - can't execute trades!")
            result["errors"] = 1
            result["block_reason"] = "alpaca_unavailable"
            result.update(execution_accounting.as_dict())
            return result

        # Load plan if not provided
        if plan is None:
            plan = self._load_latest_plan()
            if not plan:
                self.logger.warning("[EXECUTE] No plan found to execute")
                result["block_reason"] = "no_plan"
                result.update(execution_accounting.as_dict())
                return result

        self.logger.info(
            f"[EXECUTE] Plan has {len(plan.get('cleanup_orders', []))} cleanups, {len(plan.get('entry_orders', []))} entries"
        )

        # Get current positions to avoid duplicates
        current_positions = {p["symbol"] for p in self.get_current_positions()}
        self.logger.info(f"[EXECUTE] Current positions: {len(current_positions)}")
        result["open_slots"] = max(0, 20 - len(current_positions))

        # Load execution state to skip already-processed symbols
        today = datetime.now().strftime("%Y%m%d")
        execution_state_file = PLANS_DIR / f".execution_state_{today}.json"
        already_processed = set()

        if execution_state_file.exists():
            try:
                with open(execution_state_file) as f:
                    exec_state = json.load(f)
                already_processed = set(exec_state.get("executed_symbols", []))
                already_processed.update(exec_state.get("skipped_symbols", []))
            except Exception:
                pass

        # 1. Execute cleanup orders (exits)
        for order in plan.get("cleanup_orders", []):
            symbol = order.get("symbol")
            qty = order.get("qty", 0)

            if qty <= 0:
                continue

            self.logger.info(
                f"[CLEANUP] Exiting {symbol} ({qty} shares) - {order.get('reason', 'cleanup')}"
            )

            if not dry_run:
                try:
                    execution_accounting.attempt(
                        "exit",
                        symbol=symbol,
                        qty=int(qty),
                        context="execute_plan_cleanup",
                    )
                    alpaca_order = self.alpaca_client.submit_order(
                        MarketOrderRequest(
                            symbol=symbol,
                            qty=qty,
                            side=OrderSide.SELL,
                            time_in_force=TimeInForce.DAY,
                        )
                    )
                    execution_accounting.success(
                        "exit",
                        symbol=symbol,
                        qty=int(qty),
                        order_id=getattr(alpaca_order, "id", ""),
                        context="execute_plan_cleanup",
                    )
                    result["exits"] += 1
                    result["orders"].append(
                        {
                            "type": "exit",
                            "symbol": symbol,
                            "qty": qty,
                            "order_id": alpaca_order.id,
                        }
                    )
                    try:
                        from autotrade.signals.trade_learner import (
                            record_exit as journal_record_exit,
                        )

                        filled_qty = int(
                            float(getattr(alpaca_order, "filled_qty", 0) or 0)
                        )
                        filled_price = float(
                            getattr(alpaca_order, "filled_avg_price", 0) or 0
                        )
                        journal_price = float(filled_price or 0.0) or float(
                            self._get_current_price_quick(symbol) or 0.0
                        )
                        execution_status = (
                            "filled"
                            if (filled_qty > 0 and filled_price > 0)
                            else "submitted"
                        )
                        journal_record_exit(
                            symbol=symbol,
                            price=journal_price,
                            quantity=int(qty),
                            reason=str(
                                order.get("reason", "execute_plan_cleanup")
                                or "execute_plan_cleanup"
                            ),
                            order_id=str(getattr(alpaca_order, "id", "")),
                            filled_qty=filled_qty if filled_qty > 0 else int(qty),
                            execution_status=execution_status,
                        )
                    except Exception as journal_err:
                        self.logger.debug(
                            f"Cleanup exit journal record failed for {symbol}: {journal_err}"
                        )
                    self.logger.info(f"   [OK] Exit order placed: {alpaca_order.id}")
                except Exception as e:
                    execution_accounting.failure(
                        "exit",
                        symbol=symbol,
                        qty=int(qty),
                        error=str(e),
                        context="execute_plan_cleanup",
                    )
                    self.logger.error(f"   [FAIL] Exit {symbol}: {e}")
                    result["errors"] += 1
            else:
                self.logger.info(f"   [DRY] Would exit {symbol}")

        # 2. SMART ENTRY EXECUTION - LLM evaluates each trade
        # Sort by score (highest first) - prioritize best opportunities
        entry_orders = sorted(
            plan.get("entry_orders", []), key=lambda x: x.get("score", 0), reverse=True
        )

        # Filter out already-processed symbols (from previous rounds)
        entry_orders = [
            o for o in entry_orders if o.get("symbol") not in already_processed
        ]

        if not entry_orders:
            self.logger.info(
                "[SMART EXECUTION] All candidates already processed in previous rounds"
            )
            result["block_reason"] = "already_processed"
            result.update(execution_accounting.as_dict())
            return result

        # Get market context once for all evaluations
        market_context = self._get_market_context()

        # Track stats and skipped symbols for state update
        result["skipped"] = 0
        result["evaluated"] = 0
        result["skipped_symbols"] = []
        entry_quality_cfg = getattr(self, "entry_quality_cfg", None)
        configured_cycle_cap = int(
            getattr(entry_quality_cfg, "wave_max_entries", 0) or 0
        )
        if configured_cycle_cap <= 0:
            configured_cycle_cap = int(getattr(self, "max_positions", 0) or 0)
        max_entries_per_cycle = max(1, configured_cycle_cap or len(entry_orders))
        result["candidate_count"] = min(len(entry_orders), max_entries_per_cycle)

        self.logger.info(
            f"\n[SMART EXECUTION] Evaluating top {min(len(entry_orders), max_entries_per_cycle)} of {len(entry_orders)} remaining candidates..."
        )
        market_fade_reason = self._market_fade_lockout_reason()

        for i, order in enumerate(entry_orders[:max_entries_per_cycle]):
            symbol = order.get("symbol")
            planned_qty = self._coerce_int(order.get("qty"), 0)
            entry_price = self._coerce_float(order.get("entry_price"), 0.0)

            if planned_qty <= 0 or entry_price <= 0:
                reason = "invalid_qty" if planned_qty <= 0 else "invalid_entry_price"
                self.logger.info(
                    f"[SKIP] {symbol}: {reason} (qty={planned_qty}, entry={entry_price})"
                )
                result["skipped"] += 1
                if symbol:
                    result["skipped_symbols"].append(symbol)
                continue

            if market_fade_reason:
                self.logger.info(f"[SKIP] {symbol}: {market_fade_reason}")
                result["skipped"] += 1
                result["skipped_symbols"].append(symbol)
                result["block_reason"] = market_fade_reason
                continue

            # Skip if already have position
            if symbol in current_positions:
                self.logger.info(f"[SKIP] {symbol} - already have position")
                result["skipped"] += 1
                result["skipped_symbols"].append(symbol)
                continue

            entry_guard_reasons = self._entry_guard_reasons(
                symbol,
                self._coerce_float(order.get("score"), 0.0),
            )
            if entry_guard_reasons:
                self.logger.info(f"[SKIP] {symbol}: {', '.join(entry_guard_reasons)}")
                result["skipped"] += 1
                result["skipped_symbols"].append(symbol)
                continue

            result["evaluated"] += 1

            # Get current price for this symbol
            try:
                current_price = self._get_current_price_quick(symbol)
                if current_price is None or current_price <= 0:
                    current_price = entry_price  # Fallback to planned price
            except Exception:
                current_price = entry_price
            prev_close = self._coerce_float(order.get("prev_close"), 0.0)
            if prev_close > 0:
                max_prev_close_anchor = prev_close * 1.05
                if entry_price > max_prev_close_anchor:
                    self.logger.info(
                        f"[ENTRY ANCHOR] {symbol}: clamping stale planned entry "
                        f"${entry_price:.2f} -> ${max_prev_close_anchor:.2f} "
                        f"(prev_close=${prev_close:.2f})"
                    )
                    order = dict(order)
                    order["entry_price"] = round(max_prev_close_anchor, 4)
                    entry_price = max_prev_close_anchor
                if current_price > max_prev_close_anchor * 1.005:
                    self.logger.info(
                        f"[SKIP] {symbol}: prev_close_entry_drift "
                        f"(current=${current_price:.2f}, prev_close=${prev_close:.2f})"
                    )
                    result["skipped"] += 1
                    result["skipped_symbols"].append(symbol)
                    result["block_reason"] = "prev_close_entry_drift"
                    continue

            # LLM evaluates if this trade is worth making
            self.logger.info(
                f"\n[EVALUATE {i + 1}/{min(len(entry_orders), max_entries_per_cycle)}] {symbol}..."
            )
            decision = self._evaluate_trade_with_llm(
                order, current_price, market_context
            )

            order.get("score", 0)
            executed = False

            if decision["execute"]:
                adjusted_qty = decision["adjusted_qty"]
                self.logger.info(
                    f"   [OK APPROVED] {symbol}: {adjusted_qty} shares (was {planned_qty})"
                )
                self.logger.info(
                    f"      Confidence: {decision['confidence']}% - {decision['reasoning']}"
                )

                if not dry_run:
                    try:
                        # Smart limit pricing: never chase above plan
                        planned_entry = self._coerce_float(
                            order.get("entry_price"), current_price
                        )

                        if current_price > planned_entry * 1.10:
                            # Extended >10% past plan - skip, don't chase (unify with DayManager hard cap)
                            self.logger.info(
                                f"   [SKIP] {symbol}: ${current_price:.2f} extended >10% "
                                f"past plan ${planned_entry:.2f}"
                            )
                            result["skipped"] += 1
                            result["skipped_symbols"].append(symbol)
                            continue
                        elif current_price > planned_entry * 1.05:
                            # Extended 5-10% - skip (previous behavior was 5% hard skip)
                            # Kept at 5% for this specific LLM-reviewed batch to be conservative
                            self.logger.info(
                                f"   [SKIP] {symbol}: ${current_price:.2f} extended >5% "
                                f"past plan ${planned_entry:.2f}"
                            )
                            result["skipped"] += 1
                            result["skipped_symbols"].append(symbol)
                            continue
                        elif current_price > planned_entry * 1.02:
                            # Extended 2-5% - set limit at planned entry (wait for pullback)
                            limit_price = round(planned_entry, 2)
                        else:
                            # Near plan or below - enter at slight discount to current
                            limit_price = round(
                                min(planned_entry, current_price * 0.998), 2
                            )
                        execution_accounting.attempt(
                            "entry",
                            symbol=symbol,
                            qty=int(adjusted_qty),
                            context="execute_plan_entry",
                        )
                        alpaca_order = self.alpaca_client.submit_order(
                            LimitOrderRequest(
                                symbol=symbol,
                                qty=adjusted_qty,
                                side=OrderSide.BUY,
                                time_in_force=TimeInForce.DAY,
                                limit_price=limit_price,
                            )
                        )
                        execution_accounting.success(
                            "entry",
                            symbol=symbol,
                            qty=int(adjusted_qty),
                            order_id=getattr(alpaca_order, "id", ""),
                            context="execute_plan_entry",
                        )

                        self._record_buy_order_entry(
                            symbol=symbol,
                            order=alpaca_order,
                            submitted_price=float(limit_price),
                            reason="execute_plan_entry",
                            entry_score=float(
                                decision.get("confidence") or order.get("score") or 0.0
                            ),
                            signal_context={
                                "setup_type": str(order.get("setup_type", "") or ""),
                                "strategy_name": str(
                                    order.get("strategy_name", "") or ""
                                ),
                                "final_score": float(decision.get("confidence") or 0.0),
                                "llm_confidence": float(
                                    decision.get("confidence") or 0.0
                                ),
                                "entry_source": str(
                                    order.get("entry_source") or "execute_plan_batch"
                                ),
                                "plan_score_source": str(
                                    order.get("plan_score_source", "") or ""
                                ),
                                "source_bucket": str(
                                    order.get("source_bucket", "") or ""
                                ),
                            },
                        )

                        result["entries"] += 1
                        result["orders"].append(
                            {
                                "type": "entry",
                                "symbol": symbol,
                                "qty": adjusted_qty,
                                "limit_price": limit_price,
                                "order_id": alpaca_order.id,
                                "llm_confidence": decision["confidence"],
                                "gap_pct": decision["gap_pct"],
                            }
                        )
                        current_positions.add(symbol)
                        executed = True
                        self.logger.info(f"   [OK] Order placed: {alpaca_order.id}")

                        # Brief pause between orders (don't spam the market)
                        time.sleep(2)

                    except Exception as e:
                        execution_accounting.failure(
                            "entry",
                            symbol=symbol,
                            qty=int(adjusted_qty),
                            error=str(e),
                            context="execute_plan_entry",
                        )
                        self.logger.error(f"   [FAIL] Entry {symbol}: {e}")
                        result["errors"] += 1
                        result["skipped_symbols"].append(
                            symbol
                        )  # Track failed symbols too
                else:
                    self.logger.info(
                        f"   [DRY] Would buy {adjusted_qty} {symbol} @ ${current_price:.2f}"
                    )
                    executed = True  # For logging purposes
            else:
                result["skipped"] += 1
                result["skipped_symbols"].append(symbol)  # Track skipped symbol
                gap_display = decision.get("gap_pct") or 0
                conf_display = decision.get("confidence") or 0
                self.logger.info(
                    f"   [✗ SKIPPED] {symbol}: {decision.get('reasoning', 'no reason')}"
                )
                self.logger.info(
                    f"      Gap: {gap_display:+.1f}%, Confidence: {conf_display}%"
                )

            # Log decision for review
            self._log_trade_decision(decision, order, executed)

        # Update execution state with skipped symbols
        if result["skipped_symbols"]:
            try:
                if execution_state_file.exists():
                    with open(execution_state_file) as f:
                        exec_state = json.load(f)
                else:
                    exec_state = {"skipped_symbols": []}

                exec_state.setdefault("skipped_symbols", []).extend(
                    result["skipped_symbols"]
                )

                with open(execution_state_file, "w") as f:
                    json.dump(exec_state, f, indent=2)
            except Exception:
                pass

        # Summary
        remaining = len(entry_orders) - max_entries_per_cycle
        if remaining > 0:
            self.logger.info(
                f"\n[REMAINING] {remaining} more candidates to evaluate in next cycle"
            )

        accounting_dict = execution_accounting.as_dict()
        result.update(accounting_dict)
        if not dry_run:
            result["entries"] = int(accounting_dict.get("entries_submitted", 0))
            result["exits"] = int(accounting_dict.get("exits_submitted", 0))
        if not result.get("block_reason"):
            if result.get("candidate_count", 0) <= 0:
                result["block_reason"] = "no_candidates"
            elif (
                result.get("orders_submitted", 0) == 0
                and result.get("orders_failed", 0) > 0
            ):
                result["block_reason"] = "submission_failures"
            elif result.get("entries", 0) == 0 and result.get("skipped", 0) > 0:
                result["block_reason"] = "llm_or_policy_skips"

        self.logger.info(
            f"\n[EXECUTE COMPLETE] Entries: {result['entries']}, Skipped: {result['skipped']}, Errors: {result['errors']}"
        )
        self.logger.info(
            "[EXECUTE ACCOUNTING] "
            f"attempted={result.get('actions_attempted', 0)} "
            f"submitted={result.get('orders_submitted', 0)} "
            f"failed={result.get('orders_failed', 0)} "
            f"entries={result.get('entries_submitted', 0)} "
            f"exits={result.get('exits_submitted', 0)} "
            f"trims={result.get('trims_submitted', 0)}"
        )
        self.logger.info(
            f"   Decision log saved to: logs/trade_decisions_{datetime.now().strftime('%Y%m%d')}.json"
        )
        return result

    def _get_current_price_quick(self, symbol: str) -> Optional[float]:
        """Get current price quickly for execution decisions."""
        try:
            # Try Alpaca market data first
            if hasattr(self, "market_data_client") and self.market_data_client:
                from alpaca.data.requests import StockLatestQuoteRequest

                quote = self.market_data_client.get_stock_latest_quote(
                    StockLatestQuoteRequest(symbol_or_symbols=[symbol])
                )
                if symbol in quote:
                    ask = quote[symbol].ask_price or 0
                    bid = quote[symbol].bid_price or 0
                    # Sanity check: if one side is 0 or they differ by >50%, use the non-zero side
                    if ask > 0 and bid > 0:
                        if (
                            ask > 0
                            and bid > 0
                            and (max(ask, bid) / min(ask, bid)) > 1.5
                        ):
                            # Spread is absurdly wide — use the higher (ask) as safer estimate
                            self.logger.warning(
                                f"[PRICE] {symbol} bid/ask spread too wide: bid=${bid:.2f} ask=${ask:.2f}, using ask"
                            )
                            return ask
                        return (ask + bid) / 2
                    elif ask > 0:
                        return ask
                    elif bid > 0:
                        return bid
                    # Both zero — fall through to next provider
        except Exception:
            pass

        # Fallback to LocalDataProvider
        try:
            from autotrade.utils.local_data_provider import LocalDataProvider

            ldp = LocalDataProvider()
            price_result = ldp.get_current_price(symbol)
            if isinstance(price_result, tuple):
                return self._coerce_float(price_result[0], 0.0) or None
            return self._coerce_float(price_result, 0.0) or None
        except Exception:
            pass

        return None

    def _load_latest_plan(self) -> Dict:
        """Load executable plan with adjusted/PM priority and morning fallback."""

        def _plan_rows(plan_data: Dict[str, Any]):
            if not isinstance(plan_data, dict):
                return "signals", []
            for key in ("entry_orders", "signals", "buy_signals", "entry_candidates"):
                rows = plan_data.get(key)
                if isinstance(rows, list) and rows:
                    return key, rows
            return "signals", []

        def _row_symbol(row: Dict[str, Any]) -> str:
            if not isinstance(row, dict):
                return ""
            return str(row.get("symbol") or row.get("ticker") or "").upper()

        def _merge_plan_payloads_pm_precedence(
            pm_plan: Dict[str, Any], morning_plan: Dict[str, Any]
        ) -> Dict[str, Any]:
            """Merge current PM plan with morning breadth tail, PM rows first."""
            pm_key, pm_rows = _plan_rows(pm_plan)
            morning_key, morning_rows = _plan_rows(morning_plan)
            if not pm_rows:
                return dict(morning_plan or {})
            if not morning_rows:
                return dict(pm_plan or {})

            merged_rows = []
            seen = set()
            for row in pm_rows:
                if not isinstance(row, dict):
                    continue
                row_copy = dict(row)
                row_copy["plan_source"] = "pm"
                merged_rows.append(row_copy)
                sym = _row_symbol(row_copy)
                if sym:
                    seen.add(sym)

            tail_count = 0
            overlap = 0
            for row in morning_rows:
                if not isinstance(row, dict):
                    continue
                sym = _row_symbol(row)
                if not sym:
                    continue
                if sym in seen:
                    overlap += 1
                    continue
                row_copy = dict(row)
                row_copy["plan_source"] = "morning_tail"
                merged_rows.append(row_copy)
                seen.add(sym)
                tail_count += 1

            merged = dict(pm_plan or {})
            merged[pm_key or morning_key or "signals"] = merged_rows
            merged["plan_source"] = "pm_plus_morning_tail"
            merged["pm_plan_merge"] = {
                "pm_rows": len(pm_rows),
                "morning_tail_rows": tail_count,
                "overlap_rows": overlap,
                "total_rows": len(merged_rows),
            }
            self.logger.info(
                "[PLAN LOAD] merged %d PM rows + %d morning tail rows "
                "(overlap=%d skipped) -> %d total",
                len(pm_rows),
                tail_count,
                overlap,
                len(merged_rows),
            )
            return merged

        def _previous_trading_day(dt: datetime) -> datetime:
            prev = dt - timedelta(days=1)
            while prev.weekday() >= 5:
                prev -= timedelta(days=1)
            return prev

        def _extract_plan_date_token(path: Path) -> str:
            for token in path.stem.split("_"):
                if len(token) == 8 and token.isdigit():
                    return token
            return "unknown"

        def _count_actionable_plan_rows(plan_data: Dict[str, Any]) -> int:
            if not isinstance(plan_data, dict):
                return 0

            entry_orders = plan_data.get("entry_orders")
            if isinstance(entry_orders, list) and entry_orders:
                return len([row for row in entry_orders if isinstance(row, dict)])

            rows = (
                plan_data.get("signals")
                or plan_data.get("buy_signals")
                or plan_data.get("entry_candidates")
                or []
            )
            if not isinstance(rows, list):
                return 0

            actionable_labels = {"BUY", "WEAK BUY", "STRONG BUY", "BUY_OPEN", "OPEN"}
            blocked_labels = {"WATCH", "HOLD", "WAIT"}
            count = 0
            for row in rows:
                if not isinstance(row, dict):
                    continue
                label = (
                    str(row.get("recommendation") or row.get("action") or "")
                    .strip()
                    .upper()
                )
                if label in blocked_labels:
                    continue
                if label in actionable_labels:
                    count += 1
                    continue

                entry_price = self._coerce_float(
                    row.get("entry_price", row.get("entry", row.get("price", 0.0))),
                    0.0,
                )
                score = self._coerce_float(
                    row.get("score") or row.get("final_score") or row.get("confidence"),
                    0.0,
                )
                if entry_price > 0 and score > 0:
                    count += 1
            return count

        now_local = datetime.now()
        today = now_local.strftime("%Y%m%d")
        prev_day = _previous_trading_day(now_local).strftime("%Y%m%d")
        pm_plan_now = _pm_plan_path(now_local)
        prev_pm_plan_cutoff = datetime.combine(
            _previous_trading_day(now_local).date(), datetime.min.time()
        ).replace(hour=16)
        prev_pm_plan = _pm_plan_path(prev_pm_plan_cutoff)

        # adjusted_plan_*.json was the legacy premarket-adjustment artifact;
        # premarket manager now writes its adjustments directly into
        # morning_game_plan_{date}.json (artifact_role=session_execution_plan,
        # premarket_adjusted=True), so we no longer glob the legacy filenames.
        candidate_paths: List[Path] = []
        for day_token in (today, prev_day):
            candidate_paths.append(pm_plan_now if day_token == today else prev_pm_plan)
            candidate_paths.append(PLANS_DIR / f"morning_game_plan_{day_token}.json")

        for fallback_plan in sorted(
            PLANS_DIR.glob("morning_game_plan_*.json"),
            key=lambda p: p.stat().st_mtime,
            reverse=True,
        ):
            if fallback_plan not in candidate_paths:
                candidate_paths.append(fallback_plan)
            if len(candidate_paths) >= 8:
                break

        for plan_path in candidate_paths:
            if not plan_path.exists():
                continue
            try:
                with open(plan_path) as f:
                    plan_data = json.load(f)
            except Exception as e:
                self.logger.warning(f"[PLAN LOAD] Failed to read {plan_path}: {e}")
                continue

            if plan_path == pm_plan_now:
                morning_plan_path = PLANS_DIR / f"morning_game_plan_{today}.json"
                if morning_plan_path.exists():
                    try:
                        with open(morning_plan_path, "r", encoding="utf-8") as f:
                            morning_plan_data = json.load(f)
                    except Exception as e:
                        self.logger.warning(
                            f"[PLAN LOAD] Failed to read {morning_plan_path}: {e}"
                        )
                    else:
                        pm_actionable = _count_actionable_plan_rows(plan_data)
                        morning_actionable = _count_actionable_plan_rows(
                            morning_plan_data
                        )
                        if pm_actionable == 0 and morning_actionable > 0:
                            self.logger.warning(
                                "[PLAN LOAD] %s has 0 actionable rows while today's %s has %d; using morning plan",
                                plan_path.name,
                                morning_plan_path.name,
                                morning_actionable,
                            )
                            plan_path = morning_plan_path
                            plan_data = morning_plan_data
                        elif morning_actionable > 0:
                            plan_data = _merge_plan_payloads_pm_precedence(
                                plan_data, morning_plan_data
                            )

            entry_count = len(plan_data.get("entry_orders", []))
            signal_rows = (
                plan_data.get("signals")
                or plan_data.get("buy_signals")
                or plan_data.get("entry_candidates")
                or []
            )
            signal_count = len(signal_rows) if isinstance(signal_rows, list) else 0
            plan_date_token = _extract_plan_date_token(plan_path)
            date_scope = (
                "current_trading_day" if plan_date_token == today else "fallback"
            )
            self.logger.info(
                f"[PLAN LOAD] {plan_path} | date={plan_date_token} ({date_scope}) | "
                f"signals={signal_count} | entry_orders={entry_count}"
            )

            if entry_count == 0 and signal_count > 0:
                converted = self._convert_signals_to_plan(plan_data)
                converted_entries = len(converted.get("entry_orders", []))
                self.logger.info(
                    f"[PLAN LOAD] Converted {signal_count} signals -> {converted_entries} entry_orders "
                    f"from {plan_path.name}"
                )
                return converted

            return plan_data

        self.logger.warning(
            f"[PLAN LOAD] No executable plan found for {today} (or fallback {prev_day}) in {PLANS_DIR}"
        )
        return None

    def _convert_signals_to_plan(self, plan_data: Dict) -> Dict:
        """Convert signal-style plans to execute_plan entry_orders format."""
        signals = (
            plan_data.get("signals")
            or plan_data.get("buy_signals")
            or plan_data.get("entry_candidates")
            or []
        )
        positions = self.get_current_positions()
        current_symbols = {p["symbol"] for p in positions}
        account = self.get_account_info()
        buying_power = self._coerce_float(
            account.get("buying_power", account.get("cash", 0.0)),
            0.0,
        )

        entry_constraints = self._plan_entry_constraints(plan_data)
        entry_orders = []
        max_entries = max(
            0,
            min(
                int(
                    entry_constraints.get("max_positions", self.max_positions)
                    or self.max_positions
                )
                - len(positions),
                len(signals),
            ),
        )
        if max_entries <= 0:
            self.logger.info(
                "[PLAN LOAD] No entry slots available "
                f"(held={len(positions)}, max_positions={entry_constraints.get('max_positions', self.max_positions)})"
            )
            converted_plan = dict(plan_data) if isinstance(plan_data, dict) else {}
            converted_plan["entry_orders"] = []
            converted_plan["cleanup_orders"] = []
            converted_plan["converted_from"] = "buy_signals"
            return converted_plan

        skipped_held = 0
        skipped_invalid_price = 0
        skipped_unaffordable = 0

        for sig in signals:
            if len(entry_orders) >= max_entries:
                break
            symbol = sig.get("symbol") or sig.get("ticker")
            if symbol in current_symbols:
                skipped_held += 1
                continue

            entry_price = sig.get("entry_price")
            if entry_price is None:
                entry_price = sig.get("entry")
            if entry_price is None:
                entry_price = sig.get("price")
            entry_price = self._coerce_float(entry_price, 0.0)
            if entry_price <= 0:
                skipped_invalid_price += 1
                continue

            stop_loss = sig.get("stop_loss")
            if stop_loss is None:
                stop_loss = sig.get("stop")
            if stop_loss is None:
                stop_loss = sig.get("stop_price")
            stop_loss = self._coerce_float(stop_loss, 0.0)
            if stop_loss <= 0:
                stop_loss = entry_price * 0.95

            take_profit = sig.get("target")
            if take_profit is None:
                take_profit = sig.get("take_profit")
            if take_profit is None:
                take_profit = sig.get("target_price")
            take_profit = self._coerce_float(take_profit, 0.0)
            if take_profit <= 0:
                take_profit = entry_price * 1.10
            stop_loss, take_profit, risk_repair = _sanitize_long_bracket_levels(
                entry_price=entry_price,
                stop_loss=stop_loss,
                take_profit=take_profit,
            )
            if risk_repair["repaired"]:
                self.logger.warning(
                    "[PLAN CONVERT RISK REPAIR] %s repaired invalid bracket levels: %s",
                    symbol,
                    ",".join(risk_repair["reasons"]),
                )

            score = self._coerce_float(
                sig.get("score") or sig.get("final_score") or sig.get("confidence"),
                50.0,
            )

            # Calculate position size from remaining buying power.
            position_value = min(self.position_size_target, buying_power * 0.05)
            qty = int(position_value / entry_price)
            if qty <= 0:
                skipped_unaffordable += 1
                continue
            qty = max(5, qty)
            estimated_cost = entry_price * qty

            if estimated_cost > buying_power:
                affordable_qty = int(buying_power / entry_price)
                if affordable_qty <= 0:
                    skipped_unaffordable += 1
                    continue
                qty = max(1, affordable_qty)
                estimated_cost = entry_price * qty

            entry_orders.append(
                {
                    "symbol": symbol,
                    "qty": qty,
                    "entry_price": entry_price,
                    "stop_loss": stop_loss,
                    "take_profit": take_profit,
                    "risk_level_repaired": bool(risk_repair["repaired"]),
                    "risk_level_repair_reasons": risk_repair["reasons"],
                    "score": score,
                    # Strategy lab metadata (from validated strategies)
                    "strategy_name": sig.get("strategy_name", ""),
                    "setup_type": sig.get("setup_type", ""),
                    "symbol_strategy_rank": sig.get("symbol_strategy_rank"),
                    "symbol_strategy_source": sig.get("symbol_strategy_source"),
                    "max_hold_days": sig.get("max_hold_days"),
                    "stop_atr_mult": sig.get("stop_atr_mult"),
                    "target_atr_mult": sig.get("target_atr_mult"),
                }
            )

            buying_power = max(0.0, buying_power - estimated_cost)
            if buying_power <= 0:
                break

        self.logger.info(
            "[PLAN CONVERT] "
            f"signals={len(signals)} held={len(positions)} "
            f"max_entries={max_entries} built={len(entry_orders)} "
            f"skipped_held={skipped_held} skipped_invalid_price={skipped_invalid_price} "
            f"skipped_unaffordable={skipped_unaffordable} "
            f"remaining_buying_power=${buying_power:,.2f}"
        )

        # Hard guard: detect suspicious conversion collapse early and persist an alert.
        if len(signals) >= 20 and max_entries >= 5 and len(entry_orders) <= 1:
            alert_payload = {
                "signals": len(signals),
                "held_positions": len(positions),
                "max_entries": max_entries,
                "built_entries": len(entry_orders),
                "skipped_held": skipped_held,
                "skipped_invalid_price": skipped_invalid_price,
                "skipped_unaffordable": skipped_unaffordable,
                "remaining_buying_power": round(float(buying_power or 0.0), 2),
            }
            self.logger.critical(
                "[PLAN CONVERT GUARD] Suspicious conversion collapse detected: "
                f"signals={alert_payload['signals']} -> entries={alert_payload['built_entries']} "
                f"(max_entries={alert_payload['max_entries']})."
            )
            self._persist_plan_conversion_alert(alert_payload)

        converted_plan = dict(plan_data) if isinstance(plan_data, dict) else {}
        converted_plan["entry_orders"] = entry_orders
        converted_plan["cleanup_orders"] = []  # No cleanups from signals
        converted_plan["converted_from"] = "buy_signals"
        return converted_plan

    def _persist_plan_conversion_alert(self, payload: Dict) -> None:
        """Persist plan conversion guard alerts for post-mortem review."""
        try:
            LOG_DIR.mkdir(exist_ok=True)
            alert_path = (
                LOG_DIR
                / f"plan_conversion_alert_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
            )
            body = {
                "timestamp": datetime.now().isoformat(),
                "type": "plan_conversion_guard",
                "severity": "critical",
                "payload": payload,
            }
            with open(alert_path, "w") as f:
                json.dump(body, f, indent=2, default=str)
            self.logger.warning(
                f"[PLAN CONVERT GUARD] Alert persisted: {alert_path.name}"
            )
        except Exception as e:
            self.logger.warning(f"[PLAN CONVERT GUARD] Failed to persist alert: {e}")

    def save_plan(self, plan: Dict, output_path: Path = None) -> Path:
        """Save the plan to a file."""
        if output_path is None:
            output_path = (
                PLANS_DIR
                / f"tomorrows_plan_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
            )

        output_path.parent.mkdir(exist_ok=True)
        with open(output_path, "w") as f:
            json.dump(plan, f, indent=2)

        self.logger.info(f"Saved plan to {output_path}")
        return output_path


# ============================================================
# PHASE 2 – RESEARCH ENGINE
# ============================================================


class OvernightResearchEngine:
    """
    OVERNIGHT RESEARCH ENGINE - Comprehensive overnight analysis and preparation.

    This runs during OVERNIGHT phase (8 PM - 4 AM) and does:
    1. Backtest tomorrow's picks against historical data
    2. Generate visual charts for each pick (matplotlib)
    3. Research general market outlook
    4. Analyze sector rotation and hot/cold sectors
    5. Create tools in tools/ directory for custom analysis
    6. Generate a comprehensive game plan with confidence scores

    The goal is to be 100% PREPARED when the market opens.
    """

    # Directories
    TOOLS_DIR = PROJECT_DIR / "tools"
    CHARTS_DIR = PROJECT_DIR / "charts"
    RESEARCH_DIR = PROJECT_DIR / "research"
    TOOLS_INDEX_PATH = PROJECT_DIR / "tools" / "tools_index.json"
    CHARTS_INDEX_PATH = PROJECT_DIR / "charts" / "charts_index.json"

    # Chart retention policy
    CHART_RETENTION_DAYS = 7  # Delete charts older than this

    def __init__(self):
        self.logger = logging.getLogger("AutonomousAgent.OvernightEngine")
        self.ollama_url = "http://localhost:11434"
        self.searxng_url = os.environ.get("SEARXNG_URL", "http://localhost:8080")
        self.data_fetcher = DataFetcher()

        # Ensure directories exist
        self.TOOLS_DIR.mkdir(exist_ok=True)
        self.CHARTS_DIR.mkdir(exist_ok=True)
        self.RESEARCH_DIR.mkdir(exist_ok=True)

        # Load or create indices
        self.tools_index = self._load_tools_index()
        self.charts_index = self._load_charts_index()

        # Cleanup old charts on startup
        cleaned = self._cleanup_old_charts()

        # State
        self.backtest_results = {}
        self.market_outlook = {}
        self.sector_analysis = {}
        self.picks_analysis = []
        self.current_regime = "neutral"
        self.current_regime_analysis = None
        self.regime_strategy_overrides = {}
        self.regime_scan_types = []
        self.regime_scoring_mode = "momentum_pullback"
        self.disable_new_discovery = False
        self.max_discovery_batch = 200
        # Production runtime keeps visual validation disabled. Legacy vl_* state
        # remains readable for backward compatibility, but it is inert.
        self.visual_validation_enabled: bool = False
        self.vl_enabled_models: List[str] = []
        self.vl_include_all_installed_vision_models: bool = False
        self.vl_fallback_enabled: bool = False
        self.vl_preprocess_mode: str = "none"
        self.vl_min_schema_pass_rate: float = 0.85
        self.vl_min_unique_combos: int = 6
        self.vl_max_dominant_combo_ratio: float = 0.70
        self.vl_max_duplicate_reasoning_ratio: float = 0.75
        self.vl_max_stage_runtime_seconds: int = 180
        self._cached_installed_models: Optional[List[str]] = None
        self._cached_installed_models_at: Optional[datetime] = None
        self._vl_validator = None
        self._load_vl_overnight_settings()
        self.regime_detector = None
        try:
            from autotrade.analysis.market_regime import MarketRegimeDetector

            self.regime_detector = MarketRegimeDetector()
            self.logger.info(
                "Quantitative market regime detector initialized for overnight engine"
            )
        except Exception as e:
            self.logger.warning(
                f"Market regime detector unavailable for overnight engine: {e}"
            )

        self.logger.info(
            f"OvernightResearchEngine initialized ({len(self.tools_index)} tools, {len(self.charts_index)} charts)"
        )
        if cleaned:
            self.logger.info(f"   Cleaned up {cleaned} old charts")

    def _load_vl_overnight_settings(self) -> None:
        """Load VL settings without allowing runtime re-enable."""
        config_path = PROJECT_DIR / "config" / "trading_config.yaml"
        if not config_path.exists():
            return
        try:
            import yaml

            with open(config_path, encoding="utf-8") as f:
                cfg = yaml.safe_load(f) or {}
            vl_cfg = cfg.get("vl_overnight", {}) if isinstance(cfg, dict) else {}
            if not isinstance(vl_cfg, dict):
                return

            preprocess_mode = str(vl_cfg.get("preprocess_mode", "none")).strip().lower()
            if preprocess_mode in {"none", "normalize"}:
                self.vl_preprocess_mode = preprocess_mode

            max_runtime = vl_cfg.get("max_stage_runtime_seconds")
            if max_runtime is not None:
                self.vl_max_stage_runtime_seconds = max(30, int(max_runtime))

            thresholds = vl_cfg.get("quarantine_thresholds", {})
            if isinstance(thresholds, dict):
                min_schema = thresholds.get("min_schema_pass_rate")
                if min_schema is not None:
                    self.vl_min_schema_pass_rate = max(0.0, min(1.0, float(min_schema)))

                min_combos = thresholds.get("min_unique_combos")
                if min_combos is not None:
                    self.vl_min_unique_combos = max(1, int(min_combos))

                max_dom = thresholds.get("max_dominant_combo_ratio")
                if max_dom is not None:
                    self.vl_max_dominant_combo_ratio = max(
                        0.0, min(1.0, float(max_dom))
                    )

                max_dup_reason = thresholds.get("max_duplicate_reasoning_ratio")
                if max_dup_reason is not None:
                    self.vl_max_duplicate_reasoning_ratio = max(
                        0.0, min(1.0, float(max_dup_reason))
                    )
            self.visual_validation_enabled = False
            self.vl_enabled_models = []
            self.vl_include_all_installed_vision_models = False
            self.vl_fallback_enabled = False
            self.logger.info(
                "[VL] Overnight visual validation disabled; config values are ignored at runtime"
            )
        except Exception as e:
            self.logger.warning(
                f"Failed to load vl_overnight config; using defaults: {e}"
            )

    @staticmethod
    def _looks_like_vision_model(model_name: str) -> bool:
        name = str(model_name or "").lower()
        return ("vision" in name) or ("vl" in name)

    def _get_installed_ollama_models(self, ttl_seconds: int = 300) -> List[str]:
        """Return installed Ollama model names with a short cache."""
        cached = self._cached_installed_models
        cached_at = self._cached_installed_models_at
        if (
            cached is not None
            and cached_at is not None
            and (datetime.now() - cached_at).total_seconds()
            <= max(10, int(ttl_seconds))
        ):
            return list(cached)

        try:
            import requests

            response = requests.get(f"{self.ollama_url}/api/tags", timeout=8)
            if response.status_code == 200:
                payload = response.json() or {}
                names = [
                    str(m.get("name", "")).strip()
                    for m in payload.get("models", [])
                    if str(m.get("name", "")).strip()
                ]
                self._cached_installed_models = names
                self._cached_installed_models_at = datetime.now()
                return names
        except Exception as e:
            self.logger.debug(f"Unable to fetch installed Ollama models: {e}")

        return list(cached or [])

    @staticmethod
    def _find_installed_model_name(
        candidate: str, installed: List[str]
    ) -> Optional[str]:
        """Resolve configured model name to an installed model name when possible."""
        if not candidate:
            return None
        candidate_norm = str(candidate).strip().lower()
        if not candidate_norm:
            return None

        # 1) Exact case-insensitive match
        for installed_name in installed:
            if str(installed_name).strip().lower() == candidate_norm:
                return installed_name

        # 2) Prefix match (e.g. configured llama3.2-vision, installed llama3.2-vision:latest)
        for installed_name in installed:
            lowered = str(installed_name).strip().lower()
            if lowered.startswith(candidate_norm + ":"):
                return installed_name

        return None

    def _resolve_vl_model_candidates(self) -> List[str]:
        """Resolve and prioritize overnight VL models."""
        installed = self._get_installed_ollama_models()
        configured = list(self.vl_enabled_models or [])
        resolved: List[str] = []

        for name in configured:
            installed_match = self._find_installed_model_name(name, installed)
            resolved_name = installed_match or str(name).strip()
            if not self._looks_like_vision_model(resolved_name):
                self.logger.warning(
                    f"Skipping non-vision VL model candidate: {resolved_name}"
                )
                continue
            if resolved_name not in resolved:
                resolved.append(resolved_name)

        if self.vl_include_all_installed_vision_models and installed:
            installed_vision = [
                m for m in installed if self._looks_like_vision_model(m)
            ]
            for name in installed_vision:
                if name not in resolved:
                    resolved.append(name)

        if not resolved:
            # Hard fallback list if config and discovery both fail.
            resolved = [
                "llama3.2-vision:latest",
                "qwen2.5vl:7b",
                "qwen3-vl:8b",
            ]

        if not self.vl_fallback_enabled and resolved:
            return [resolved[0]]
        return resolved

    def _apply_regime_discovery_profile(self) -> None:
        """Apply regime-specific overnight discovery behavior."""
        regime = str(self.current_regime or "neutral").lower()
        overrides = (
            self.regime_strategy_overrides
            if isinstance(self.regime_strategy_overrides, dict)
            else {}
        )
        scan_types = overrides.get("scan_types") or []
        self.regime_scan_types = [str(s).lower() for s in scan_types if s]

        # In crash/capitulation, completely disable new discovery (only manage existing positions)
        self.disable_new_discovery = regime in ("crash", "capitulation")
        if self.disable_new_discovery:
            self.max_discovery_batch = 0
        elif regime in ("selloff", "distribution"):
            self.max_discovery_batch = 80  # Legacy setting (no longer enforced in overnight - informational only)
        elif regime in ("rotation",):
            self.max_discovery_batch = 120  # Legacy setting (no longer enforced in overnight - informational only)
        else:
            self.max_discovery_batch = 200  # Legacy setting (no longer enforced in overnight - informational only)

        # NOTE: During overnight with 11+ hours, we now research ALL screener results (not capped).
        # max_discovery_batch is kept for logging/state reporting only.
        # The only enforced cap is disable_new_discovery=True (crash/capitulation).

        # Regime-aware screener scoring mode selection.
        #
        # `momentum_pullback` uses hardcoded weights (RS 30%, RSI pullback 25%,
        #   volume 20%, trend 15%, SR 10%) — good when momentum is reliable.
        # `complex` uses configurable YAML weights and includes extra factors
        #   (regime_score, divergence alpha) — better when direction is unclear
        #   or sector rotation matters.
        #
        # Mapping:
        #   strong_rally, grinding_up → momentum_pullback (momentum working, ride it)
        #   recovery, neutral, rotation → complex (multi-factor needed)
        #   distribution, selloff, short_squeeze → complex (mean_reversion territory)
        #   crash, capitulation → N/A (discovery disabled)
        _MOMENTUM_REGIMES = {"strong_rally", "grinding_up"}
        _COMPLEX_REGIMES = {
            "recovery",
            "neutral",
            "rotation",
            "distribution",
            "selloff",
            "short_squeeze",
        }

        if regime in _MOMENTUM_REGIMES:
            self.regime_scoring_mode = "momentum_pullback"
        elif regime in _COMPLEX_REGIMES:
            self.regime_scoring_mode = "complex"
        elif (
            "mean_reversion" in self.regime_scan_types
            and "momentum_breakout" not in self.regime_scan_types
        ):
            # Fallback for unknown regimes: use scan_types hint
            self.regime_scoring_mode = "complex"
        else:
            self.regime_scoring_mode = "momentum_pullback"

    def _load_eod_feedback(self) -> Dict:
        """Load latest EOD feedback to bias research."""
        feedback_path = PROJECT_DIR / "data" / "eod_feedback_latest.json"
        if feedback_path.exists():
            try:
                with open(feedback_path) as f:
                    feedback = json.load(f)
                feedback_date = str(feedback.get("date", "") or "").strip()
                if feedback_date:
                    now = get_market_now()
                    freshness_anchor = now.date()
                    if now.weekday() < 5 and now.hour < 16:
                        freshness_anchor = freshness_anchor - timedelta(days=1)
                    expected_date = last_trading_day(freshness_anchor).strftime(
                        "%Y-%m-%d"
                    )
                    if feedback_date != expected_date:
                        self.logger.warning(
                            "   [FEEDBACK] Ignoring stale feedback dated %s (expected latest completed session %s)",
                            feedback_date,
                            expected_date,
                        )
                        return {}
                self.logger.info(
                    f"   [FEEDBACK] Loaded latest feedback from {feedback.get('date')} "
                    f"(Win Rate: {feedback.get('win_rate', 0):.1%})"
                )
                return feedback
            except Exception as e:
                self.logger.warning(f"Failed to load EOD feedback: {e}")
        return {}

    def _load_market_intelligence(self) -> Optional[Dict]:
        """Load today's YouTube market intelligence report."""
        rag_dir = PROJECT_DIR / "data" / "youtube" / "rag" / "daily_reports"

        # Try today first, then yesterday (overnight runs after market close)
        for offset in [0, 1]:
            date_str = (datetime.now() - timedelta(days=offset)).strftime("%Y-%m-%d")
            report_path = rag_dir / f"{date_str}_consolidated.json"
            if report_path.exists():
                try:
                    with open(report_path) as f:
                        report = json.load(f)
                    self.logger.info(
                        f"   [YOUTUBE] Loaded intelligence report for {date_str}"
                    )
                    return report
                except Exception as e:
                    self.logger.warning(
                        f"Failed to parse YouTube report {report_path}: {e}"
                    )

        self.logger.warning("   [YOUTUBE] No market intelligence report available")
        return None

    def _apply_intelligence_to_screening(self, report: Dict) -> Dict:
        """Apply market intelligence to stock screening parameters."""
        signals = report.get("trading_signals", {})
        smallcap = report.get("smallcap_health", {})
        regime = report.get("regime", {})

        adjustments = {
            # Position sizing multiplier (0.0 = no new positions, 1.5 = aggressive)
            "position_size_multiplier": signals.get("position_sizing_multiplier", 1.0),
            # Sector filtering
            "avoid_sectors": [
                s["sector"]
                for s in signals.get("sector_bias", [])
                if s.get("bias") == "AVOID"
            ],
            "prefer_sectors": [
                s["sector"]
                for s in signals.get("sector_bias", [])
                if s.get("bias") == "OVERWEIGHT"
            ],
            # Candidate count (fewer in risk-off)
            "candidate_target": (
                int(
                    (report.get("overnight_directives", {}) or {}).get(
                        "candidate_count_target", 50
                    )
                )
                if isinstance(report.get("overnight_directives", {}), dict)
                else 50
            ),
            # Screening bias
            "screening_bias": report.get("overnight_directives", {}).get(
                "screening_bias", "momentum"
            ),
            # Small-cap health check
            "smallcap_ok": smallcap.get("iwm_status") in ("HEALTHY", "NEUTRAL"),
            # Overall regime
            "regime": regime.get("classification", "NEUTRAL"),
            "regime_confidence": regime.get("confidence", 50),
        }

        # CRITICAL: If regime is RISK-OFF or CRASH, dramatically reduce activity
        classification = str(adjustments["regime"]).upper()
        if classification in ("RISK-OFF", "CRASH"):
            adjustments["position_size_multiplier"] = min(
                adjustments["position_size_multiplier"], 0.25
            )
            adjustments["candidate_target"] = min(adjustments["candidate_target"], 5)
            self.logger.warning(
                f"   [YOUTUBE] {classification} detected: sizing={adjustments['position_size_multiplier']}, "
                f"candidates={adjustments['candidate_target']}"
            )

        elif classification == "RISK-OFF-LIGHT":
            adjustments["position_size_multiplier"] = min(
                adjustments["position_size_multiplier"], 0.5
            )
            adjustments["candidate_target"] = min(adjustments["candidate_target"], 8)

        return adjustments

    def _refresh_quantitative_regime(self):
        """Refresh quantitative regime snapshot for overnight research controls."""
        if not self.regime_detector:
            self.current_regime = "neutral"
            self.regime_strategy_overrides = {}
            self._apply_regime_discovery_profile()
            return None

        try:
            analysis = self.regime_detector.detect_regime(use_cache=True)
            self.current_regime = analysis.regime.value
            self.current_regime_analysis = analysis
            self.regime_strategy_overrides = analysis.recommended_strategy or {}
            self._apply_regime_discovery_profile()
            self.logger.info(
                "[REGIME] Overnight regime=%s (confidence %.0f%%, breadth %.1f%%) "
                "scan_mode=%s max_discovery_batch=%s disable_discovery=%s",
                str(self.current_regime).upper(),
                analysis.confidence * 100.0,
                analysis.breadth_pct_positive,
                self.regime_scoring_mode,
                self.max_discovery_batch,
                self.disable_new_discovery,
            )
            return analysis
        except Exception as e:
            self.logger.warning(f"[REGIME] Overnight detection failed: {e}")
            self.current_regime = "neutral"
            self.current_regime_analysis = None
            self.regime_strategy_overrides = {}
            self._apply_regime_discovery_profile()
            return None

    # ===== CHART INDEX METHODS =====

    def _load_charts_index(self) -> Dict:
        """Load the charts index from disk."""
        if self.CHARTS_INDEX_PATH.exists():
            try:
                with open(self.CHARTS_INDEX_PATH, encoding="utf-8") as f:
                    return json.load(f)
            except Exception as e:
                self.logger.warning(f"Failed to load charts index: {e}")
        return {}

    def _save_charts_index(self):
        """Save the charts index to disk."""
        try:
            with open(self.CHARTS_INDEX_PATH, "w", encoding="utf-8") as f:
                json.dump(self.charts_index, f, indent=2, default=str)
        except Exception as e:
            self.logger.error(f"Failed to save charts index: {e}")

    def _cleanup_old_charts(self) -> int:
        """
        Delete charts older than CHART_RETENTION_DAYS.
        Returns count of deleted files.
        """
        deleted = 0
        cutoff = datetime.now() - timedelta(days=self.CHART_RETENTION_DAYS)

        # Clean up files
        for chart_file in self.CHARTS_DIR.glob("*.png"):
            try:
                # Parse date from filename (e.g., AAPL_20260202.png or ADAM_20260307_VLM.png)
                parts = chart_file.stem.split("_")
                if len(parts) >= 2:
                    date_str = parts[-1]
                    # For VLM charts, date is parts[1] not parts[-1]
                    if len(date_str) != 8 and len(parts) >= 3:
                        date_str = parts[1]
                    if len(date_str) == 8:  # YYYYMMDD format
                        file_date = datetime.strptime(date_str, "%Y%m%d")
                        if file_date < cutoff:
                            chart_file.unlink()
                            deleted += 1
            except Exception:
                pass

        # Clean up index entries for deleted files
        to_remove = []
        for key, info in self.charts_index.items():
            path = Path(info.get("path", ""))
            if not path.exists():
                to_remove.append(key)

        for key in to_remove:
            del self.charts_index[key]

        if to_remove:
            self._save_charts_index()

        return deleted

    def chart_exists_today(self, symbol: str) -> bool:
        """Check if we already have today's chart for this symbol."""
        today = datetime.now().strftime("%Y%m%d")
        key = f"{symbol}_{today}"

        if key in self.charts_index:
            path = Path(self.charts_index[key].get("path", ""))
            if path.exists():
                return True
        return False

    def get_chart_analysis(self, symbol: str) -> Optional[Dict]:
        """Get VL analysis for a symbol's chart if it exists."""
        today = datetime.now().strftime("%Y%m%d")
        key = f"{symbol}_{today}"

        if key in self.charts_index:
            return self.charts_index[key].get("vl_analysis")
        return None

    def _register_chart(self, symbol: str, path: Path, vl_analysis: Dict = None):
        """Register a chart in the index with its VL analysis."""
        today = datetime.now().strftime("%Y%m%d")
        key = f"{symbol}_{today}"

        self.charts_index[key] = {
            "symbol": symbol,
            "path": str(path),
            "created_at": datetime.now().isoformat(),
            "vl_analysis": vl_analysis,
        }
        self._save_charts_index()

    def _prepare_vl_image_base64(self, chart_path: Path) -> str:
        """Encode chart image for VL model, with optional lightweight preprocessing."""
        import base64

        image_bytes = chart_path.read_bytes()
        if self.vl_preprocess_mode != "normalize":
            return base64.b64encode(image_bytes).decode("utf-8")

        try:
            from io import BytesIO
            from PIL import Image, ImageEnhance, ImageOps

            with Image.open(chart_path) as img:
                # Normalize contrast/clarity for better OCR-like indicator reading.
                prepared = ImageOps.autocontrast(img.convert("L"))
                prepared = ImageEnhance.Contrast(prepared).enhance(1.15)
                prepared = ImageEnhance.Sharpness(prepared).enhance(1.20)
                buf = BytesIO()
                prepared.save(buf, format="PNG")
                return base64.b64encode(buf.getvalue()).decode("utf-8")
        except Exception as e:
            self.logger.debug(f"VL preprocessing fallback to raw image: {e}")
            return base64.b64encode(image_bytes).decode("utf-8")

    @staticmethod
    def _extract_json_object(
        content: str,
    ) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:
        """Extract the first balanced JSON object from model output."""
        text = str(content or "")
        start = text.find("{")
        if start < 0:
            return None, "no_json_object_found"
        depth = 0
        for i, ch in enumerate(text[start:]):
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    candidate = text[start : start + i + 1]
                    try:
                        parsed = json.loads(candidate)
                    except Exception as e:
                        return None, f"json_parse_error:{e}"
                    if not isinstance(parsed, dict):
                        return None, "json_payload_not_object"
                    return parsed, None
        return None, "unbalanced_json_object"

    def _normalize_vl_analysis_payload(
        self, payload: Dict[str, Any]
    ) -> Tuple[Dict[str, Any], List[str]]:
        """Normalize and validate VL payload against expected overnight schema."""
        errors: List[str] = []
        normalized: Dict[str, Any] = {}

        trend_raw = str(payload.get("trend", "")).strip().lower()
        trend_map = {
            "bull": "bullish",
            "bullish": "bullish",
            "uptrend": "bullish",
            "upward": "bullish",
            "bear": "bearish",
            "bearish": "bearish",
            "downtrend": "bearish",
            "downward": "bearish",
            "neutral": "neutral",
            "sideways": "neutral",
            "range": "neutral",
        }
        trend = trend_map.get(trend_raw, trend_raw)
        if trend not in {"bullish", "bearish", "neutral"}:
            errors.append(f"invalid_trend:{trend_raw}")
            trend = "neutral"
        normalized["trend"] = trend

        pattern = payload.get("pattern")
        normalized["pattern"] = str(pattern).strip() if pattern is not None else None

        entry_raw = str(payload.get("entry_signal", "")).strip().lower()
        if "breakout" in entry_raw:
            entry_signal = "breakout"
        elif "bounce" in entry_raw:
            entry_signal = "bounce"
        elif "reversal" in entry_raw:
            entry_signal = "reversal"
        elif "momentum" in entry_raw:
            entry_signal = "momentum"
        elif entry_raw in {"none", "no", "null", ""}:
            entry_signal = "none"
        else:
            errors.append(f"invalid_entry_signal:{entry_raw}")
            entry_signal = "none"
        normalized["entry_signal"] = entry_signal

        rec_raw = str(payload.get("recommendation", "")).strip().lower()
        if "buy" in rec_raw:
            recommendation = "buy"
        elif "sell" in rec_raw or "short" in rec_raw:
            recommendation = "sell"
        elif "hold" in rec_raw:
            recommendation = "hold"
        elif "wait" in rec_raw or "avoid" in rec_raw or "neutral" in rec_raw:
            recommendation = "wait"
        else:
            errors.append(f"invalid_recommendation:{rec_raw}")
            recommendation = "wait"
        normalized["recommendation"] = recommendation

        conf_raw = payload.get("confidence")
        confidence: Optional[float] = None
        if isinstance(conf_raw, (int, float)):
            confidence = float(conf_raw)
        elif isinstance(conf_raw, str):
            token = conf_raw.strip().replace("%", "")
            try:
                confidence = float(token)
            except Exception:
                confidence = None
        if confidence is None:
            errors.append("invalid_confidence")
            confidence = 50.0
        if 0.0 <= confidence <= 1.0:
            confidence = confidence * 100.0
        if confidence < 0.0 or confidence > 100.0:
            errors.append(f"confidence_out_of_range:{confidence}")
            confidence = max(0.0, min(100.0, confidence))
        normalized["confidence"] = float(confidence)

        reasoning = str(payload.get("reasoning", "") or "").strip()
        if len(reasoning) < 12:
            errors.append("reasoning_too_short")
        normalized["reasoning"] = reasoning

        macd_raw = str(payload.get("macd_status", "")).strip().lower()
        if macd_raw:
            if "bullish_cross" in macd_raw or "bull cross" in macd_raw:
                normalized["macd_status"] = "bullish_cross"
            elif "bearish_cross" in macd_raw or "bear cross" in macd_raw:
                normalized["macd_status"] = "bearish_cross"
            elif "bullish" in macd_raw:
                normalized["macd_status"] = "bullish"
            elif "bearish" in macd_raw:
                normalized["macd_status"] = "bearish"
            else:
                normalized["macd_status"] = macd_raw

        rsi_raw = str(payload.get("rsi_status", "")).strip().lower()
        if rsi_raw:
            if "oversold" in rsi_raw:
                normalized["rsi_status"] = "oversold"
            elif "overbought" in rsi_raw:
                normalized["rsi_status"] = "overbought"
            else:
                normalized["rsi_status"] = "neutral"

        vwap_raw = str(payload.get("vwap_position", "")).strip().lower()
        if vwap_raw:
            normalized["vwap_position"] = "above" if "above" in vwap_raw else "below"

        normalized["support_resistance"] = payload.get("support_resistance")
        return normalized, errors

    def _analyze_chart_with_vl(
        self, chart_path: Path, symbol: str, backtest: Dict = None
    ) -> Dict:
        """
        Analyze a chart using a Vision-Language model for ACTIONABLE trading signals.

        Uses VLChartValidator for professional, high-fidelity technical analysis.
        """
        validator = self._get_vl_validator()
        if not validator:
            return {
                "trend": "unknown",
                "recommendation": "hold",
                "confidence": 50,
                "reasoning": "VL validator not available",
                "analyzed": False,
            }

        try:
            # Building SR context from backtest
            sr_context = backtest if backtest else {}

            # This calls the internal analysis via Ollama with optimized prompting
            # and proper image handling.
            result = validator.validate_with_vl_confirmation(symbol, sr_data=sr_context)

            # Log results for consistency with old behavior
            pattern = result.get("pattern", "none")
            entry = result.get("entry_signal", "none")
            trend = result.get("trend", "neutral")
            conf = result.get("confidence", 50)

            if result.get("vl_used", False):
                self.logger.info(f"   VL: {trend} | {pattern} | {entry} ({conf:.0f}%)")

            return result

        except Exception as e:
            self.logger.error(f"VL analysis failed for {symbol}: {e}")
            return {
                "trend": "unknown",
                "recommendation": "hold",
                "confidence": 50,
                "reasoning": f"Analysis failed: {e}",
                "analyzed": False,
            }

    def _load_tools_index(self) -> Dict:
        """Load the tools index from disk."""
        if self.TOOLS_INDEX_PATH.exists():
            try:
                with open(self.TOOLS_INDEX_PATH) as f:
                    index = json.load(f)

                # Migrate absolute paths to project-relative paths
                migrated = False
                for name, info in index.items():
                    raw_path = info.get("path")
                    if not raw_path:
                        continue
                    path = Path(raw_path)

                    # Normalize to project-relative paths when possible
                    if path.is_absolute():
                        candidate = path
                        if not candidate.exists():
                            candidate = PROJECT_DIR / "tools" / path.name
                        if candidate.exists():
                            try:
                                info["path"] = str(
                                    candidate.resolve().relative_to(PROJECT_DIR)
                                )
                                migrated = True
                            except ValueError:
                                info["path"] = str(candidate.resolve())
                                migrated = True
                    else:
                        candidate = PROJECT_DIR / path
                        if not candidate.exists():
                            fallback = PROJECT_DIR / "tools" / path.name
                            if fallback.exists():
                                info["path"] = str(
                                    fallback.resolve().relative_to(PROJECT_DIR)
                                )
                                migrated = True

                if migrated:
                    self.tools_index = index
                    self._save_tools_index()

                return index
            except Exception as e:
                self.logger.warning(f"Failed to load tools index: {e}")
        return {}

    def _resolve_tool_path(self, raw_path: str) -> Path:
        """Resolve a tool path to an absolute path."""
        path = Path(raw_path)
        if path.is_absolute():
            return path
        return (PROJECT_DIR / path).resolve()

    def _normalize_tool_path(self, path: Path) -> str:
        """Convert a tool path to project-relative when possible."""
        try:
            return str(path.resolve().relative_to(PROJECT_DIR))
        except ValueError:
            return str(path.resolve())

    def _save_tools_index(self):
        """Save the tools index to disk."""
        try:
            with open(self.TOOLS_INDEX_PATH, "w", encoding="utf-8") as f:
                json.dump(self.tools_index, f, indent=2, default=str)
        except Exception as e:
            self.logger.error(f"Failed to save tools index: {e}")

    def register_tool(
        self, name: str, description: str, path: Path, category: str = "analysis"
    ) -> bool:
        """
        Register a tool in the index.

        Args:
            name: Tool name (e.g., 'quick_lookup')
            description: What the tool does
            path: Path to the tool file
            category: Tool category (analysis, scanner, utility, etc.)

        Returns:
            True if newly registered, False if already exists
        """
        if name in self.tools_index:
            return False

        self.tools_index[name] = {
            "description": description,
            "path": self._normalize_tool_path(path),
            "category": category,
            "created_at": datetime.now().isoformat(),
            "last_used": None,
            "usage_count": 0,
        }
        self._save_tools_index()
        self.logger.info(f"Registered tool: {name}")
        return True

    def tool_exists(self, name: str) -> bool:
        """Check if a tool exists in the index."""
        if name not in self.tools_index:
            return False
        # Also verify the file exists
        path = self._resolve_tool_path(self.tools_index[name]["path"])
        return path.exists()

    def get_tool(self, name: str) -> Optional[Dict]:
        """Get tool info from the index."""
        if name in self.tools_index:
            tool = self.tools_index[name]
            # Update usage stats
            tool["last_used"] = datetime.now().isoformat()
            tool["usage_count"] = tool.get("usage_count", 0) + 1
            self._save_tools_index()
            resolved = dict(tool)
            resolved["path"] = str(self._resolve_tool_path(tool["path"]))
            return resolved
        return None

    def list_tools(self, category: str = None) -> List[Dict]:
        """List all available tools, optionally filtered by category."""
        tools = []
        for name, info in self.tools_index.items():
            if category is None or info.get("category") == category:
                tools.append(
                    {
                        "name": name,
                        **info,
                        "exists": self._resolve_tool_path(info["path"]).exists(),
                    }
                )
        return tools

    def find_tool_for_task(self, task_description: str) -> Optional[str]:
        """
        Find an existing tool that might help with a task.
        Uses simple keyword matching.
        """
        task_lower = task_description.lower()

        for name, info in self.tools_index.items():
            desc_lower = info.get("description", "").lower()
            # Check for keyword overlap
            if any(word in task_lower for word in desc_lower.split() if len(word) > 4):
                if Path(info["path"]).exists():
                    return name
        return None

    def _update_workflow_state_flag(self, flag_name: str) -> None:
        """Update data/workflow_state.json with completed runtime phase flags."""
        # Use DATA_DIR from autotrade.core.autonomous_agent namespace
        ws_path = DATA_DIR / "workflow_state.json"
        try:
            state: Dict[str, Any] = {}
            if ws_path.exists():
                with open(ws_path) as f:
                    loaded = json.load(f)
                if isinstance(loaded, dict):
                    state = loaded

            today = datetime.now().strftime("%Y-%m-%d")
            if state.get("last_date") != today:
                state["daily_flags"] = {}
                state["last_date"] = today

            state.setdefault("daily_flags", {})[str(flag_name)] = True
            state["last_checkpoint_at"] = datetime.now().isoformat()

            with open(ws_path, "w") as f:
                json.dump(state, f, indent=2)

        except Exception as e:
            self.logger.warning(f"Failed to update workflow state: {e}")

    def _get_vl_validator(self) -> Optional[Any]:
        """Lazy load VL chart validator."""
        if self._vl_validator is None:
            self.logger.info(
                "[VL] Overnight visual validation disabled; validator will not load"
            )
        self._vl_validator = None
        return None

    def run_full_overnight_cycle(self, pm_plan_path: Path = None) -> Dict:
        """
        Run the COMPLETE overnight research cycle.

        This is the HEAVY LIFTING workflow that:
        1. Scans for new entry candidates (with SMA 200 filter)
        2. Runs backtests on each pick
        3. Generates charts with VL analysis
        4. Researches market outlook
        5. Analyzes sector rotation
        6. Creates final game plan with confidence scores

        NOTE: The Post-Market workflow is now just a lightweight daily review.
        """
        self.logger.info("=" * 60)
        self.logger.info("[OVERNIGHT] FULL RESEARCH CYCLE STARTING")
        self.logger.info("=" * 60)

        # Cleanup old charts first (7-day retention)
        cleaned = self._cleanup_old_charts()
        if cleaned > 0:
            self.logger.info(f"   Cleaned up {cleaned} old chart(s)")

        report = {
            "started_at": datetime.now().isoformat(),
            "signals_generated": 0,
            "sma200_filtered": 0,
            "picks_analyzed": 0,
            "backtests_run": 0,
            "charts_generated": 0,
            "charts_cached": 0,
            "vl_analyses": 0,
            "market_outlook": {},
            "sector_analysis": {},
            "picks_breakdown": [],
            "game_plan": {},
            "tools_created": [],
            "completed_at": None,
        }
        lessons_payload: Dict[str, Any] = {}
        target_date: Optional[str] = None

        # === STEP 0: YouTube Intelligence ===
        self.logger.info("\n[YOUTUBE] Loading market intelligence...")
        self.logger.info("-" * 50)
        intel = self._load_market_intelligence()
        adjustments = {}
        if intel:
            adjustments = self._apply_intelligence_to_screening(intel)
            regime = adjustments.get("regime", "NEUTRAL")
            self.logger.info(
                f"   [OVERNIGHT] Market regime: {regime}, "
                f"sizing: {adjustments.get('position_size_multiplier', 1.0)}x, "
                f"target: {adjustments.get('candidate_target', 15)} candidates"
            )

            # If CRASH regime, skip scanning entirely
            if str(regime).upper() == "CRASH":
                self.logger.warning(
                    "   [OVERNIGHT] CRASH regime detected - skipping candidate generation"
                )
                report["completed_at"] = datetime.now().isoformat()
                return report

        # === STEP 1: GENERATE ENTRY SIGNALS ===
        # This was moved from PM Workflow to here (overnight is for heavy scanning)
        self.logger.info("\n[SIGNAL GENERATION] Scanning for entry candidates...")
        self.logger.info("-" * 50)

        # Load feedback to apply bias
        feedback = self._load_eod_feedback()
        min_score_bias = 0.0
        if feedback and feedback.get("win_rate", 1.0) < 0.35:
            min_score_bias = 5.0
            self.logger.warning(
                f"   [BIAS] Underperforming win rate ({feedback.get('win_rate'):.1%}); "
                f"raising min_score by +{min_score_bias}"
            )

        picks = []
        try:
            from autotrade.signals.agentic_signal_generator import (
                AgenticSignalGenerator,
            )

            # Get base config min score
            from config.config_loader import get_config

            base_min_score = float(get_config().signal_generation.min_composite_score)

            # Use adjustments from YouTube intelligence
            max_cands = int(adjustments.get("candidate_target", 50))
            adjustments.get("avoid_sectors", [])
            adjustments.get("prefer_sectors", [])

            signal_gen = AgenticSignalGenerator(
                max_candidates=max_cands,
                use_llm=True,
                use_lessons=True,
                parent_logger=self.logger,
                min_score=base_min_score + min_score_bias,
            )
            raw_candidates = signal_gen.run()

            if raw_candidates:
                # v0.13.0: Apply Regime-Adaptive Strategy Routing
                try:
                    from autotrade.signals.regime_router import RegimeRouter

                    router = RegimeRouter(parent_logger=self.logger)

                    # 1. Filter by allowed strategy families for current regime
                    current_regime = adjustments.get("regime", "neutral")
                    raw_candidates = router.filter_allowed_strategies(
                        current_regime, raw_candidates
                    )

                    # 2. Apply sector bias from intelligence (updates scores)
                    raw_candidates = router.apply_sector_bias(
                        adjustments, raw_candidates
                    )
                except Exception as e:
                    self.logger.warning(f"Regime routing failed: {e}")

                # === STEP 1.1: Alpha Extension (PEAD/Squeeze) ===
                try:
                    from autotrade.signals.alpha_pead import PEADAlphaSource
                    from autotrade.signals.alpha_squeeze import SqueezeAlphaSource
                    from autotrade.signals.agentic_signal_generator import (
                        EntryCandidate,
                    )

                    pead_source = PEADAlphaSource(parent_logger=self.logger)
                    squeeze_source = SqueezeAlphaSource(parent_logger=self.logger)

                    # Generate and convert to EntryCandidate for compatibility
                    extended_candidates = []

                    pead_signals = pead_source.generate_signals()
                    for sig in pead_signals:
                        extended_candidates.append(
                            EntryCandidate(
                                symbol=sig.ticker,
                                price=sig.entry_price or 0.0,
                                final_score=sig.score,
                                action=sig.action.value
                                if hasattr(sig.action, "value")
                                else str(sig.action),
                                momentum_score=sig.score,  # Placeholder
                                catalyst_note=sig.reason,
                                strategy_id=sig.strategy_id,
                                strategy_params=sig.strategy_params,
                            )
                        )

                    squeeze_signals = squeeze_source.generate_signals()
                    for sig in squeeze_signals:
                        extended_candidates.append(
                            EntryCandidate(
                                symbol=sig.ticker,
                                price=sig.entry_price or 0.0,
                                final_score=sig.score,
                                action=sig.action.value
                                if hasattr(sig.action, "value")
                                else str(sig.action),
                                momentum_score=sig.score,
                                catalyst_note=sig.reason,
                                strategy_id=sig.strategy_id,
                                strategy_params=sig.strategy_params,
                            )
                        )

                    # 3. Inverse ETF Hedging (Phase 5)
                    from autotrade.signals.alpha_inverse_etf import (
                        InverseETFAlphaSource,
                    )

                    hedge_source = InverseETFAlphaSource(parent_logger=self.logger)
                    hedge_signals = hedge_source.generate_signals(current_regime)
                    for sig in hedge_signals:
                        extended_candidates.append(
                            EntryCandidate(
                                symbol=sig.ticker,
                                price=sig.entry_price or 0.0,
                                final_score=sig.score,
                                action=sig.action.value
                                if hasattr(sig.action, "value")
                                else str(sig.action),
                                momentum_score=sig.score,
                                catalyst_note=sig.reason,
                                strategy_id=sig.strategy_id,
                                strategy_params=sig.strategy_params,
                            )
                        )

                    if extended_candidates:
                        self.logger.info(
                            f"   Adding {len(extended_candidates)} extended alpha candidates (PEAD/Squeeze)"
                        )
                        raw_candidates.extend(extended_candidates)
                        # Re-sort after extension
                        raw_candidates.sort(key=lambda x: x.final_score, reverse=True)
                except Exception as e:
                    self.logger.warning(f"Alpha extension failed: {e}")

                # Apply SMA 200 filter to avoid wasting resources on weak stocks
                picks = self._filter_by_sma200(raw_candidates)
                report["signals_generated"] = len(raw_candidates)
                report["sma200_filtered"] = len(raw_candidates) - len(picks)

                signal_gen.print_summary(picks)
                from autotrade.utils.market_time import next_trading_day

                target_date = next_trading_day(datetime.now().date()).strftime(
                    "%Y-%m-%d"
                )
                signal_gen.save_signals(
                    picks,
                    target_date=target_date,
                    source="overnight_signal_generation",
                )
                self.logger.info(
                    f"   Generated {len(raw_candidates)} candidates, {len(picks)} passed SMA 200 filter"
                )
            else:
                self.logger.warning("   No signals generated")

        except Exception as e:
            self.logger.error(f"   Signal generation failed: {e}")
            # Fallback to existing signals if generation fails
            signals_path = (
                LOG_DIR / f"signals_{datetime.now().strftime('%Y-%m-%d')}.json"
            )
            if signals_path.exists():
                with open(signals_path) as f:
                    picks = json.load(f)[:15]
                self.logger.info(f"   Loaded {len(picks)} existing signals as fallback")

        # Limit to top 30 for deep analysis
        picks = picks[:30] if picks else []
        # Lessons-based prioritization (prefer missed opportunities, avoid repeat losers)
        picks, lessons_payload = self._apply_daily_lessons_prioritization(
            picks, lessons_payload
        )
        # Verify catalysts with SearXNG-backed news aggregator
        picks = self._enrich_with_news_catalysts(picks)

        # === STEP 2: Research Market Outlook ===
        self.logger.info("\n[MARKET] Researching Outlook...")
        report["market_outlook"] = self._research_market_outlook()

        # === STEP 3: Analyze Sectors ===
        self.logger.info("\n[SECTORS] Analyzing Rotation...")
        report["sector_analysis"] = self._analyze_sectors()

        # === STEP 4: Backtest and Analyze Each Pick ===
        for i, pick in enumerate(picks):
            # Extract symbol from dict, EntryCandidate, or string
            if isinstance(pick, dict):
                symbol = pick.get("symbol", pick.get("ticker"))
            elif hasattr(pick, "symbol"):
                symbol = pick.symbol  # EntryCandidate or similar dataclass
            else:
                symbol = str(pick) if pick else None

            if not symbol:
                continue

            self.logger.info(f"\n[PICK {i + 1}/{len(picks)}] Analyzing: {symbol}")

            pick_analysis = {
                "symbol": symbol,
                "backtest": None,
                "chart_path": None,
                "vl_analysis": None,  # Vision-Language model analysis
                "technical_analysis": None,
                "sentiment": None,
                "confidence": 0,
            }

            # Run backtest
            backtest = self._backtest_symbol(symbol)
            pick_analysis["backtest"] = backtest
            if backtest:
                report["backtests_run"] += 1

            # Generate chart + VL analysis (now returns tuple)
            chart_path, vl_analysis = self._generate_chart(symbol, backtest)
            pick_analysis["chart_path"] = str(chart_path) if chart_path else None
            pick_analysis["vl_analysis"] = vl_analysis
            pick_analysis["vl_reliable"] = bool(
                isinstance(vl_analysis, dict)
                and vl_analysis.get("analyzed")
                and vl_analysis.get("schema_valid")
            )
            if chart_path:
                report["charts_generated"] += 1

            # Log VL analysis if available
            if vl_analysis:
                trend = vl_analysis.get("trend", "unknown")
                vl_conf = vl_analysis.get("confidence", 0)
                self.logger.info(f"   VL Analysis: {trend} (confidence: {vl_conf}%)")

            # Technical analysis
            pick_analysis["technical_analysis"] = self._technical_analysis(symbol)

            # Calculate confidence score (0-100) - now includes VL analysis
            pick_analysis["confidence"] = self._calculate_confidence(
                pick_analysis, report["market_outlook"]
            )

            report["picks_breakdown"].append(pick_analysis)
            report["picks_analyzed"] += 1

        # 4. Generate Tools if needed
        report["tools_created"] = self._generate_analysis_tools()

        # 5. Create Final Game Plan
        self.logger.info("\n[GAME PLAN] Generating...")
        report["game_plan"] = self._generate_game_plan(report)
        report["pm_report"] = self._build_pm_report(picks, lessons_payload, target_date)

        report["completed_at"] = datetime.now().isoformat()

        # Save report
        report_path = (
            self.RESEARCH_DIR
            / f"overnight_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
        )
        with open(report_path, "w") as f:
            json.dump(report, f, indent=2, default=str)

        self._update_workflow_state_flag("overnight_ran")

        self.logger.info(
            f"\n[DONE] Overnight cycle complete! Report: {report_path.name}"
        )
        self._print_summary(report)

        return report

    def _research_market_outlook(self) -> Dict:
        """Research general market outlook using SearXNG + Ollama."""
        import requests

        outlook = {
            "sp500_sentiment": "neutral",
            "vix_level": "unknown",
            "key_events": [],
            "economic_calendar": [],
            "overall_bias": "neutral",
            "summary": "",
        }

        # Search for market outlook
        queries = [
            "stock market outlook tomorrow",
            "S&P 500 futures premarket",
            "VIX volatility index today",
            "market moving events tomorrow",
        ]

        articles = []
        for query in queries:
            try:
                response = requests.get(
                    f"{self.searxng_url}/search",
                    params={"q": query, "format": "json", "categories": "news"},
                    timeout=10,
                )
                if response.status_code == 200:
                    results = response.json().get("results", [])[:3]
                    articles.extend(
                        [
                            {
                                "title": r.get("title", ""),
                                "content": r.get("content", "")[:500],
                            }
                            for r in results
                        ]
                    )
            except Exception as e:
                self.logger.debug(f"Search failed for '{query}': {e}")

        if not articles:
            outlook["summary"] = "Could not fetch market outlook - search unavailable"
            return outlook

        # Use Ollama to analyze
        articles_text = "\n".join(
            [f"- {a['title']}: {a['content']}" for a in articles[:8]]
        )
        prompt = f"""/no_think
Analyze these market news articles and provide tomorrow's market outlook:

{articles_text}

Return ONLY valid JSON:
{{"sp500_sentiment": "bullish/bearish/neutral", "vix_level": "low/moderate/high/unknown", "key_events": ["event1", "event2"], "economic_calendar": ["event1"], "overall_bias": "bullish/bearish/neutral", "summary": "2-3 sentence summary"}}"""

        try:
            response = requests.post(
                f"{self.ollama_url}/api/chat",
                json={
                    "model": "qwen3:8b",
                    "messages": [{"role": "user", "content": prompt}],
                    "stream": False,
                    "think": False,
                    "options": {"num_predict": 500},
                },
                timeout=45,
            )

            if response.status_code == 200:
                content = response.json().get("message", {}).get("content", "")
                # Extract JSON
                start = content.find("{")
                if start >= 0:
                    depth = 0
                    for i, c in enumerate(content[start:]):
                        if c == "{":
                            depth += 1
                        elif c == "}":
                            depth -= 1
                            if depth == 0:
                                outlook = json.loads(content[start : start + i + 1])
                                break
        except Exception as e:
            self.logger.error(f"Ollama analysis failed: {e}")
            outlook["summary"] = f"Analysis failed: {e}"

        self.logger.info(f"   Market bias: {outlook.get('overall_bias', 'unknown')}")
        return outlook

