    def _backtest_symbol(self, symbol: str) -> Dict:
        """Run lightweight local-data backtest for a specific symbol."""
        backtest = {
            "symbol": symbol,
            "trades": 0,
            "win_rate": 0,
            "avg_pnl": 0,
            "total_pnl": 0,
            "exit_breakdown": {},
            "has_data": False,
        }

        try:
            import pandas as pd

            closes = None

            # Prefer local parquet-backed history.
            provider = None
            try:
                from autotrade.utils.local_data_provider import get_provider

                provider = get_provider()
            except Exception:
                provider = None
            if provider and provider.has_ticker(symbol):
                hist = provider.get_ticker_data(
                    symbol, days=120, include_features=False
                )
                if hist is not None and not hist.empty:
                    close_col = "Adj Close" if "Adj Close" in hist.columns else "Close"
                    if close_col in hist.columns:
                        closes = pd.to_numeric(
                            hist[close_col], errors="coerce"
                        ).dropna()

            # Fallback: short yfinance history if local ticker is unavailable.
            if closes is None or len(closes) < 30:
                try:
                    import yfinance as yf

                    yf_hist = yf.Ticker(symbol).history(period="6mo")
                    if (
                        yf_hist is not None
                        and not yf_hist.empty
                        and "Close" in yf_hist.columns
                    ):
                        closes = pd.to_numeric(
                            yf_hist["Close"], errors="coerce"
                        ).dropna()
                except Exception:
                    closes = closes if closes is not None else pd.Series(dtype=float)

            if closes is None or len(closes) < 30:
                return backtest

            # Rolling fixed-horizon forward return proxy (5 trading days).
            hold_days = 5
            pnl_values: List[float] = []
            for idx in range(0, len(closes) - hold_days):
                entry = float(closes.iloc[idx])
                exit_price = float(closes.iloc[idx + hold_days])
                if entry <= 0:
                    continue
                pnl_values.append(((exit_price - entry) / entry) * 100.0)

            if len(pnl_values) < 5:
                return backtest

            pnl = pd.Series(pnl_values, dtype=float)
            backtest["has_data"] = True
            backtest["trades"] = int(len(pnl))
            backtest["win_rate"] = float((pnl > 0).mean() * 100.0)
            backtest["avg_pnl"] = float(pnl.mean())
            backtest["total_pnl"] = float(pnl.sum())
            backtest["exit_breakdown"] = {"close_5d": int(len(pnl))}

            self.logger.info(
                f"   Backtest: {backtest['trades']} trades, "
                f"{backtest['win_rate']:.0f}% win rate, {backtest['avg_pnl']:.2f}% avg"
            )

        except Exception as e:
            self.logger.error(f"   Backtest failed for {symbol}: {e}")

        return backtest

    def _generate_chart(
        self, symbol: str, backtest: Dict = None
    ) -> Tuple[Optional[Path], Optional[Dict]]:
        """
        Generate a chart image for the overnight pipeline.

        Visual validation stays disabled at runtime; this restores chart output
        without enabling any vision-model path.

        Returns:
            (chart_path, vl_analysis) tuple
        """
        try:
            chart_path = generate_vlm_chart(symbol, days=60, force=False)
            if not chart_path:
                self.logger.warning(
                    f"[CHART] Chart generation returned no file for {symbol}"
                )
                return None, None

            self._register_chart(symbol, chart_path)
            self.logger.info(f"[CHART] Generated chart for {symbol}: {chart_path.name}")
            return chart_path, None
        except Exception as exc:
            self.logger.error(f"[CHART] Chart generation failed for {symbol}: {exc}")
            return None, None

