    def _technical_analysis(self, symbol: str) -> Dict:
        """Basic technical analysis for a symbol."""
        analysis = {
            "trend": "unknown",
            "support": 0,
            "resistance": 0,
            "rsi": 50,
            "volume_trend": "unknown",
        }

        try:
            import yfinance as yf

            stock = yf.Ticker(symbol)
            hist = stock.history(period="1mo")

            if hist.empty:
                return analysis

            closes = hist["Close"]
            volumes = hist["Volume"]

            # Trend (simple: above/below 20-day MA)
            if len(closes) >= 20:
                ma20 = closes.rolling(20).mean().iloc[-1]
                current = closes.iloc[-1]
                analysis["trend"] = "bullish" if current > ma20 else "bearish"

            # Support/Resistance (recent lows/highs)
            analysis["support"] = float(hist["Low"].tail(10).min())
            analysis["resistance"] = float(hist["High"].tail(10).max())

            # RSI (14-period)
            if len(closes) >= 15:
                delta = closes.diff()
                gain = (delta.where(delta > 0, 0)).rolling(14).mean()
                loss = (-delta.where(delta < 0, 0)).rolling(14).mean()
                rs = gain / loss
                rsi = 100 - (100 / (1 + rs))
                analysis["rsi"] = float(rsi.iloc[-1]) if not rsi.empty else 50

            # Volume trend
            if len(volumes) >= 10:
                recent_vol = volumes.tail(5).mean()
                older_vol = volumes.tail(10).head(5).mean()
                analysis["volume_trend"] = (
                    "increasing"
                    if recent_vol > older_vol * 1.1
                    else "decreasing"
                    if recent_vol < older_vol * 0.9
                    else "stable"
                )

        except Exception as e:
            self.logger.debug(f"   Technical analysis failed: {e}")

        return analysis

    def _calculate_confidence(self, pick_analysis: Dict, market_outlook: Dict) -> int:
        """Calculate confidence score (0-100) for a pick, including VL analysis."""
        score = 50  # Base score

        # Backtest contribution (+/- 25)
        backtest = pick_analysis.get("backtest", {})
        if backtest.get("has_data"):
            win_rate = backtest.get("win_rate", 50)
            avg_pnl = backtest.get("avg_pnl", 0)

            # Win rate bonus
            if win_rate >= 60:
                score += 15
            elif win_rate >= 50:
                score += 5
            else:
                score -= 10

            # PnL bonus
            if avg_pnl > 1:
                score += 10
            elif avg_pnl > 0:
                score += 5
            else:
                score -= 5

        # Technical analysis contribution (+/- 15)
        tech = pick_analysis.get("technical_analysis", {})
        if tech.get("trend") == "bullish":
            score += 10
        elif tech.get("trend") == "bearish":
            score -= 10

        rsi = tech.get("rsi", 50)
        if 40 <= rsi <= 60:  # Neutral zone
            score += 5
        elif rsi < 30:  # Oversold
            score += 8
        elif rsi > 70:  # Overbought
            score -= 8

        # VL (Vision-Language) analysis contribution (+/- 25)
        vl = pick_analysis.get("vl_analysis", {})
        vl_reliable = bool(pick_analysis.get("vl_reliable", True))
        vl_schema_valid = (
            bool(vl.get("schema_valid", True)) if isinstance(vl, dict) else False
        )
        vl_analyzed = bool(vl.get("analyzed", False)) if isinstance(vl, dict) else False
        if vl and vl_reliable and vl_schema_valid and vl_analyzed:
            vl_trend = vl.get("trend", "").lower()
            vl_confidence = vl.get("confidence", 0)
            vl_rec = vl.get("recommendation", "").lower()
            entry_signal = vl.get("entry_signal", "").lower()

            # VL trend contribution
            if "bullish" in vl_trend:
                score += 8
            elif "bearish" in vl_trend:
                score -= 8

            # Entry signal is the KEY indicator (+/- 12)
            if entry_signal in ["breakout", "bounce", "gap", "reversal"]:
                score += 12  # Actionable pattern found
            elif entry_signal == "none" or not entry_signal:
                score -= 5  # No clear entry

            # VL recommendation contribution
            if "buy" in vl_rec:
                score += 5
            elif "sell" in vl_rec or "wait" in vl_rec:
                score -= 5

            # VL confidence modifies impact
            if vl_confidence >= 75:
                score += 5  # High VL confidence bonus
            elif vl_confidence < 40:
                score -= 3  # Low VL confidence penalty

        # Market outlook contribution (+/- 10)
        bias = market_outlook.get("overall_bias", "neutral")
        if bias == "bullish":
            score += 10
        elif bias == "bearish":
            score -= 10

        # Clamp to 0-100
        return max(0, min(100, score))

