    def _filter_by_sma200(self, candidates: List) -> List:
        """
        Filter candidates to only include stocks trading ABOVE their SMA 200.

        This is critical for avoiding wasted resources - we don't want to
        scan/analyze stocks that are in a long-term downtrend.

        Data priority:
        1. LocalDataProvider (DownDay parquet) - fastest, 4453 tickers
        2. yfinance API - fallback for tickers not in local data

        Args:
            candidates: List of signal candidates (dicts or signal objects)

        Returns:
            Filtered list of candidates above SMA 200
        """
        if not candidates:
            return []

        # Extract symbols
        symbols = []
        for c in candidates:
            if isinstance(c, dict):
                sym = c.get("symbol", c.get("ticker"))
            elif hasattr(c, "symbol"):
                sym = c.symbol
            else:
                sym = str(c)
            if sym:
                symbols.append(sym.upper())

        if not symbols:
            return candidates

        self.logger.info(f"   Checking SMA 200 filter for {len(symbols)} candidates...")

        entry_cfg = get_config().entry_quality
        relax_if_zero = bool(getattr(entry_cfg, "sma200_relax_if_zero_pass", True))
        relax_max_below_pct = float(
            getattr(entry_cfg, "sma200_relax_max_below_pct", 3.0)
        )

        passed_filter = set()
        near_sma_symbols = set()
        failed_symbols = []

        # Try LocalDataProvider first (fastest)
        try:
            from autotrade.utils.local_data_provider import get_provider, bulk_sma_check

            provider = get_provider()

            # Check which symbols have local data
            local_symbols = [s for s in symbols if provider.has_ticker(s)]
            api_symbols = [s for s in symbols if not provider.has_ticker(s)]

            if local_symbols:
                self.logger.info(
                    f"   Using local data for {len(local_symbols)} symbols"
                )

                # Bulk SMA check from local parquet (very fast)
                results = bulk_sma_check(local_symbols, period=200)

                for symbol, data in results.items():
                    if data.get("sma") is None:
                        failed_symbols.append(symbol)
                        continue

                    if data.get("above_sma"):
                        passed_filter.add(symbol)
                        self.logger.debug(
                            f"   {symbol}: ${data['price']:.2f} > SMA200 ${data['sma']:.2f} (local)"
                        )
                    else:
                        pct_below = ((data["sma"] - data["price"]) / data["sma"]) * 100
                        if pct_below <= relax_max_below_pct:
                            near_sma_symbols.add(symbol)
                        self.logger.info(
                            f"   {symbol}: FILTERED - ${data['price']:.2f} < SMA200 ${data['sma']:.2f} "
                            f"(-{pct_below:.1f}%)"
                        )

            # Fallback to yfinance for symbols not in local data
            if api_symbols:
                self.logger.info(
                    f"   Falling back to yfinance for {len(api_symbols)} symbols"
                )
                self._sma200_yfinance_batch(
                    api_symbols,
                    passed_filter,
                    failed_symbols,
                    near_sma_symbols=near_sma_symbols,
                    relax_max_below_pct=relax_max_below_pct,
                )

        except ImportError:
            # LocalDataProvider not available, use yfinance
            self.logger.warning("   LocalDataProvider not available, using yfinance")
            self._sma200_yfinance_batch(
                symbols,
                passed_filter,
                failed_symbols,
                near_sma_symbols=near_sma_symbols,
                relax_max_below_pct=relax_max_below_pct,
            )
        except Exception as e:
            self.logger.warning(
                f"   LocalDataProvider error: {e}, falling back to yfinance"
            )
            self._sma200_yfinance_batch(
                symbols,
                passed_filter,
                failed_symbols,
                near_sma_symbols=near_sma_symbols,
                relax_max_below_pct=relax_max_below_pct,
            )

        # If too many failed, log a summary
        if len(failed_symbols) > 10:
            self.logger.warning(
                f"   {len(failed_symbols)} symbols had insufficient data for SMA 200"
            )

        # Filter the original candidates
        filtered = []
        for c in candidates:
            if isinstance(c, dict):
                sym = c.get("symbol", c.get("ticker"))
            elif hasattr(c, "symbol"):
                sym = c.symbol
            else:
                sym = str(c)

            if sym and sym.upper() in passed_filter:
                filtered.append(c)

        self.logger.info(
            f"   SMA 200 strict filter: {len(filtered)}/{len(candidates)} passed"
        )
        if filtered:
            return filtered

        if not relax_if_zero:
            return filtered

        if near_sma_symbols:
            relaxed = []
            for c in candidates:
                if isinstance(c, dict):
                    sym = c.get("symbol", c.get("ticker"))
                elif hasattr(c, "symbol"):
                    sym = c.symbol
                else:
                    sym = str(c)
                if sym and sym.upper() in near_sma_symbols:
                    relaxed.append(c)

            if relaxed:
                self.logger.warning(
                    "   SMA 200 strict filter produced 0/%d passes; relaxing to %d stocks within %.1f%% below SMA 200",
                    len(candidates),
                    len(relaxed),
                    relax_max_below_pct,
                )
                return relaxed

        self.logger.warning(
            "   SMA 200 strict filter produced 0/%d passes; bypassing filter for this cycle",
            len(candidates),
        )
        return candidates

    def _sma200_yfinance_batch(
        self,
        symbols: List[str],
        passed_filter: set,
        failed_symbols: List[str],
        near_sma_symbols: Optional[set] = None,
        relax_max_below_pct: float = 0.0,
    ):
        """Batch SMA 200 check using yfinance API."""
        try:
            import yfinance as yf

            batch_size = 20
            for i in range(0, len(symbols), batch_size):
                batch = symbols[i : i + batch_size]

                for symbol in batch:
                    try:
                        ticker = yf.Ticker(symbol)
                        hist = ticker.history(period="1y")

                        if hist.empty or len(hist) < 200:
                            self.logger.debug(
                                f"   {symbol}: Not enough yfinance data "
                                f"({len(hist) if not hist.empty else 0} bars)"
                            )
                            failed_symbols.append(symbol)
                            continue

                        closes = hist["Close"].values
                        sma200 = float(closes[-200:].mean())
                        current_price = float(closes[-1])

                        if current_price > sma200:
                            passed_filter.add(symbol)
                            self.logger.debug(
                                f"   {symbol}: ${current_price:.2f} > SMA200 ${sma200:.2f} (yfinance)"
                            )
                        else:
                            pct_below = ((sma200 - current_price) / sma200) * 100
                            if (
                                near_sma_symbols is not None
                                and pct_below <= relax_max_below_pct
                            ):
                                near_sma_symbols.add(symbol)
                            self.logger.info(
                                f"   {symbol}: FILTERED - ${current_price:.2f} < SMA200 ${sma200:.2f} "
                                f"(-{pct_below:.1f}%)"
                            )

                    except Exception as e:
                        self.logger.debug(f"   {symbol}: yfinance error - {e}")
                        # On error, give benefit of doubt and include
                        passed_filter.add(symbol)

        except ImportError:
            self.logger.error("   yfinance not available - cannot check SMA 200")

    def _apply_daily_lessons_prioritization(
        self, picks: List, lessons_payload: Dict[str, Any]
    ) -> tuple[List, Dict[str, Any]]:
        """
        Apply the structured daily learning state as a hard gate.
        """
        if not picks:
            return picks, lessons_payload

        try:
            from autotrade.utils.daily_learning_state import (
                apply_learning_gates,
                load_learning_state,
            )

            lessons_payload = lessons_payload or {}
            learning_state = load_learning_state()
            if not learning_state:
                lessons_payload.setdefault("daily_learning", {})
                lessons_payload["daily_learning"]["state_loaded"] = False
                return picks, lessons_payload

            picks, gate_report = apply_learning_gates(picks, learning_state)
            lessons_payload["daily_learning"] = {
                "state_loaded": True,
                "as_of_date": learning_state.get("as_of_date"),
                "artifact_status": learning_state.get("learning_artifact_status", {}),
                "blocked_symbols": learning_state.get("active_rules", {}).get(
                    "blocked_symbols", []
                ),
                "preferred_symbols": learning_state.get("active_rules", {}).get(
                    "preferred_symbols", []
                ),
                "blocked_setup_types": learning_state.get("active_rules", {}).get(
                    "blocked_setup_types", []
                ),
                "blocked_sectors": learning_state.get("active_rules", {}).get(
                    "blocked_sectors", []
                ),
                "min_candidate_score": learning_state.get("active_rules", {}).get(
                    "min_candidate_score", 0.0
                ),
                "boosted_symbols": learning_state.get("active_rules", {}).get(
                    "boosted_symbols", []
                ),
                "preferred_setup_keywords": learning_state.get("active_rules", {}).get(
                    "preferred_setup_keywords", []
                ),
                "gate_report": gate_report,
            }
        except Exception as exc:
            self.logger.warning(
                f"[LESSONS] Could not apply lessons prioritization: {exc}"
            )

        return picks, lessons_payload

    def _enrich_with_news_catalysts(self, picks: List) -> List:
        """
        Use NewsAggregator (SearXNG fallback) to flag catalysts and sentiment.
        """
        if not picks:
            return picks

        try:
            from autotrade.utils.news_aggregator import NewsAggregator

            aggregator = NewsAggregator(headline_limit=3)
        except Exception as exc:
            self.logger.warning(f"[NEWS] News aggregation unavailable: {exc}")
            return picks

        for cand in picks:
            try:
                snapshot = aggregator.collect(getattr(cand, "symbol", ""))
                cand.metadata = getattr(cand, "metadata", {}) or {}
                cand.metadata["news_snapshot"] = snapshot
                cand.has_catalyst = bool(
                    snapshot.get("has_catalyst", cand.has_catalyst)
                )
                cand.catalyst_note = snapshot.get("catalyst_note", cand.catalyst_note)
                cand.news_sentiment = snapshot.get(
                    "sentiment_score", cand.news_sentiment
                )
                if snapshot.get("has_catalyst"):
                    cand.final_score = min(100.0, float(cand.final_score) + 2.0)
            except Exception as exc:
                self.logger.debug(f"[NEWS] Skipping news enrichment for {cand}: {exc}")
                continue

        picks.sort(key=lambda c: float(getattr(c, "final_score", 0.0)), reverse=True)
        return picks

    def _build_pm_report(
        self, picks: List, lessons_payload: Dict[str, Any], target_date: Optional[str]
    ) -> Dict[str, Any]:
        """
        Provide a compact, standardized overnight handoff payload.
        """
        top_entries = []
        for cand in picks[:20]:
            tag = getattr(cand, "metadata", {}).get("daily_lessons_tag")
            news_meta = getattr(cand, "metadata", {}).get("news_snapshot", {})
            top_entries.append(
                {
                    "symbol": getattr(cand, "symbol", ""),
                    "score": float(getattr(cand, "final_score", 0.0)),
                    "has_catalyst": bool(getattr(cand, "has_catalyst", False)),
                    "lesson_tag": tag,
                    "news_coverage": news_meta.get("coverage"),
                    "news_headlines": news_meta.get("headlines", []),
                }
            )

        return {
            "date": target_date or datetime.now().strftime("%Y-%m-%d"),
            "lessons_date": lessons_payload.get("date", ""),
            "prefer_symbols": lessons_payload.get("prefer_symbols", []),
            "avoid_symbols": lessons_payload.get("avoid_symbols", []),
            "top_entries": top_entries,
            "generated_at": datetime.now().isoformat(),
            "source": "overnight_engine",
        }

    def _generate_game_plan(self, report: Dict) -> Dict:
        """Generate the final game plan with prioritized actions, including VL confirmation."""
        game_plan = {
            "market_bias": report["market_outlook"].get("overall_bias", "neutral"),
            "sector_focus": report["sector_analysis"].get("hot_sectors", []),
            "avoid_sectors": report["sector_analysis"].get("cold_sectors", []),
            "top_picks": [],
            "vl_confirmed": [],  # Picks where VL analysis confirms the signal
            "watch_only": [],
            "avoid": [],
            "strategy_notes": [],
            "risk_level": "moderate",
        }

        # Sort picks by confidence
        picks = sorted(
            report["picks_breakdown"],
            key=lambda x: x.get("confidence", 0),
            reverse=True,
        )

        for pick in picks:
            symbol = pick["symbol"]
            confidence = pick["confidence"]
            backtest = pick.get("backtest", {})
            vl = pick.get("vl_analysis", {})
            if not bool(pick.get("vl_reliable", True)):
                vl = {}
            tech = pick.get("technical_analysis", {})

            entry = {
                "symbol": symbol,
                "confidence": confidence,
                "win_rate": backtest.get("win_rate", 0),
                "avg_pnl": backtest.get("avg_pnl", 0),
                "trend": tech.get("trend", "unknown"),
                "vl_trend": vl.get("trend", "N/A") if vl else "N/A",
                "vl_recommendation": vl.get("recommendation", "N/A") if vl else "N/A",
                "vl_confidence": vl.get("confidence", 0) if vl else 0,
            }

            # Check if VL confirms the technical signal
            vl_confirms = False
            if vl:
                vl_trend = vl.get("trend", "").lower()
                vl_rec = vl.get("recommendation", "").lower()
                vl_conf = vl.get("confidence", 0)
                tech_trend = tech.get("trend", "").lower()

                # VL confirms if same direction with decent confidence
                if "bullish" in tech_trend or tech_trend == "uptrend":
                    if (
                        "bullish" in vl_trend
                        or "uptrend" in vl_trend
                        or "buy" in vl_rec
                    ) and vl_conf >= 50:
                        vl_confirms = True
                elif "bearish" in tech_trend or tech_trend == "downtrend":
                    if (
                        "bearish" in vl_trend
                        or "downtrend" in vl_trend
                        or "sell" in vl_rec
                    ) and vl_conf >= 50:
                        vl_confirms = True

            entry["vl_confirmed"] = vl_confirms

            if confidence >= 70:
                game_plan["top_picks"].append(entry)
                if vl_confirms:
                    game_plan["vl_confirmed"].append(entry)
            elif confidence >= 50:
                game_plan["watch_only"].append(entry)
            else:
                game_plan["avoid"].append(entry)

        # Strategy notes based on market conditions
        bias = game_plan["market_bias"]
        if bias == "bullish":
            game_plan["strategy_notes"].append(
                "Market bullish - full position sizes OK"
            )
            game_plan["strategy_notes"].append(
                "Look for breakout entries on high-confidence picks"
            )
            game_plan["risk_level"] = "moderate-high"
        elif bias == "bearish":
            game_plan["strategy_notes"].append(
                "Market bearish - reduce position sizes by 30%"
            )
            game_plan["strategy_notes"].append(
                "Focus on defensive plays and tight stops"
            )
            game_plan["risk_level"] = "low"
        else:
            game_plan["strategy_notes"].append(
                "Market neutral - standard position sizes"
            )
            game_plan["strategy_notes"].append("Wait for clear setups before entering")

        # Add VL confirmation note
        if game_plan["vl_confirmed"]:
            game_plan["strategy_notes"].append(
                f"VL-CONFIRMED PICKS: {', '.join([p['symbol'] for p in game_plan['vl_confirmed']])}"
            )
            game_plan["strategy_notes"].append(
                "Prioritize VL-confirmed picks - visual pattern matches signal"
            )

        # Add sector-based notes
        if game_plan["sector_focus"]:
            game_plan["strategy_notes"].append(
                f"Focus on: {', '.join(game_plan['sector_focus'][:3])}"
            )
        if game_plan["avoid_sectors"]:
            game_plan["strategy_notes"].append(
                f"Avoid: {', '.join(game_plan['avoid_sectors'][:3])}"
            )

        return game_plan

    def _print_summary(self, report: Dict):
        """Log a human-readable summary of the overnight research.

        Uses logger instead of raw print() to avoid OSError on Windows
        when concurrent threads write to the console.
        """
        sep = "=" * 60
        lines = [f"\n{sep}", "OVERNIGHT RESEARCH SUMMARY", sep]

        # Market outlook
        outlook = report.get("market_outlook", {})
        lines.append(
            f"\nMARKET OUTLOOK: {outlook.get('overall_bias', 'unknown').upper()}"
        )
        lines.append(f"   {outlook.get('summary', 'No summary available')}")

        # Sectors
        sectors = report.get("sector_analysis", {})
        if sectors.get("hot_sectors"):
            lines.append(f"\n[HOT] SECTORS: {', '.join(sectors['hot_sectors'])}")
        if sectors.get("cold_sectors"):
            lines.append(f"[COLD] SECTORS: {', '.join(sectors['cold_sectors'])}")

        # VL-Confirmed Picks (highest priority)
        game_plan = report.get("game_plan", {})
        if game_plan.get("vl_confirmed"):
            lines.append(
                f"\n[VL-CONFIRMED] TOP PICKS ({len(game_plan['vl_confirmed'])}):"
            )
            for pick in game_plan["vl_confirmed"][:5]:
                lines.append(
                    f"   {pick['symbol']:6} - Conf: {pick['confidence']}%, VL: {pick['vl_trend']} ({pick['vl_confidence']}%)"
                )

        # Regular top picks
        if game_plan.get("top_picks"):
            non_vl = [p for p in game_plan["top_picks"] if not p.get("vl_confirmed")]
            if non_vl:
                lines.append(f"\n[+] TOP PICKS (non-VL confirmed: {len(non_vl)}):")
                for pick in non_vl[:5]:
                    lines.append(
                        f"   {pick['symbol']:6} - Confidence: {pick['confidence']}%, Win Rate: {pick['win_rate']:.0f}%"
                    )

        if game_plan.get("watch_only"):
            lines.append(f"\n[WATCH] ({len(game_plan['watch_only'])}):")
            for pick in game_plan["watch_only"][:3]:
                lines.append(
                    f"   {pick['symbol']:6} - Confidence: {pick['confidence']}%"
                )

        # Strategy
        lines.append(
            f"\n[STRATEGY] ({game_plan.get('risk_level', 'moderate').upper()} RISK):"
        )
        for note in game_plan.get("strategy_notes", []):
            lines.append(f"   - {note}")

        # Stats
        lines.append("\n[STATS]:")
        lines.append(f"   Picks Analyzed: {report['picks_analyzed']}")
        lines.append(f"   Backtests Run: {report['backtests_run']}")
        lines.append(f"   Charts Generated: {report['charts_generated']}")
        vl_count = sum(
            1 for p in report.get("picks_breakdown", []) if p.get("vl_analysis")
        )
        lines.append(f"   VL Analyses: {vl_count}")
        if report.get("tools_created"):
            lines.append(f"   Tools Created: {', '.join(report['tools_created'])}")

        lines.append(f"\n{sep}")
        self.logger.info("\n".join(lines))


