    def _screen_technical_setups(self) -> List[Dict]:
        """Screen for stocks with technical setups FROM YOUR PM PLAN."""
        import yfinance as yf

        setups = []

        # Get universe from PM plan (your actual candidates)
        universe = []
        try:
            pm_plan_path = _pm_plan_path()
            if pm_plan_path.exists():
                with open(pm_plan_path) as f:
                    plan = json.load(f)
                for c in plan.get("entry_candidates", [])[:30]:
                    if isinstance(c, dict):
                        price = c.get("price", 0)
                        if 0 < price < 200:  # Your price range
                            universe.append(c.get("symbol", ""))
        except Exception:
            pass

        if not universe:
            return []

        for symbol in universe[:20]:
            try:
                stock = yf.Ticker(symbol)
                hist = stock.history(period="1mo")

                if len(hist) < 10:
                    continue

                close = hist["Close"].iloc[-1]
                ma10 = hist["Close"].rolling(10).mean().iloc[-1]
                ma20 = (
                    hist["Close"].rolling(20).mean().iloc[-1]
                    if len(hist) >= 20
                    else ma10
                )

                # Check for setups
                pattern = None
                confidence = 0

                # Breakout: price above both MAs, MAs trending up
                if close > ma10 > ma20:
                    ma10_trend = (
                        hist["Close"]
                        .rolling(10)
                        .mean()
                        .iloc[-5:]
                        .is_monotonic_increasing
                    )
                    if ma10_trend:
                        pattern = "Breakout"
                        confidence = 70

                # Bounce: price near MA10 from above
                elif abs(close - ma10) / ma10 < 0.02 and close > ma20:
                    pattern = "MA Bounce"
                    confidence = 60

                # Oversold bounce potential
                elif close < ma10 < ma20:
                    # Check RSI
                    delta = hist["Close"].diff()
                    gain = (delta.where(delta > 0, 0)).rolling(14).mean()
                    loss = (-delta.where(delta < 0, 0)).rolling(14).mean()
                    rs = gain / loss
                    rsi = 100 - (100 / (1 + rs)).iloc[-1]
                    if rsi < 35:
                        pattern = "Oversold"
                        confidence = 55

                if pattern:
                    setups.append(
                        {
                            "symbol": symbol,
                            "pattern": pattern,
                            "confidence": confidence,
                            "price": close,
                            "ma10": ma10,
                        }
                    )

            except Exception:
                continue

        # Sort by confidence
        setups.sort(key=lambda x: x["confidence"], reverse=True)
        return setups[:10]

