    def _scan_overnight_news(self) -> Dict:
        """Scan for breaking news using SearXNG."""
        import requests

        results = {
            "articles": [],
            "market_moving": [],
            "scanned_at": datetime.now().isoformat(),
        }

        # Search queries for overnight news
        queries = [
            "stock market news today",
            "breaking financial news",
            "S&P 500 futures overnight",
            "fed interest rate news",
            "earnings reports today",
        ]

        for query in queries[:3]:  # Limit to 3 queries to be fast
            try:
                response = requests.get(
                    f"{self.searxng_url}/search",
                    params={
                        "q": query,
                        "format": "json",
                        "categories": "news",
                        "time_range": "day",
                    },
                    timeout=10,
                )
                if response.status_code == 200:
                    search_results = response.json().get("results", [])[:3]
                    for r in search_results:
                        article = {
                            "title": r.get("title", ""),
                            "content": r.get("content", "")[:300],
                            "url": r.get("url", ""),
                            "source": r.get("engine", ""),
                        }
                        results["articles"].append(article)

                        # Check for market-moving keywords
                        text = (article["title"] + " " + article["content"]).lower()
                        if any(
                            kw in text
                            for kw in [
                                "fed",
                                "rate cut",
                                "rate hike",
                                "crash",
                                "surge",
                                "plunge",
                                "emergency",
                            ]
                        ):
                            results["market_moving"].append(article["title"][:80])

            except Exception:
                continue

        return results

